package com.ascent.climb.data.i18n

/**
 * Banco de preguntas en español, segunda parte (claves nuevas del lote de ampliación).
 * Claves idénticas a PackEnQuiz.kt; cifras, dosis y escalas sin cambios.
 */
internal val PACK_ES_QUIZ_B: Map<String, String> = mapOf(
    // ---------- l1 Entender el riesgo en montaña ----------
    "q.l1#10.p" to "¿Cuál de estos es un peligro subjetivo?",
    "q.l1#10.o0" to "La pérdida de juicio por fatiga",
    "q.l1#10.o1" to "Una caída de piedras",
    "q.l1#10.o2" to "Una grieta",
    "q.l1#10.o3" to "Una tormenta eléctrica",
    "q.l1#10.e" to "Los peligros subjetivos vienen del estado y de las decisiones de las personas: fatiga, prisa, exceso de confianza, presión del grupo. Cuesta más verlos que los objetivos y, aun así, son el punto de partida habitual de los accidentes.",

    "q.l1#11.p" to "¿Por qué un buen equipo no sustituye al juicio sobre el riesgo?",
    "q.l1#11.o0" to "Porque el equipo reduce las consecuencias, no hace desaparecer el peligro",
    "q.l1#11.o1" to "Porque el equipo se rompe",
    "q.l1#11.o2" to "Porque el equipo pesa",
    "q.l1#11.o3" to "Porque el buen equipo es caro",
    "q.l1#11.e" to "El casco, la cuerda y la encordada reducen el daño cuando algo pasa; no hacen desaparecer un alud ni una grieta. Tomar el equipo como amuleto es el sesgo cognitivo más común.",

    "q.l1#12.p" to "¿De qué se compone normalmente un accidente de montaña?",
    "q.l1#12.o0" to "De varias desviaciones pequeñas que se acumulan y que un último suceso detona",
    "q.l1#12.o1" to "De una única decisión equivocada",
    "q.l1#12.o2" to "De simple mala suerte",
    "q.l1#12.o3" to "De una avería repentina del material",
    "q.l1#12.e" to "La forma típica de la cadena es: salir tarde → ir con prisa → saltarse las comprobaciones → encontrar un cambio → quedarse sin margen. Romper cualquier eslabón evita el accidente.",

    "q.l1#13.p" to "Sobre salir solo a la montaña, ¿qué afirmación es la más exacta?",
    "q.l1#13.o0" to "El riesgo sube mucho: pierdes el frenado, el rescate y el segundo par de ojos que te juzga",
    "q.l1#13.o1" to "Con experiencia suficiente no hay problema",
    "q.l1#13.o2" to "Es más seguro que ir encordado",
    "q.l1#13.o3" to "Solo depende del material",
    "q.l1#13.e" to "El riesgo de ir solo no está en la técnica, sino en que nadie puede descubrir por ti que te estás equivocando. Por eso muchas rutas exigen un mínimo de dos personas.",

    "q.l1#14.p" to "¿Qué significa «riesgo = exposición × probabilidad × consecuencia» para el diseño de una salida?",
    "q.l1#14.o0" to "Que puedes bajarlo por tres vías: reducir el tiempo de exposición, reducir la probabilidad y reducir la consecuencia",
    "q.l1#14.o1" to "Que solo depende de la suerte",
    "q.l1#14.o2" to "Que basta con reducir la probabilidad",
    "q.l1#14.o3" to "Que basta con tener seguro",
    "q.l1#14.e" to "De las tres vías, acortar la exposición es la más olvidada y la más eficaz: no detenerse en terreno de aludes, salir de la zona de seracs antes del mediodía.",

    // ---------- l2 Conocer el material: piolet y crampones ----------
    "q.l2#10.p" to "¿Hacia dónde va el uso de la dragonera (leash) del piolet en la escalada técnica actual?",
    "q.l2#10.o0" to "La mayoría ha dejado de usarla; se pasa a una dragonera de seguridad o a no llevarla",
    "q.l2#10.o1" to "Debe usarse siempre",
    "q.l2#10.o2" to "Solo en cascadas de hielo",
    "q.l2#10.o3" to "Solo en pendientes de nieve",
    "q.l2#10.e" to "En una caída la dragonera puede torcerte la muñeca o engancharse. La práctica moderna tiende a «sin dragonera y con un agarre fiable», aunque en largas travesías por nieve todavía tiene su lugar.",

    "q.l2#11.p" to "¿En qué se diferencian los crampones de puntas verticales de los de puntas horizontales?",
    "q.l2#11.o0" to "En la orientación y la forma de las puntas: las verticales van mejor para la técnica de puntas frontales y las horizontales para caminar con el pie plano",
    "q.l2#11.o1" to "En el número de puntas",
    "q.l2#11.o2" to "En el material",
    "q.l2#11.o3" to "En el peso",
    "q.l2#11.e" to "Las puntas verticales entran bien en hielo duro con la técnica frontal; las horizontales encajan en la técnica francesa de pie plano sobre nieve. Elegir mal deforma el gesto técnico.",

    "q.l2#12.p" to "¿Cuál es el efecto más directo de llevar los crampones desafilados?",
    "q.l2#12.o0" to "Cuesta clavarlos, resbalan con facilidad y cansan más",
    "q.l2#12.o1" to "Pesan más",
    "q.l2#12.o2" to "Se oscurecen",
    "q.l2#12.o3" to "No afecta al uso",
    "q.l2#12.e" to "Una punta roma necesita mucha más fuerza para morder el hielo y la fatiga llega antes. Afilar las puntas con lima antes de salir es mantenimiento normal.",

    "q.l2#13.p" to "Al alquilar o pedir prestados unos crampones, ¿qué hay que comprobar primero?",
    "q.l2#13.o0" to "Que encajen con tu bota (automáticos, semiautomáticos o de correas) y que el cierre sea fiable",
    "q.l2#13.o1" to "El color",
    "q.l2#13.o2" to "La marca",
    "q.l2#13.o3" to "Si son nuevos",
    "q.l2#13.e" to "Un crampón automático montado en una bota de suela blanda se sale directamente. La compatibilidad importa más que las prestaciones.",

    "q.l2#14.p" to "Sobre la longitud del piolet, ¿qué afirmación es correcta?",
    "q.l2#14.o0" to "Para caminar por nieve se usa un piolet largo (hasta media espinilla); para la escalada técnica, uno corto",
    "q.l2#14.o1" to "Cuanto más largo, más seguro",
    "q.l2#14.o2" to "Cuanto más corto, menos esfuerzo",
    "q.l2#14.o3" to "No tiene relación con la estatura",
    "q.l2#14.e" to "El largo se usa como bastón; el corto, para las técnicas de golpe. Subir una pendiente larga con un piolet técnico corto te obliga a agacharte cientos de veces en un día.",

    // ---------- l3 Botas de montaña y sistema de capas ----------
    "q.l3#10.p" to "Se ha mojado la bota interior de una bota de doble pared. ¿Qué es lo más razonable?",
    "q.l3#10.o0" to "Sacarla, llevarla pegada al cuerpo o meterla en el saco para que seque; nunca secarla al fuego",
    "q.l3#10.o1" to "Ponértela mojada",
    "q.l3#10.o2" to "Secarla al fuego",
    "q.l3#10.o3" to "Dejarla fuera de la tienda toda la noche",
    "q.l3#10.e" to "Secar con el calor del cuerpo es lo más seguro. El fuego daña la espuma y una noche al hielo la deja igual de rígida al día siguiente.",

    "q.l3#11.p" to "¿Cuál es la combinación correcta de calcetines?",
    "q.l3#11.o0" to "Una capa fina interior que evacúa el sudor y un calcetín grueso de lana por fuera",
    "q.l3#11.o1" to "Un solo calcetín grueso de algodón",
    "q.l3#11.o2" to "Dos calcetines gruesos de algodón",
    "q.l3#11.o3" to "Media y calcetín de algodón",
    "q.l3#11.e" to "Con dos capas la fricción ocurre entre los calcetines, no contra la piel. El algodón se empapa y no seca: es la primera causa de ampollas.",

    "q.l3#12.p" to "¿Para qué sirven principalmente las polainas?",
    "q.l3#12.o0" to "Para que no entre nieve por el empeine y para proteger el bajo del pantalón",
    "q.l3#12.o1" to "Para dar calor",
    "q.l3#12.o2" to "Para no resbalar",
    "q.l3#12.o3" to "Para ganar altura",
    "q.l3#12.e" to "Con nieve profunda y sin polainas, en diez minutos tienes nieve dentro de la bota; después llegan los pies mojados y el riesgo de congelación.",

    "q.l3#13.p" to "¿Qué hay que hacer con unas botas nuevas antes de usarlas?",
    "q.l3#13.o0" to "Domarlas con salidas cortas y localizar los puntos de presión",
    "q.l3#13.o1" to "Estrenarlas en una ruta larga",
    "q.l3#13.o2" to "Meterlas en agua para ablandarlas",
    "q.l3#13.o3" to "Apretarlas al máximo",
    "q.l3#13.e" to "Una bota de alta montaña no se doma en la montaña. Probarla en salidas cortas antes de salir revela los puntos de roce, y eso sirve más que llevar un puñado de apósitos.",

    "q.l3#14.p" to "¿Cuál es el indicio más fiable de que un pie se está enfriando demasiado?",
    "q.l3#14.o0" to "Sensación embotada, movimientos más lentos y color pálido",
    "q.l3#14.o1" to "Que la persona diga que tiene frío",
    "q.l3#14.o2" to "Que los calcetines estén mojados",
    "q.l3#14.o3" to "Que los cordones se hayan aflojado",
    "q.l3#14.e" to "«Tener frío» todavía no es peligroso; «no notar el frío y moverse torpe» sí es un aviso de congelación. Hay que revisar activamente los dedos de los compañeros.",

    // ---------- l4 Fundamentos para caminar por nieve ----------
    "q.l4#8.p" to "¿Para qué sirve el paso de descanso?",
    "q.l4#8.o0" to "Para cargar el peso en cada paso sobre la pierna estirada y dar descanso real a la otra",
    "q.l4#8.o1" to "Para detenerse a descansar",
    "q.l4#8.o2" to "Para ir más despacio",
    "q.l4#8.o3" to "Para cambiar de mano el piolet",
    "q.l4#8.e" to "El paso de descanso hace que las piernas soporten el peso por turnos en lugar de mantener la musculatura en tensión. En pendientes largas de nieve decide si llegas o no.",

    "q.l4#9.p" to "Al cruzar en diagonal una pendiente de nieve dura, ¿qué es correcto?",
    "q.l4#9.o0" to "Pie de aguas abajo abajo y pie de aguas arriba arriba, con el piolet en el lado de arriba",
    "q.l4#9.o1" to "Los dos pies en paralelo",
    "q.l4#9.o2" to "El piolet en el lado de abajo",
    "q.l4#9.o3" to "El cuerpo mirando hacia abajo",
    "q.l4#9.e" to "Con el piolet en el lado de arriba puedes clavarlo para frenar en el acto. Con los pies invertidos, el primer gesto de una caída te hace tropezar contigo mismo.",

    "q.l4#10.p" to "En una pendiente larga y continua, ¿qué forma de subir cansa menos?",
    "q.l4#10.o0" to "En zigzag, repartiendo la pendiente",
    "q.l4#10.o1" to "En línea recta",
    "q.l4#10.o2" to "Corriendo",
    "q.l4#10.o3" to "Saltando de lado",
    "q.l4#10.e" to "El zigzag cambia pendiente por distancia y reduce mucho la altura de cada paso. El precio es más recorrido: hay que calcular el tiempo de antemano.",

    "q.l4#11.p" to "Sientes un pinchazo en la rodilla al bajar. ¿Cuál es la causa más probable?",
    "q.l4#11.o0" to "Zancada demasiado larga y rodilla estirada y bloqueada al apoyar",
    "q.l4#11.o1" to "Botas demasiado blandas",
    "q.l4#11.o2" to "Calcetines demasiado gruesos",
    "q.l4#11.o3" to "Mochila demasiado ligera",
    "q.l4#11.e" to "Al bajar, el impacto es varias veces el de subir. Acortar la zancada y mantener la rodilla ligeramente flexionada es la protección más eficaz.",

    "q.l4#12.p" to "Al hacer escalones en una pendiente de nieve, ¿cómo debe caer el pie?",
    "q.l4#12.o0" to "Con la parte delantera de la suela o todo el pie, formando un escalón horizontal y con la punta un poco levantada",
    "q.l4#12.o1" to "Con la punta clavada en vertical",
    "q.l4#12.o2" to "Con el talón",
    "q.l4#12.o3" to "Con el canto del pie",
    "q.l4#12.e" to "El escalón tiene que ser plano para sostenerse. Con la punta levantada la suela comprime la nieve en horizontal, en lugar de excavar un agujero inclinado.",

    // ---------- l21 Sistema de capas y vestimenta ----------
    "q.l21#10.p" to "En el sistema de tres capas, ¿cuál es la función principal de la capa intermedia?",
    "q.l21#10.o0" to "Retener el calor y, a la vez, dejar salir el vapor del sudor",
    "q.l21#10.o1" to "Cortar el viento",
    "q.l21#10.o2" to "Evacuar el sudor",
    "q.l21#10.o3" to "Impermeabilizar",
    "q.l21#10.e" to "La capa intermedia (forro polar o plumas finas) hace «abrigo + transpiración». Si es demasiado gruesa sudas en la subida; si es demasiado fina, te quedas frío en cuanto paras.",

    "q.l21#11.p" to "¿Cuál es la diferencia principal entre una chaqueta softshell y una hardshell?",
    "q.l21#11.o0" to "La softshell transpira y resiste la abrasión; la hardshell impermeabiliza y corta el viento mucho mejor",
    "q.l21#11.o1" to "La softshell es más cara",
    "q.l21#11.o2" to "La hardshell es más ligera",
    "q.l21#11.o3" to "No hay diferencia",
    "q.l21#11.e" to "Con frío seco, softshell (prioridad a la transpiración); con lluvia, nieve y viento, hardshell (prioridad a la protección). Elegir mal te deja entre sudar empapado o mojarte.",

    "q.l21#12.p" to "¿Cuál es el orden correcto para regular la temperatura mientras caminas?",
    "q.l21#12.o0" to "Abrir primero el cuello y las axilas, luego quitar la capa exterior y solo al final reducir la intermedia",
    "q.l21#12.o1" to "Quedarte solo con la capa de evacuación",
    "q.l21#12.o2" to "Quitar primero la capa intermedia",
    "q.l21#12.o3" to "Parar en el acto y quitarte ropa en cuanto sudas",
    "q.l21#12.e" to "Los ajustes finos funcionan mejor que los cambios grandes: abrir una cremallera baja dos o tres grados. Vestir y desvestir sin parar pierde tiempo y enfría en las pausas.",

    "q.l21#13.p" to "¿Por qué la capa de abrigo de reserva tiene que estar seca?",
    "q.l21#13.o0" to "Porque mojada casi no abriga, y suele usarse justo cuando te ves obligado a parar",
    "q.l21#13.o1" to "Porque se enmohece",
    "q.l21#13.o2" to "Porque pesa más",
    "q.l21#13.o3" to "Porque huele mal",
    "q.l21#13.e" to "La capa de reserva es el seguro para las paradas. Si se moja, deja de funcionar exactamente en el momento en que más la necesitas.",

    "q.l21#14.p" to "¿Qué ventaja tiene una chaqueta de fibra sintética frente a las plumas?",
    "q.l21#14.o0" to "Conserva parte del abrigo aunque se moje",
    "q.l21#14.o1" to "Pesa menos",
    "q.l21#14.o2" to "Abriga más",
    "q.l21#14.o3" to "Es más barata",
    "q.l21#14.e" to "Las plumas mojadas casi no abrigan; la fibra sintética aguanta. En ambientes húmedos la sintética es la opción más segura.",

    // ---------- m01 Ciencia del medio alpino ----------
    "q.m01#13.p" to "Al ganar altitud, ¿cómo cambia el punto de ebullición del agua y qué implica al cocinar?",
    "q.m01#13.o0" to "Baja, la comida se hace peor y se gastan más agua y más combustible",
    "q.m01#13.o1" to "Sube y todo se hace antes",
    "q.m01#13.o2" to "No cambia",
    "q.m01#13.o3" to "Se congela",
    "q.m01#13.e" to "Cerca de 5.000 m el agua hierve a unos 83 °C. El arroz y las legumbres necesitan más tiempo o remojo previo; es una de las razones por las que en altura se prefiere la comida deshidratada.",

    "q.m01#14.p" to "En una noche despejada, ¿por qué dentro de la tienda hace más frío que la temperatura del aire?",
    "q.m01#14.o0" to "El suelo y la tienda irradian calor hacia fuera y se forma escarcha",
    "q.m01#14.o1" to "Porque hay más viento",
    "q.m01#14.o2" to "Porque hay menos oxígeno",
    "q.m01#14.o3" to "Porque la humedad es alta",
    "q.m01#14.e" to "El enfriamiento radiativo nocturno deja la superficie más fría que el aire, y de ahí la escarcha en la pared interior. También es la razón de «guardar el saco lo primero por la mañana».",

    // ---------- m02 Preparación física y nutrición ----------
    "q.m02#10.p" to "¿Qué estructura de entrenamiento es razonable antes de una ascensión?",
    "q.m02#10.o0" to "Base aeróbica como eje, con fuerza y ascensos con carga, subiendo la carga semana a semana",
    "q.m02#10.o1" to "Intervalos de alta intensidad todos los días",
    "q.m02#10.o2" to "Solo fuerza",
    "q.m02#10.o3" to "Solo estiramientos",
    "q.m02#10.e" to "La montaña es un esfuerzo largo y de baja intensidad: la base aeróbica es lo primero. La carga debe ser progresiva y en las dos semanas previas hay que reducir.",

    "q.m02#11.p" to "¿En qué debe centrarse el entrenamiento de las dos semanas previas a la salida?",
    "q.m02#11.o0" to "En reducir volumen, mantener la forma y dormir bien",
    "q.m02#11.o1" to "En aumentar la intensidad",
    "q.m02#11.o2" to "En probar disciplinas nuevas",
    "q.m02#11.o3" to "En parar por completo",
    "q.m02#11.e" to "Subir cansado es usar tu peor estado en el momento en que más lo necesitas. La fase de descarga es parte del entrenamiento, no pereza.",

    "q.m02#12.p" to "Sobre la cafeína en altitud, ¿qué es correcto?",
    "q.m02#12.o0" to "Se puede usar con moderación, pero no sustituye al sueño ni a la hidratación",
    "q.m02#12.o1" to "Cuanta más, más te despeja",
    "q.m02#12.o2" to "Está totalmente prohibida",
    "q.m02#12.o3" to "Sirve para tratar el mal de altura",
    "q.m02#12.e" to "La cafeína mejora un rato la sensación subjetiva de fatiga, pero no cambia la falta de oxígeno. Usarla para aguantar traslada el problema a un momento más tarde y más peligroso.",

    // ---------- m03 Ética ambiental y de campo ----------
    "q.m03#10.p" to "¿Qué distancia se recomienda entre el campamento y el agua?",
    "q.m03#10.o0" to "Más de 60 metros",
    "q.m03#10.o1" to "5 metros",
    "q.m03#10.o2" to "10 metros",
    "q.m03#10.o3" to "Cuanto más cerca, mejor",
    "q.m03#10.e" to "60 metros (unos 70 pasos) es la distancia sanitaria habitual, y vale para evacuar, lavarse y fregar.",

    "q.m03#11.p" to "¿Cuál es la actitud correcta ante el fuego en el campo?",
    "q.m03#11.o0" to "Priorizar el hornillo; si de verdad hace falta fuego, usar un círculo ya existente y apagarlo del todo",
    "q.m03#11.o1" to "Hacer fuego tiene más ambiente",
    "q.m03#11.o2" to "Basta con no provocar un incendio",
    "q.m03#11.o3" to "El fuego ahuyenta a los animales",
    "q.m03#11.e" to "Las marcas de fuego duran años y animan a otros a repetir en el mismo sitio. En época seca una chispa puede provocar un desastre real.",

    "q.m03#12.p" to "Al encontrarte con fauna, ¿qué es razonable?",
    "q.m03#12.o0" to "Mantener distancia, no dar comida, retroceder despacio y no perseguir para fotografiar",
    "q.m03#12.o1" to "Acercarte a hacer fotos",
    "q.m03#12.o2" to "Darles comida para calmarlos",
    "q.m03#12.o3" to "Espantarlos a gritos",
    "q.m03#12.e" to "Dar comida altera el comportamiento de los animales y aumenta el riesgo de conflicto. Mantener la distancia te protege y los protege.",

    // ---------- m04 Meteorología y navegación básicas ----------
    "q.m04#10.p" to "Al mirar el pronóstico, ¿qué importa más que la probabilidad de precipitación?",
    "q.m04#10.o0" to "El viento, la temperatura y la forma de la precipitación (lluvia o nieve) según la altura",
    "q.m04#10.o1" to "Solo la probabilidad de precipitación",
    "q.m04#10.o2" to "Solo la temperatura máxima",
    "q.m04#10.o3" to "Solo la humedad",
    "q.m04#10.e" to "Con la misma cantidad de precipitación, que caiga lluvia o nieve cambia por completo la salida. El viento decide la sensación térmica y si se puede avanzar; la temperatura decide el material.",

    "q.m04#11.p" to "¿Qué patrón meteorológico es habitual en montaña por la tarde?",
    "q.m04#11.o0" to "Aumento de nubosidad, convección y más probabilidad de tormenta y chubascos",
    "q.m04#11.o1" to "Cielo despejado continuo",
    "q.m04#11.o2" to "Viento que amaina",
    "q.m04#11.o3" to "La temperatura baja más deprisa",
    "q.m04#11.e" to "De ahí la regla «salir por la mañana y abandonar el terreno expuesto por la tarde». El diseño de la salida debe seguir ese ritmo.",

    "q.m04#12.p" to "Al estimar la cota de nieve con el gradiente térmico, ¿cuántos grados se bajan por cada 1.000 m?",
    "q.m04#12.o0" to "6,5 °C",
    "q.m04#12.o1" to "2 °C",
    "q.m04#12.o2" to "10 °C",
    "q.m04#12.o3" to "15 °C",
    "q.m04#12.e" to "6,5 °C por 1.000 m es el gradiente medio. Con él se calcula a grandes rasgos la cota de los cero grados y se decide si caerá lluvia o nieve.",

    // ---------- m05 Montañas objetivo: iniciación a la nieve ----------
    "q.m05#10.p" to "¿Por qué es importante la «ventana de temporada» en una montaña nevada de iniciación?",
    "q.m05#10.o0" to "Porque la nieve, el viento y las normas de permiso cambian mucho según la época, y fuera de la ventana la dificultad se duplica",
    "q.m05#10.o1" to "Por el precio de los billetes",
    "q.m05#10.o2" to "Porque hay más gente",
    "q.m05#10.o3" to "Por las horas de luz",
    "q.m05#10.e" to "La misma montaña antes y después del monzón son dos dificultades distintas. Primero se elige la temporada, después la ruta.",

    "q.m05#11.p" to "Al elegir una montaña de iniciación, ¿qué significa «si requiere maniobras técnicas»?",
    "q.m05#11.o0" to "Si hacen falta encordada, aseguramiento, progresión por grietas y técnicas similares",
    "q.m05#11.o1" to "Si hay que pagar entrada",
    "q.m05#11.o2" to "Si hace falta guía",
    "q.m05#11.o3" to "Si hace falta tienda",
    "q.m05#11.e" to "Ahí está la diferencia de fondo entre una montaña de senderismo y una técnica. Para la primera vez en nieve conviene elegir una ruta sin maniobras técnicas.",

    "q.m05#12.p" to "Sobre la «tasa de cumbres», ¿cuál es la interpretación correcta?",
    "q.m05#12.o0" to "Refleja la ventana de buen tiempo y la dificultad de la ruta, pero el criterio estadístico varía mucho entre años",
    "q.m05#12.o1" to "Cuanto más alta, mejor",
    "q.m05#12.o2" to "Cuanto más baja, más segura",
    "q.m05#12.o3" to "No sirve de referencia",
    "q.m05#12.e" to "La tasa de cumbres es información, no una garantía. Al leerla hay que mirar el año, la temporada y si incluye la ayuda de equipos comerciales.",
    // ---------- l5 Técnica de crampones: francesa, alemana, mixta ----------
    "q.l5#10.p" to "La nieve se apelmaza bajo los crampones (balling). ¿Qué es lo más eficaz?",
    "q.l5#10.o0" to "Quitarla golpeando con la punta del piolet y aplicar cera antiadherente, o usar crampones con placa antitaco",
    "q.l5#10.o1" to "Seguir caminando, el calor lo derrite",
    "q.l5#10.o2" to "Golpear el crampón contra un árbol",
    "q.l5#10.o3" to "Quitarte los crampones",
    "q.l5#10.e" to "La nieve apelmazada deja las puntas sin agarre: es como ir descalzo por una pendiente de hielo. Hay que resolverlo en el acto, no esperar al siguiente rellano.",

    "q.l5#11.p" to "Al clavar las puntas frontales, ¿cómo debe estar el tobillo?",
    "q.l5#11.o0" to "Relajado, dejando que las puntas entren verticales en el hielo; sin apretar hacia abajo",
    "q.l5#11.o1" to "Tenso",
    "q.l5#11.o2" to "Con la punta del pie hacia arriba",
    "q.l5#11.o3" to "Apoyando primero el talón",
    "q.l5#11.e" to "La tensión cansa la pantorrilla antes de tiempo y hace que las puntas entren en ángulo. Con el tobillo relajado las puntas muerden en vertical.",

    "q.l5#12.p" to "En hielo duro (hielo azul), ¿por qué no es fiable la técnica francesa de pie plano?",
    "q.l5#12.o0" to "Las puntas horizontales no entran en el hielo duro y el crampón entero patina",
    "q.l5#12.o1" to "Porque es demasiado lenta",
    "q.l5#12.o2" to "Porque cansa demasiado",
    "q.l5#12.o3" to "Porque la postura es fea",
    "q.l5#12.e" to "La técnica francesa se apoya en que toda la fila de puntas presiona sobre la nieve. El hielo duro no cede; ahí hay que pasar a la técnica de puntas frontales.",

    "q.l5#13.p" to "¿Cuál es la ventaja de la técnica francesa en pendientes de nieve blanda?",
    "q.l5#13.o0" to "Ahorra esfuerzo y es rápida; va bien en pendientes largas y suaves",
    "q.l5#13.o1" to "Es más segura",
    "q.l5#13.o2" to "Va mejor en hielo duro",
    "q.l5#13.o3" to "No hace falta piolet",
    "q.l5#13.e" to "La nieve blanda da suficiente superficie de contacto: caminar con el pie plano cansa mucho menos que clavar las puntas frontales una y otra vez. La técnica se elige según la nieve.",

    "q.l5#14.p" to "Al bajar con técnica francesa, ¿cuál es la postura correcta?",
    "q.l5#14.o0" to "Puntas hacia abajo, talón primero, y toda la planta presionando la nieve",
    "q.l5#14.o1" to "Puntas hacia arriba",
    "q.l5#14.o2" to "De lado",
    "q.l5#14.o3" to "Solo con las puntas frontales",
    "q.l5#14.e" to "Al bajar, la clave es que toda la fila de puntas muerda la nieve y el centro de gravedad quede sobre la planta. Apoyar primero el talón es lo que talla el escalón.",

    "q.l5#15.p" to "Al cruzar en diagonal, ¿qué hace el pie del lado de la pendiente?",
    "q.l5#15.o0" to "Muerde con las puntas interiores, con el tobillo inclinado hacia la pendiente",
    "q.l5#15.o1" to "Se apoya plano",
    "q.l5#15.o2" to "Punta hacia abajo",
    "q.l5#15.o3" to "Se levanta del suelo",
    "q.l5#15.e" to "Al cruzar, los dos pies tienen que «morder» la pendiente para formar un apoyo estable. Con el tobillo rígido las puntas solo rozan la superficie.",

    // ---------- l6 Uso del piolet y autorretención ----------
    "q.l6#10.p" to "Al hacer autorretención, ¿dónde se apoya el mango del piolet contra el cuerpo?",
    "q.l6#10.o0" to "Entre el hombro y el pecho, con el peso del cuerpo sobre la cabeza del piolet",
    "q.l6#10.o1" to "En la cintura",
    "q.l6#10.o2" to "Sobre la cabeza",
    "q.l6#10.o3" to "Al costado de la pierna",
    "q.l6#10.e" to "Cuanto más arriba se presiona, mejor se convierte el peso en fuerza de frenado. En la cintura la punta se levanta y la retención no sirve prácticamente de nada.",

    "q.l6#11.p" to "¿Qué es el «agarre de autorretención» (self-arrest grip)?",
    "q.l6#11.o0" to "El pulgar en un lado de la cabeza del piolet y la palma encima, listo para girar a la posición de frenado",
    "q.l6#11.o1" to "Las dos manos al final del mango",
    "q.l6#11.o2" to "Llevar el piolet colgando de una mano",
    "q.l6#11.o3" to "La mano dentro de la dragonera",
    "q.l6#11.e" to "Este agarre permite frenar en el instante de perder el equilibrio sin cambiar de manos. Ese medio segundo de cambio suele ser justo la distancia que te deslizas.",

    "q.l6#12.p" to "¿Cómo influye la calidad de la nieve en la eficacia del frenado?",
    "q.l6#12.o0" to "La nieve blanda frena con facilidad; la dura y el hielo casi no permiten frenar",
    "q.l6#12.o1" to "Cuanto más dura, mejor se frena",
    "q.l6#12.o2" to "No influye",
    "q.l6#12.o3" to "La nieve húmeda es la más resbaladiza",
    "q.l6#12.e" to "El frenado depende de que la punta muerda. En nieve dura solo se araña un surco superficial y en hielo no funciona en absoluto: por eso las pendientes de hielo se aseguran con cuerda fija, no con la autorretención.",

    "q.l6#13.p" to "¿Cuál es el riesgo principal de caer con dragonera (leash)?",
    "q.l6#13.o0" to "Si el piolet se engancha, te tuerce la muñeca o te arrastra hasta perder el control",
    "q.l6#13.o1" to "Que se rompa la dragonera",
    "q.l6#13.o2" to "Perder el piolet",
    "q.l6#13.o3" to "Queda mal estéticamente",
    "q.l6#13.e" to "En una caída la dragonera puede convertirse en un punto de enganche y llevar la muñeca a un ángulo forzado. En terreno técnico se suele sustituir por una dragonera de seguridad.",

    "q.l6#14.p" to "Después de frenar y detenerte, ¿qué es lo primero que hay que hacer?",
    "q.l6#14.o0" to "Comprobar tu posición y la seguridad de los compañeros, y luego revisar lesiones y material",
    "q.l6#14.o1" to "Levantarse de inmediato",
    "q.l6#14.o2" to "Seguir bajando",
    "q.l6#14.o3" to "Recoger primero el piolet",
    "q.l6#14.e" to "Detenerse no es estar a salvo: puedes quedar colgando en la pendiente y puede haber compañeros arrastrados. Primero evaluar, después actuar.",

    "q.l6#15.p" to "¿Por qué «golpear el hielo con la punta del piolet» no es una maniobra de frenado eficaz?",
    "q.l6#15.o0" to "Frenar exige presión sostenida, no un impacto aislado: el golpe hace rebotar el piolet",
    "q.l6#15.o1" to "Porque hace ruido",
    "q.l6#15.o2" to "Porque rompe el piolet",
    "q.l6#15.o3" to "Porque el hielo es demasiado duro",
    "q.l6#15.e" to "Frenar es un proceso de presionar y deslizar perdiendo velocidad. Un impacto suelto solo arranca esquirlas y el cuerpo sigue bajando.",

    // ---------- l22 Material técnico, navegación y comunicación ----------
    "q.l22#10.p" to "¿Cuál es la diferencia esencial entre cuerda doble (media) y cuerda simple?",
    "q.l22#10.o0" to "La doble se va clipando alternando seguros, lo que reduce el roce y el factor de caída, pero complica la maniobra",
    "q.l22#10.o1" to "La doble es más barata",
    "q.l22#10.o2" to "La doble pesa menos",
    "q.l22#10.o3" to "No hay diferencia",
    "q.l22#10.e" to "La doble va bien en rutas sinuosas donde hay que reducir el roce; la simple es más directa y sencilla. La elección depende de la forma de la ruta, no de cuál es «más profesional».",

    "q.l22#11.p" to "¿Qué hay que hacer con un casco tras un impacto claro?",
    "q.l22#11.o0" to "Retirarlo y sustituirlo, aunque parezca intacto",
    "q.l22#11.o1" to "Seguir usándolo",
    "q.l22#11.o2" to "Pegarlo con adhesivo",
    "q.l22#11.o3" to "Cambiar solo el acolchado",
    "q.l22#11.e" to "El casco absorbe energía con la espuma; tras un impacto la estructura interna ya está dañada y no se ve. En un segundo impacto la protección cae mucho.",

    "q.l22#12.p" to "En el uso de walkie-talkies en el grupo, ¿qué es lo más importante?",
    "q.l22#12.o0" to "Canal fijo y reglas de llamada claras, mensajes de posición breves y nada de charla en el canal",
    "q.l22#12.o1" to "Poner el volumen al máximo",
    "q.l22#12.o2" to "Mantener la comunicación abierta todo el rato",
    "q.l22#12.o3" to "Que solo los lleve el jefe de cordada",
    "q.l22#12.e" to "El canal es un recurso compartido. Una charla larga bloquea la llamada de emergencia que de verdad hace falta y agota la batería muy rápido.",

    "q.l22#13.p" to "¿En qué se diferencian un dispositivo satelital (tipo inReach) y un PLB?",
    "q.l22#13.o0" to "El satelital permite comunicación bidireccional; el PLB solo emite una alerta y es exclusivo para emergencias",
    "q.l22#13.o1" to "El PLB puede enviar SMS",
    "q.l22#13.o2" to "Son exactamente iguales",
    "q.l22#13.o3" to "El dispositivo satelital no necesita batería",
    "q.l22#13.e" to "Un PLB registrado lo atienden los servicios de rescate y una activación accidental sale cara; el satelital sirve para avisar de que estás bien y coordinar. Son herramientas con funciones distintas.",

    "q.l22#14.p" to "Con frío la batería se agota muy rápido. ¿Cuál es la medida más práctica?",
    "q.l22#14.o0" to "Llevar las baterías de repuesto pegadas al cuerpo y guardar el dispositivo en un bolsillo interior cuando no lo uses",
    "q.l22#14.o1" to "Llevar varias en el exterior de la mochila",
    "q.l22#14.o2" to "Apagar todas las funciones",
    "q.l22#14.o3" to "Calentarlo con una bolsa de agua caliente",
    "q.l22#14.e" to "Una batería de litio a -20 °C puede quedarse con la mitad de capacidad. Abrigarla funciona mejor que llevar más, porque las de repuesto también pierden carga.",

    "q.l22#15.p" to "¿Cuál es la forma correcta de preparar los mapas sin conexión antes de salir?",
    "q.l22#15.o0" to "Descargar el paquete offline de toda la ruta y probar una vez en casa la localización en modo avión",
    "q.l22#15.o1" to "Hacer solo capturas de pantalla de la ruta",
    "q.l22#15.o2" to "Confiar en el mapa en línea en tiempo real",
    "q.l22#15.o3" to "Imprimir un mapa pequeño",
    "q.l22#15.e" to "«Descargado» y «funciona sin conexión» son dos cosas distintas. Probarlo en casa descubre a tiempo teselas que faltan o problemas de permisos.",

    // ---------- l23 Lista de material y sistema de carga ----------
    "q.l23#0.p" to "Al preparar la lista de material, ¿qué categoría hay que asegurar primero?",
    "q.l23#0.o0" to "Abrigo y protección, y el material técnico",
    "q.l23#0.o1" to "Cámara y batería portátil",
    "q.l23#0.o2" to "Snacks y condimentos",
    "q.l23#0.o3" to "Ropa limpia de recambio",
    "q.l23#0.e" to "El orden de la lista decide qué te va a faltar con mal tiempo. Abrigo, protección y material técnico son la categoría «si falta, pasa algo»; la comodidad que falte solo incomoda.",

    "q.l23#1.p" to "¿Qué capacidades se eligen normalmente para la mochila de cumbre y el petate?",
    "q.l23#1.o0" to "35–50 litros / 90–120 litros",
    "q.l23#1.o1" to "20–30 litros / 50–60 litros",
    "q.l23#1.o2" to "60–70 litros / 60 litros",
    "q.l23#1.o3" to "Cuanto más grandes, mejor",
    "q.l23#1.e" to "La mochila de cumbre lleva lo del día: capa de abrigo, comida de marcha, agua, frontal y botiquín pequeño. El bulto grande va en transporte de carga, no se sube al campo alto.",

    "q.l23#2.p" to "¿Dónde va el peso dentro de la mochila?",
    "q.l23#2.o0" to "Pegado a la espalda, entre los omóplatos (zona alta de la espalda)",
    "q.l23#2.o1" to "En el fondo",
    "q.l23#2.o2" to "En la parte exterior",
    "q.l23#2.o3" to "Donde se pueda coger rápido",
    "q.l23#2.e" to "El peso pegado a la espalda y alto mantiene el centro de gravedad cerca del cuerpo y por encima de la cadera, y así la marcha es estable. En el fondo la mochila se hunde, el cinturón reparte mal y a las horas duele la zona lumbar.",

    "q.l23#3.p" to "¿Qué parte soporta principalmente el peso de la mochila?",
    "q.l23#3.o0" to "El cinturón lumbar (un 60–70 %); los tirantes sirven sobre todo para que la mochila quede pegada al cuerpo",
    "q.l23#3.o1" to "Los tirantes",
    "q.l23#3.o2" to "El pecho",
    "q.l23#3.o3" to "La correa cruzada del cuello",
    "q.l23#3.e" to "El cinturón pasa el peso a la pelvis, la parte del cuerpo que mejor lo soporta. Si a los pocos minutos te duelen los hombros, normalmente el cinturón está flojo o demasiado alto.",

    "q.l23#4.p" to "¿En qué porcentaje del peso corporal se recomienda mantener la mochila el día de cumbre?",
    "q.l23#4.o0" to "15–20 %",
    "q.l23#4.o1" to "30–35 %",
    "q.l23#4.o2" to "40 %",
    "q.l23#4.o3" to "No hay límite",
    "q.l23#4.e" to "Con 60 kg de peso corporal son unos 9–12 kg. Por encima de eso suben claramente el consumo de oxígeno en la subida y el riesgo de perder el equilibrio.",

    "q.l23#5.p" to "Sobre la impermeabilización, ¿qué planteamiento es correcto?",
    "q.l23#5.o0" to "El saco y las plumas, cada uno en su bolsa estanca; la electrónica y los medicamentos en otra capa más",
    "q.l23#5.o1" to "La mochila ya es impermeable, no hacen falta bolsas interiores",
    "q.l23#5.o2" to "Con una bolsa grande para todo basta",
    "q.l23#5.o3" to "Basta con poner una bolsa de basura por fuera",
    "q.l23#5.e" to "El agua entra por las costuras. La ventaja de impermeabilizar por capas es que, aunque se moje la capa exterior, el material crítico sigue seco, y una bolsa rota no arrastra todo lo demás.",

    "q.l23#6.p" to "¿Cuáles son las tres cosas que más se olvidan antes de salir y más peligrosas resultan si faltan?",
    "q.l23#6.o0" to "Frontal con pilas de repuesto, guantes de repuesto y botiquín",
    "q.l23#6.o1" to "Gafas de sol, crema solar y protector labial",
    "q.l23#6.o2" to "Cantimplora, fiambrera y palillos",
    "q.l23#6.o3" to "Cámara, trípode y tarjeta de repuesto",
    "q.l23#6.e" to "Las dos primeras cubren dos situaciones muy frecuentes: «no llegamos al campo antes de anochecer» y «se han mojado los guantes». La tercera es lo que todo el mundo da por hecho que llevará otro.",

    "q.l23#7.p" to "¿En qué partidas se puede ahorrar peso en un campo alto?",
    "q.l23#7.o0" to "Cámara de repuesto y trípode",
    "q.l23#7.o1" to "Tercer juego de ropa de recambio",
    "q.l23#7.o2" to "Frontal y pilas de repuesto",
    "q.l23#7.o3" to "Botiquín",
    "q.l23#7.e" to "Se ahorra peso donde no afecta a la seguridad. Frontal, botiquín y capa de abrigo no son negociables; la cámara y la ropa de recambio son comodidad.",

    "q.l23#8.p" to "¿Qué rasgos debe tener una lista de material que funcione?",
    "q.l23#8.o0" to "Estar agrupada por situaciones de uso, no por orden de compra",
    "q.l23#8.o1" to "Marcar lo obligatorio y lo opcional",
    "q.l23#8.o2" to "Tener variantes por temporada y por tramo de altitud",
    "q.l23#8.o3" to "Cuanto más larga, mejor",
    "q.l23#8.e" to "El valor de una lista es poder seguirla también bajo presión. Agrupar por situación, marcar lo obligatorio y ajustar por altitud son las tres cosas que la hacen utilizable; la longitud hace más probable que se abandone.",

    "q.l23#9.p" to "Ordena la secuencia correcta para hacer la mochila.",
    "q.l23#9.o0" to "Saco y plumas en bolsas estancas, al fondo",
    "q.l23#9.o1" to "El peso (agua, hornillo, material técnico) pegado a la espalda, en la zona media alta",
    "q.l23#9.o2" to "La capa de abrigo del día y la comida de marcha, arriba",
    "q.l23#9.o3" to "Frontal y botiquín en el bolsillo superior o lateral, a mano",
    "q.l23#9.e" to "Primero lo que no se usa pero hay que llevar, luego lo pesado y al final lo que hay que tener siempre a mano. El frontal y el botiquín tienen que poder sacarse sin abrir la mochila.",

    "q.l23#10.p" to "¿Cuál es el orden correcto de comprobaciones una vez puesta la mochila?",
    "q.l23#10.o0" to "Cerrar y apretar el cinturón",
    "q.l23#10.o1" to "Ajustar los tirantes al cuerpo",
    "q.l23#10.o2" to "Cerrar el esternón",
    "q.l23#10.o3" to "Levantarse, dar unos pasos y confirmar que no baila",
    "q.l23#10.e" to "Invertir el orden hace que el peso caiga en los hombros: primero se fija el cinturón, luego se ajustan los tirantes; el esternón solo evita que se abran hacia fuera. Al final hay que verificarlo caminando.",

    "q.l23#11.p" to "La mochila de cumbre suele ser de 35–50 litros y el petate, de ______ litros.",
    "q.l23#11.a0" to "90–120",
    "q.l23#11.a1" to "90-120",
    "q.l23#11.a2" to "90~120",
    "q.l23#11.e" to "El petate lleva el bulto de la carretera al campo: tiene que caber el saco, las plumas, las botas y el material técnico, y suele ser de 90–120 litros.",

    "q.l23#12.p" to "El cinturón lumbar soporta alrededor del ______ % del peso de la mochila (un número).",
    "q.l23#12.a0" to "60",
    "q.l23#12.a1" to "65",
    "q.l23#12.a2" to "70",
    "q.l23#12.a3" to "60–70",
    "q.l23#12.e" to "Un 60–70 % aproximadamente. También sirve como criterio de ajuste: si cargas claramente en los hombros, el problema suele estar en el cinturón.",

    "q.l23#13.p" to "Relaciona cada zona de la mochila con lo que debe llevar.",
    "q.l23#13.l0" to "Pegado a la espalda, zona media alta",
    "q.l23#13.l1" to "Fondo",
    "q.l23#13.l2" to "Bolsillo superior",
    "q.l23#13.l3" to "Bolsillo lateral",
    "q.l23#13.r0" to "Agua, hornillo, material técnico: lo pesado",
    "q.l23#13.r1" to "Saco y plumas (en bolsa estanca)",
    "q.l23#13.r2" to "Capa de abrigo del día y comida de marcha",
    "q.l23#13.r3" to "Frontal, botiquín pequeño, protección solar",
    "q.l23#13.e" to "La posición decide el acceso y el centro de gravedad. El frontal va al lateral para no tener que rebuscar de noche; el saco va al fondo porque solo se usa una vez al día en el campo.",

    "q.l23#14.p" to "La mochila de tu compañero pesa bastante más que la tuya. ¿Qué es lo más razonable?",
    "q.l23#14.o0" to "Extenderlo todo en el sitio y repartir de nuevo, igualando el material común",
    "q.l23#14.o1" to "Que se apañe, es su decisión",
    "q.l23#14.o2" to "Cargar con la mitad aunque te sobrecargues",
    "q.l23#14.o3" to "Tirar el material común",
    "q.l23#14.e" to "El ritmo del grupo lo marca el más lento, y sobrecargarlo lo hace aún más lento. El material común (hornillo, cuerda, botiquín) tiene que repartirse por igual, y eso se hace antes de salir.",
    // ---------- l24 Sistema de dormir y equipo de campo ----------
    "q.l24#0.p" to "¿Qué temperatura hay que mirar al elegir un saco?",
    "q.l24#0.o0" to "La temperatura de confort",
    "q.l24#0.o1" to "La temperatura extrema",
    "q.l24#0.o2" to "La mínima que anuncia la publicidad del fabricante",
    "q.l24#0.o3" to "El peso",
    "q.l24#0.e" to "La de confort es la temperatura a la que duermes toda la noche sin pasar frío con la ropa base puesta; la extrema es solo el límite de supervivencia, el punto en que no te congelas. Entre una y otra suele haber más de 10 °C.",

    "q.l24#1.p" to "En altitud, ¿cómo se elige la temperatura de confort del saco?",
    "q.l24#1.o0" to "Al menos 5 °C por debajo de la mínima prevista",
    "q.l24#1.o1" to "Igual a la mínima prevista",
    "q.l24#1.o2" to "5 °C por encima de la mínima prevista",
    "q.l24#1.o3" to "Da igual",
    "q.l24#1.e" to "El margen existe porque de noche baja el metabolismo, se come menos y puede formarse escarcha dentro de la tienda: la sensación real es más fría que el pronóstico.",

    "q.l24#2.p" to "¿De qué hay que proteger sobre todo un saco de plumas?",
    "q.l24#2.o0" to "De la humedad: mojado casi no abriga",
    "q.l24#2.o1" to "De los pliegues",
    "q.l24#2.o2" to "Del sol",
    "q.l24#2.o3" to "Del roce",
    "q.l24#2.e" to "Las plumas mojadas pierden volumen y con ello gran parte del aislamiento, y en el campo es casi imposible secarlas de verdad. Una bolsa estanca es el seguro más barato y eficaz.",

    "q.l24#3.p" to "¿Cómo se usan normalmente las esterillas en un campo de altura?",
    "q.l24#3.o0" to "Esterilla de espuma de célula cerrada y colchoneta hinchable superpuestas, sumando los valores de aislamiento",
    "q.l24#3.o1" to "Solo colchoneta hinchable",
    "q.l24#3.o2" to "Solo una manta de aluminio",
    "q.l24#3.o3" to "Directamente sobre el suelo de la tienda",
    "q.l24#3.e" to "La espuma corta la conducción con el suelo y la hinchable da una superficie plana y cómoda. La combinación también sirve de respaldo: si la hinchable falla, la espuma sigue ahí.",

    "q.l24#4.p" to "La colchoneta hinchable pierde aire en el campo. ¿Qué es lo primero que hay que hacer?",
    "q.l24#4.o0" to "Localizar el pinchazo y poner un parche, y usar la espuma como recambio",
    "q.l24#4.o1" to "Seguir durmiendo y resolverlo mañana",
    "q.l24#4.o2" to "Desinflarla del todo",
    "q.l24#4.o3" to "Cambiar de tienda",
    "q.l24#4.e" to "La fuga va a más y de noche hace más frío. Parche más espuma de respaldo es el procedimiento estándar; confiar en que aguante hasta el amanecer es una apuesta.",

    "q.l24#5.p" to "¿Cuál es la forma correcta de guardar un saco durante largos periodos?",
    "q.l24#5.o0" to "Extendido o colgado suelto en un lugar seco",
    "q.l24#5.o1" to "Siempre comprimido en su funda",
    "q.l24#5.o2" to "En vacío",
    "q.l24#5.o3" to "Cerrado hermético en una bolsa de plástico",
    "q.l24#5.e" to "La compresión prolongada fatiga la estructura de las plumas y en unas temporadas el abrigo baja de forma clara. Guardar es sinónimo de suelto y seco.",

    "q.l24#6.p" to "¿Qué medidas mejoran de verdad el sueño en altitud?",
    "q.l24#6.o0" to "Beber menos por la noche pero cubrir el total del día",
    "q.l24#6.o1" to "Usar tapones para aislar los ruidos de la tienda",
    "q.l24#6.o2" to "Meter la ropa mojada en el saco para secarla",
    "q.l24#6.o3" to "Cenar muy copiosamente antes de dormir",
    "q.l24#6.e" to "Meter ropa mojada en el saco quita mucho calor y moja las plumas: es un error clásico. Una cena muy pesada empeora las molestias nocturnas.",

    "q.l24#7.p" to "¿Qué suele formar parte de un sistema para dormir?",
    "q.l24#7.o0" to "Saco (con sábana interior)",
    "q.l24#7.o1" to "Esterilla (espuma más hinchable)",
    "q.l24#7.o2" to "Almohada",
    "q.l24#7.o3" to "Bajera de la tienda",
    "q.l24#7.e" to "Estos cuatro elementos determinan juntos la conducción con el suelo, la convección del aire y el confort. Si falta uno, de noche se pierde calor de forma constante por ese lado.",

    "q.l24#8.p" to "¿Cuál es el orden correcto para montar la zona de dormir?",
    "q.l24#8.o0" to "Allanar el suelo y quitar piedras y objetos puntiagudos",
    "q.l24#8.o1" to "Extender la bajera y la esterilla de espuma",
    "q.l24#8.o2" to "Hinchar la colchoneta y comprobarla",
    "q.l24#8.o3" to "Extender el saco dejando espacio para girarte",
    "q.l24#8.e" to "Un orden equivocado obliga a repetir: si el suelo no está limpio, la colchoneta puede pincharse en una sola noche.",

    "q.l24#9.p" to "La temperatura de confort del saco debería estar al menos ______ °C por debajo de la mínima prevista.",
    "q.l24#9.a0" to "5",
    "q.l24#9.e" to "5 °C de margen es la práctica habitual. En altitud la noche se siente más fría y ese margen no es exagerado.",

    "q.l24#10.p" to "Un saco de plumas mojado casi no abriga, así que debe ir en una ______ propia.",
    "q.l24#10.a0" to "bolsa estanca",
    "q.l24#10.a1" to "bolsa impermeable",
    "q.l24#10.a2" to "dry bag",
    "q.l24#10.e" to "La bolsa estanca propia sirve para separar capas: aunque fuera se moje todo, el núcleo sigue seco.",

    "q.l24#11.p" to "Relaciona cada equipo de dormir con su función principal.",
    "q.l24#11.l0" to "Esterilla de espuma de célula cerrada",
    "q.l24#11.l1" to "Colchoneta hinchable",
    "q.l24#11.l2" to "Sábana interior del saco",
    "q.l24#11.l3" to "Tapones para los oídos",
    "q.l24#11.r0" to "Corta la conducción con el suelo y no teme los pinchazos",
    "q.l24#11.r1" to "Da una superficie plana y cómoda y se puede superponer para aislar más",
    "q.l24#11.r2" to "Reduce la suciedad y la humedad dentro del saco",
    "q.l24#11.r3" to "Amortigua el ruido y facilita conciliar el sueño",
    "q.l24#11.e" to "Cuatro equipos resuelven cuatro problemas distintos: conducción, planitud, humedad y ruido. Si falta uno, el problema vuelve por ese lado.",

    "q.l24#12.p" to "Hay mucha escarcha dentro de la tienda. ¿Cómo se procede a la mañana siguiente?",
    "q.l24#12.o0" to "Guardar primero el saco en la bolsa estanca y luego sacudir la escarcha de la pared interior",
    "q.l24#12.o1" to "Recoger primero la tienda y dejar el saco fuera",
    "q.l24#12.o2" to "Derretir la escarcha con el calor del cuerpo",
    "q.l24#12.o3" to "Ignorarla, con el sol se va",
    "q.l24#12.e" to "La escarcha cae como hielo al menor roce. Cerrar el saco primero es el gesto que evita que «una salida entera se estropee en diez minutos por la mañana».",

    "q.l24#13.p" to "¿Por qué se duerme peor en general en altitud?",
    "q.l24#13.o0" to "La falta de oxígeno provoca respiración periódica, que te saca del sueño ligero una y otra vez",
    "q.l24#13.o1" to "La tienda es demasiado dura",
    "q.l24#13.o2" to "Porque se camina poco durante el día",
    "q.l24#13.o3" to "Porque en altura el tiempo pasa más despacio",
    "q.l24#13.e" to "Es fisiológico. Lo único que se puede hacer es mejorar las condiciones (abrigo, silencio, hidratación), no exigirse «dormir ocho horas seguidas».",

    "q.l24#14.p" to "El grupo solo tiene una tienda de reserva. ¿A quién se le da primero?",
    "q.l24#14.o0" to "A quien tenga más riesgo de hipotermia o ya muestre síntomas de mal de altura",
    "q.l24#14.o1" to "Al jefe de cordada",
    "q.l24#14.o2" to "A quien esté más en forma",
    "q.l24#14.o3" to "Se decide por sorteo",
    "q.l24#14.e" to "Los recursos de reserva se reparten por riesgo, no por antigüedad ni por forma física. Eso hay que dejarlo claro antes de salir para no discutir de noche.",

    // ---------- l7 Reacción ante una caída y autorretención ----------
    "q.l7#10.p" to "En el instante en que pierdes el equilibrio, ¿qué hay que proteger primero?",
    "q.l7#10.o0" to "La cabeza, girando a la vez el cuerpo a una posición que permita frenar, boca abajo o boca arriba",
    "q.l7#10.o1" to "La mochila",
    "q.l7#10.o2" to "El piolet",
    "q.l7#10.o3" to "El móvil",
    "q.l7#10.e" to "El golpe en la cabeza es una de las principales causas de muerte en una caída. Girar, proteger la cabeza y clavar el piolet tienen que empezar a la vez.",

    "q.l7#11.p" to "¿Cuál es el grito estándar cuando ves caer piedras o a alguien deslizarse?",
    "q.l7#11.o0" to "«¡Piedra!» o «¡Caída!», fuerte, corto y repetido",
    "q.l7#11.o1" to "Observar en silencio",
    "q.l7#11.o2" to "Solo hacer señas",
    "q.l7#11.o3" to "Silbar",
    "q.l7#11.e" to "El grito sirve para que quien está abajo levante la vista y se aparte de inmediato. El tono importa más que la explicación; corto y repetido funciona mejor que un discurso.",

    "q.l7#12.p" to "Una persona de la cordada se desliza. ¿Qué hacen los demás?",
    "q.l7#12.o0" to "Frenar de inmediato y mantener la tensión de la cuerda, sin moverse a la vez",
    "q.l7#12.o1" to "Correr todos hacia ella",
    "q.l7#12.o2" to "Soltar la cuerda",
    "q.l7#12.o3" to "Sentarse en el sitio",
    "q.l7#12.e" to "Si todos se mueven a la vez la cuerda pierde tensión y quien cae sigue deslizándose. El primer paso del frenado es asegurar tu propio apoyo.",

    "q.l7#13.p" to "La caída se ha detenido pero la cuerda sigue tensa. ¿Cómo se procede?",
    "q.l7#13.o0" to "Mantener la tensión, montar primero un aseguramiento y luego acercarse a mirar",
    "q.l7#13.o1" to "Aflojar la cuerda de inmediato",
    "q.l7#13.o2" to "Que suba por su cuenta",
    "q.l7#13.o3" to "Cortar la cuerda",
    "q.l7#13.e" to "Aflojar puede provocar otra caída. Primero te fijas tú, y solo después tiene sentido hablar de rescate.",

    "q.l7#14.p" to "¿Por qué los crampones pueden ser peligrosos durante una caída?",
    "q.l7#14.o0" to "Las puntas se enganchan en la nieve o en la ropa y provocan torsiones o una parada brusca",
    "q.l7#14.o1" to "Porque pesan mucho",
    "q.l7#14.o2" to "Porque se sueltan",
    "q.l7#14.o3" to "Porque se desgastan",
    "q.l7#14.e" to "Si un pie se engancha de golpe, el cuerpo gira sobre la articulación. Por eso importa tanto la postura «pies abajo y rodillas flexionadas».",

    "q.l7#15.p" to "En el descenso es cuando más accidentes ocurren. ¿Cuál es la causa principal?",
    "q.l7#15.o0" to "Fatiga, atención en baja y la relajación mental de «ya está hecho»",
    "q.l7#15.o1" to "Que anochece",
    "q.l7#15.o2" to "El desgaste del material",
    "q.l7#15.o3" to "Que la ruta se vuelve más difícil",
    "q.l7#15.e" to "Al bajar el terreno suele ser más expuesto y la vigilancia está en su punto más bajo. Planificar el descenso como «la otra mitad de la salida» no es un formalismo.",

    // ---------- l8 Descenso por nieve y deslizamiento controlado ----------
    "q.l8#10.p" to "¿Qué postura se recomienda para bajar una pendiente de nieve dura algo inclinada?",
    "q.l8#10.o0" to "De cara a la pendiente, con tres puntos de contacto y bajando poco a poco",
    "q.l8#10.o1" to "De cara hacia fuera, bajando rápido",
    "q.l8#10.o2" to "Deslizarse (glissade)",
    "q.l8#10.o3" to "Saltar",
    "q.l8#10.e" to "De cara a la pendiente puedes frenar con el piolet en cualquier momento. De cara hacia fuera solo vale en pendientes suaves o con nieve blanda.",

    "q.l8#11.p" to "¿Cómo se prepara el frenado en un deslizamiento controlado (glissade)?",
    "q.l8#11.o0" to "El piolet se mantiene en una posición desde la que se pueda clavar y frenar en cualquier momento",
    "q.l8#11.o1" to "Guardar el piolet en la mochila",
    "q.l8#11.o2" to "Abrir las dos manos",
    "q.l8#11.o3" to "Cerrar los ojos",
    "q.l8#11.e" to "La diversión del glissade se basa en poder parar cuando quieras. Con mala postura o nieve demasiado dura, el glissade se convierte directamente en una caída.",

    "q.l8#12.p" to "¿Qué comprobaciones hay que completar antes de rapelar?",
    "q.l8#12.o0" to "Reunión, nudos, cabo de cuerda, sentido de paso del descendedor y respaldo",
    "q.l8#12.o1" to "Solo la reunión",
    "q.l8#12.o2" to "Solo la longitud de la cuerda",
    "q.l8#12.o3" to "Solo a los compañeros",
    "q.l8#12.e" to "Casi todos los accidentes de rápel se deben a uno de esos cinco puntos. Repasarlos en voz alta uno por uno es más fiable que «yo creo que está bien».",

    "q.l8#13.p" to "¿Dónde es más probable que te alcance una piedra al rapelar?",
    "q.l8#13.o0" to "Justo debajo de la vertical de la cuerda",
    "q.l8#13.o1" to "A tres metros de lado",
    "q.l8#13.o2" to "Junto a la reunión",
    "q.l8#13.o3" to "Detrás de la repisa",
    "q.l8#13.e" to "La vertical es la línea de caída de las piedras. Al rapelar conviene desplazarse a un lado y pasar el borde con rapidez.",

    "q.l8#14.p" to "¿Cuál es la causa más frecuente de que la cuerda no se recupere tras un rápel de doble cuerda?",
    "q.l8#14.o0" to "Cabos anudados, un nudo atascado en una fisura o longitudes distintas en los dos ramales",
    "q.l8#14.o1" to "La cuerda es demasiado vieja",
    "q.l8#14.o2" to "El descendedor es demasiado pequeño",
    "q.l8#14.o3" to "La reunión está demasiado alta",
    "q.l8#14.e" to "Antes de tirar hay que confirmar que los cabos están libres, sin enganches y con la misma longitud. Si se atasca, primero se cambia el ángulo, no se tira con fuerza.",

    "q.l8#15.p" to "¿Para qué sirve el nudo de tope en el cabo al rapelar?",
    "q.l8#15.o0" to "Evita que el cabo se salga del descendedor y provoque una caída sin control",
    "q.l8#15.o1" to "Facilita recoger la cuerda",
    "q.l8#15.o2" to "Marca la longitud",
    "q.l8#15.o3" to "Reduce el desgaste",
    "q.l8#15.e" to "Si la cuerda no llega, un cabo que se escapa significa perder el frenado de golpe. El nudo no cuesta nada y en muchos accidentes es la línea que separa un susto de una tragedia.",
    // ---------- l13 Mal agudo de montaña (AMS) ----------
    "q.l13#14.p" to "¿Cuánto tarda en aparecer el AMS tras llegar a la altitud?",
    "q.l13#14.o0" to "6–12 horas",
    "q.l13#14.o1" to "De inmediato",
    "q.l13#14.o2" to "A los 3 días",
    "q.l13#14.o3" to "A la semana",
    "q.l13#14.e" to "Esa ventana importa mucho: la tarde y la noche del mismo día de la subida son el periodo de observación, y son también la razón de «no seguir subiendo».",

    "q.l13#15.p" to "¿Cuál es el punto clave para distinguir el AMS del HACE?",
    "q.l13#15.o0" to "Si aparece ataxia o alteración de la conciencia",
    "q.l13#15.o1" to "La intensidad del dolor de cabeza",
    "q.l13#15.o2" to "Si hay náuseas",
    "q.l13#15.o3" to "La frecuencia cardíaca",
    "q.l13#15.e" to "Dolor de cabeza y náuseas son frecuentes en el AMS; en cuanto la marcha se vuelve inestable o la conciencia se nubla, hay que tratar como HACE y descender de inmediato.",

    "q.l13#16.p" to "Si los síntomas del AMS desaparecen y pasan 24 horas, ¿se puede seguir subiendo?",
    "q.l13#16.o0" to "Sí, pero más despacio y con observación estrecha",
    "q.l13#16.o1" to "Sí, sin más",
    "q.l13#16.o2" to "Nunca más",
    "q.l13#16.o3" to "Hay que descender 1.000 m",
    "q.l13#16.e" to "Que los síntomas desaparezcan del todo indica que la aclimatación avanza. Aun así hay que ser más conservador, y si reaparecen, se detiene la subida.",

    "q.l13#17.p" to "¿Qué se confunde con facilidad con un AMS?",
    "q.l13#17.o0" to "Deshidratación, resfriado y falta de sueño",
    "q.l13#17.o1" to "Una fractura",
    "q.l13#17.o2" to "Congelaciones",
    "q.l13#17.o3" to "Ceguera de nieve",
    "q.l13#17.e" to "Los síntomas se solapan. Lo que mejora claramente tras beber y descansar no suele ser AMS; lo que persiste o empeora se trata como AMS.",

    "q.l13#18.p" to "¿Qué hay que tener en cuenta al usar analgésicos con AMS?",
    "q.l13#18.o0" to "Solo tapan los síntomas y en ningún caso justifican seguir subiendo",
    "q.l13#18.o1" to "Con la pastilla ya se puede subir",
    "q.l13#18.o2" to "Se puede aumentar la dosis",
    "q.l13#18.o3" to "Están del todo contraindicados",
    "q.l13#18.e" to "El analgésico hace desaparecer la señal, pero el proceso sigue. Subir con los síntomas tapados es la vía más habitual hacia el agravamiento.",

    "q.l13#19.p" to "¿Por qué se pasa por alto el mal de altura en niños y personas mayores?",
    "q.l13#19.o0" to "Expresan peor los síntomas y los cambios de conducta suelen preceder a la queja",
    "q.l13#19.o1" to "Porque no son sensibles",
    "q.l13#19.o2" to "Porque se aclimatan rápido",
    "q.l13#19.o3" to "Porque suben poco a la montaña",
    "q.l13#19.e" to "Los niños muestran somnolencia, llanto, falta de apetito; las personas mayores a veces solo «sin energía». Observar la conducta es más fiable que esperar a que lo digan.",

    // ---------- l14 HACE y HAPE ----------
    "q.l14#12.p" to "¿Cuál es la prueba más sencilla para detectar la ataxia del HACE?",
    "q.l14#12.o0" to "Caminar en línea recta juntando el talón con la punta del pie",
    "q.l14#12.o1" to "Mantenerse a pie firme sobre una pierna",
    "q.l14#12.o2" to "Hacer sentadillas",
    "q.l14#12.o3" to "Saltar en el sitio",
    "q.l14#12.e" to "Si no puede seguir la línea y la marcha es tambaleante, la prueba es positiva. No necesita material, cualquiera puede hacerla y sirve como cribado diario.",

    "q.l14#13.p" to "¿Cómo evoluciona normalmente la tos en el HAPE?",
    "q.l14#13.o0" to "De tos seca a esputo espumoso, con caída brusca de la capacidad de esfuerzo",
    "q.l14#13.o1" to "De tos con flemas a tos seca",
    "q.l14#13.o2" to "Se mantiene igual",
    "q.l14#13.o3" to "Solo aparece por la noche",
    "q.l14#13.e" to "Esputo espumoso y disnea en reposo son la combinación típica del HAPE. Cuando el esputo ya es rosado y espumoso, lo habitual es que el cuadro esté avanzado.",

    "q.l14#14.p" to "¿En qué fase de la salida aparece más a menudo el HAPE?",
    "q.l14#14.o0" to "En la primera o segunda noche después de subir",
    "q.l14#14.o1" to "Antes de salir",
    "q.l14#14.o2" to "Durante el descenso",
    "q.l14#14.o3" to "Al volver al llano",
    "q.l14#14.e" to "De noche la hipoxia es máxima y el HAPE suele aparecer en la segunda noche. De ahí que la primera merezca atención especial.",

    "q.l14#15.p" to "Con sospecha de HACE o HAPE, ¿cuál es el orden de prioridades?",
    "q.l14#15.o0" to "Descender de inmediato y dar oxígeno; la medicación es apoyo",
    "q.l14#15.o1" to "Medicar primero y observar",
    "q.l14#15.o2" to "Esperar una noche",
    "q.l14#15.o3" to "Esperar al rescate",
    "q.l14#15.e" to "El descenso es la única medida que revierte el cuadro con certeza. La medicación y el oxígeno sirven para «ganar tiempo de descenso».",

    "q.l14#16.p" to "¿Qué hace y qué no hace la bolsa hiperbárica (bolsa de Gamow)?",
    "q.l14#16.o0" to "Simula un descenso y gana tiempo, pero no sustituye a un descenso real",
    "q.l14#16.o1" to "Cura la enfermedad",
    "q.l14#16.o2" to "Se puede usar de forma indefinida",
    "q.l14#16.o3" to "Solo sirve con la persona consciente",
    "q.l14#16.e" to "La bolsa es «tierra baja portátil»: requiere que alguien la maneje, cansa y tiene capacidad limitada. Es un puente, no el destino.",

    "q.l14#17.p" to "Si alguien ha tenido un HAPE en la salida, ¿qué se hace al recuperarse?",
    "q.l14#17.o0" to "No volver a subir en esta salida y organizar el descenso",
    "q.l14#17.o1" to "Descansar dos días y seguir",
    "q.l14#17.o2" to "Cambiar de ruta y continuar",
    "q.l14#17.o3" to "Seguir con la dosis a la mitad",
    "q.l14#17.e" to "El riesgo de recaída del HAPE es alto, y un segundo episodio puede ser más rápido y más grave. Esta ascensión ha terminado.",

    "q.l14#18.p" to "¿Cómo se manifiesta concretamente la «alteración de la conciencia» del HACE?",
    "q.l14#18.o0" to "Somnolencia, respuestas que no vienen al caso, conducta anómala, alucinaciones",
    "q.l14#18.o1" to "Solo coma",
    "q.l14#18.o2" to "Solo dolor de cabeza",
    "q.l14#18.o3" to "Solo náuseas",
    "q.l14#18.e" to "Al principio puede ser solo «más callado que de costumbre» o repetir frases. Los compañeros suelen verlo antes que la propia persona, por eso hay que observarse entre sí.",

    "q.l14#19.p" to "¿Por qué pueden aparecer a la vez HAPE y HACE?",
    "q.l14#19.o0" to "Los dos son manifestaciones del mal de altura grave y pueden coexistir a nivel patológico",
    "q.l14#19.o1" to "Porque se medican igual",
    "q.l14#19.o2" to "Porque los síntomas se parecen",
    "q.l14#19.o3" to "No aparecen nunca juntos",
    "q.l14#19.e" to "En la práctica clínica son frecuentes los casos de HACE con HAPE. El principio de tratamiento es el mismo: descender, oxígeno y medicación si hace falta.",

    // ---------- l15 Estrategia de aclimatación ----------
    "q.l15#12.p" to "En la aclimatación, ¿qué cambio ocurre primero?",
    "q.l15#12.o0" to "Aumenta la ventilación (respiración más profunda y rápida)",
    "q.l15#12.o1" to "Aumentan los glóbulos rojos",
    "q.l15#12.o2" to "Se fortalece la musculatura",
    "q.l15#12.o3" to "Baja la frecuencia cardíaca",
    "q.l15#12.e" to "La ventilación sube en pocas horas; la producción de glóbulos rojos tarda días o semanas. Por eso la primera noche es la más dura.",

    "q.l15#13.p" to "¿Por qué el alcohol y los sedantes empeoran el mal de altura?",
    "q.l15#13.o0" to "Deprimen el impulso respiratorio y agravan la hipoxia nocturna",
    "q.l15#13.o1" to "Porque deshidratan",
    "q.l15#13.o2" to "Porque dañan el estómago",
    "q.l15#13.o3" to "Porque alteran el sueño",
    "q.l15#13.e" to "En altura el impulso respiratorio ya está debilitado y estas sustancias lo frenan más. Además, el aspecto de una persona ebria se confunde con facilidad con un HACE incipiente.",

    "q.l15#14.p" to "La respiración periódica es muy común de noche en altura. ¿Cómo se produce?",
    "q.l15#14.o0" to "La hipoxia provoca hiperventilación, el CO₂ baja demasiado y aparece una pausa respiratoria; el ciclo se repite",
    "q.l15#14.o1" to "Obstrucción de la vía aérea",
    "q.l15#14.o2" to "Un problema cardíaco",
    "q.l15#14.o3" to "Un efecto psicológico",
    "q.l15#14.e" to "Es fisiológico y no hay que alarmarse. Pero rompe el sueño y es una de las razones para dormir más bajo.",

    "q.l15#15.p" to "¿Cuál de estas señales no es un aviso temprano de mala aclimatación?",
    "q.l15#15.o0" to "Mejor apetito y mejor sueño",
    "q.l15#15.o1" to "Dolor de cabeza persistente",
    "q.l15#15.o2" to "Despertares nocturnos frecuentes con sensación de ahogo",
    "q.l15#15.o3" to "Menor capacidad de esfuerzo",
    "q.l15#15.e" to "Comer, dormir y caminar bien son las tres señales de buena aclimatación. Cuando ocurre lo contrario, hay que bajar el ritmo.",

    "q.l15#16.p" to "¿Qué solidez tiene la evidencia sobre el entrenamiento intermitente en hipoxia (preaclimatación)?",
    "q.l15#16.o0" to "Hay cierto efecto fisiológico, pero no sustituye a la aclimatación sobre el terreno",
    "q.l15#16.o1" to "Sustituye por completo a la aclimatación",
    "q.l15#16.o2" to "No sirve absolutamente de nada",
    "q.l15#16.o3" to "Solo funciona en deportistas de élite",
    "q.l15#16.e" to "La preaclimatación puede acortar algo la aclimatación, pero lo decisivo siguen siendo la velocidad de ascenso y la altura de dormir. No es un atajo.",

    "q.l15#17.p" to "¿Cuál es el riesgo principal de subir a altitud con un resfriado sin curar?",
    "q.l15#17.o0" to "La inflamación de la vía aérea aumenta el riesgo de HAPE",
    "q.l15#17.o1" to "Contagiar a los compañeros",
    "q.l15#17.o2" to "Empeorar el resfriado",
    "q.l15#17.o3" to "Ninguno",
    "q.l15#17.e" to "Es lo que más se pasa por alto. Tomar un resfriado como «una tontería» y subir igual es un desencadenante habitual de HAPE.",

    "q.l15#18.p" to "¿Cómo se aprovecha un día de descanso en la fase de aclimatación?",
    "q.l15#18.o0" to "Quedarse a la misma altura con actividad suave, recuperando sueño y comida, en lugar de quedarse tumbado",
    "q.l15#18.o1" to "Quedarse todo el día en la tienda",
    "q.l15#18.o2" to "Seguir subiendo",
    "q.l15#18.o3" to "Bajar al valle a descansar",
    "q.l15#18.e" to "La actividad ligera ayuda a la ventilación y a la circulación. Estar completamente tumbado retrasa la aclimatación y quita el apetito.",

    "q.l15#19.p" to "¿Por qué se dice que «el diseño de la salida ya es prevención»?",
    "q.l15#19.o0" to "La velocidad de ascenso y la altura de dormir determinan la mayor parte del riesgo; cambiar el plan es más de fondo que tomar pastillas",
    "q.l15#19.o1" to "Porque un plan es fácil de escribir",
    "q.l15#19.o2" to "Porque los medicamentos son caros",
    "q.l15#19.o3" to "Porque lo exige el guía",
    "q.l15#19.e" to "Quien incluye días de aclimatación rara vez necesita medicación; quien llena el calendario suele acabar apoyándose en pastillas.",

    // ---------- l16 Hipotermia y congelación ----------
    "q.l16#12.p" to "En la clasificación de la hipotermia, ¿a qué temperatura central corresponde la «leve»?",
    "q.l16#12.o0" to "35–32 °C, consciente y con temblor evidente",
    "q.l16#12.o1" to "38 °C",
    "q.l16#12.o2" to "Por debajo de 30 °C",
    "q.l16#12.o3" to "Por debajo de 28 °C",
    "q.l16#12.e" to "La leve se caracteriza por temblor y conciencia clara. El temblor indica que el cuerpo aún produce calor, y también que todavía hay margen.",

    "q.l16#13.p" to "¿Por qué es una señal de alarma que el temblor se detenga?",
    "q.l16#13.o0" to "Porque el cuerpo ya no puede mantener la temperatura produciendo calor y entra en hipotermia moderada o grave",
    "q.l16#13.o1" to "Porque se ha recuperado",
    "q.l16#13.o2" to "Porque se ha dormido",
    "q.l16#13.o3" to "Porque está muy cansado",
    "q.l16#13.e" to "Pasar de «tiembla sin parar» a «ya no tiembla» no es mejorar: es el fallo de la compensación. Hay que recalentar y evacuar de inmediato.",

    "q.l16#14.p" to "¿Qué se hace con una persona hipotérmica con la conciencia alterada?",
    "q.l16#14.o0" to "No dar bebidas calientes; aislar, separar del suelo y trasladar con suavidad",
    "q.l16#14.o1" to "Dar agua caliente con azúcar",
    "q.l16#14.o2" to "Frotar manos y pies",
    "q.l16#14.o3" to "Hacer que camine",
    "q.l16#14.e" to "Con la conciencia alterada el reflejo de deglución no es fiable y el líquido puede aspirarse. Los movimientos bruscos pueden desencadenar arritmias.",

    "q.l16#15.p" to "Para recalentar una extremidad congelada en el lugar, ¿a qué temperatura debe estar el agua?",
    "q.l16#15.o0" to "37–40 °C",
    "q.l16#15.o1" to "50–60 °C",
    "q.l16#15.o2" to "Agua con hielo",
    "q.l16#15.o3" to "Cuanto más caliente, mejor",
    "q.l16#15.e" to "Esa temperatura ronda la corporal: recalentar sin quemar. Demasiado caliente provoca una segunda lesión y demasiado frío no sirve de nada.",

    "q.l16#16.p" to "¿Por qué hay que evitar que una congelación se vuelva a congelar tras recalentarla?",
    "q.l16#16.o0" to "Porque congelar y descongelar varias veces daña el tejido mucho más que una sola congelación",
    "q.l16#16.o1" to "Porque duele",
    "q.l16#16.o2" to "Porque se hincha",
    "q.l16#16.o3" to "Porque deja cicatriz",
    "q.l16#16.e" to "Descongelar y volver a congelar es peor que mantenerse congelado. Por eso solo se recalienta cuando hay garantía de que no volverá a helarse.",

    "q.l16#17.p" to "¿Qué no conviene hacer en el lugar con una zona congelada?",
    "q.l16#17.o0" to "Frotarla con nieve, acercarla al fuego o darle alcohol",
    "q.l16#17.o1" to "Recalentarla con agua tibia",
    "q.l16#17.o2" to "Cubrirla con un apósito estéril",
    "q.l16#17.o3" to "Elevar la extremidad",
    "q.l16#17.e" to "El roce y el calor seco agravan la lesión del tejido. En el lugar solo se hace «agua tibia, protección y analgesia».",

    "q.l16#18.p" to "Tras una congelación en los pies, ¿se puede seguir caminando?",
    "q.l16#18.o0" to "Mejor no: caminar agrava la lesión; si se puede esperar al rescate, se espera",
    "q.l16#18.o1" to "Sí, sin problema",
    "q.l16#18.o2" to "Corriendo es más rápido",
    "q.l16#18.o3" to "Mientras no duela, sí",
    "q.l16#18.e" to "Cargar sobre un pie recalentado y congelado empeora mucho la lesión. Por eso hay que sopesar cuándo se recalienta.",

    "q.l16#19.p" to "¿Cuáles son las tres cosas más importantes para prevenir la hipotermia?",
    "q.l16#19.o0" to "Mantenerse seco, cortar el viento y reponer energía a tiempo",
    "q.l16#19.o1" to "Ponerse más ropa",
    "q.l16#19.o2" to "Beber mucha agua caliente",
    "q.l16#19.o3" to "Caminar mucho",
    "q.l16#19.e" to "Humedad, viento y falta de energía son las tres puertas de entrada de la hipotermia. La suma que funciona es capa de evacuación, capa cortavientos y comer a horas fijas.",

    // ---------- m09 Medicación de altura y fármacos de urgencia ----------
    "q.m09#12.p" to "¿Cuál es la dosis habitual en adultos de acetazolamida como prevención?",
    "q.m09#12.o0" to "125 mg dos veces al día",
    "q.m09#12.o1" to "500 mg una vez al día",
    "q.m09#12.o2" to "1.000 mg una vez al día",
    "q.m09#12.o3" to "Según necesidad",
    "q.m09#12.e" to "125 mg dos veces al día es el criterio que usa el manual. Es un fármaco con receta: contraindicaciones y efectos adversos requieren valoración médica.",

    "q.m09#13.p" to "¿Qué efectos adversos frecuentes tiene la acetazolamida?",
    "q.m09#13.o0" to "Hormigueo en manos y pies, alteración del gusto (sobre todo con bebidas con gas) y aumento de la diuresis",
    "q.m09#13.o1" to "Somnolencia",
    "q.m09#13.o2" to "Aceleración del pulso",
    "q.m09#13.o3" to "Subida de la tensión",
    "q.m09#13.e" to "Suelen tolerarse, pero afectan a la ingesta de líquidos y al sueño. Está contraindicada en personas alérgicas a las sulfamidas.",

    "q.m09#14.p" to "¿Cuál es la dosis habitual de dexametasona en el HACE?",
    "q.m09#14.o0" to "4 mg cada 6 horas",
    "q.m09#14.o1" to "1 mg una vez al día",
    "q.m09#14.o2" to "20 mg cada 12 horas",
    "q.m09#14.o3" to "Una sola dosis si hace falta",
    "q.m09#14.e" to "4 mg cada 6 horas es el criterio del manual. Es tratamiento, y no sustituye al descenso.",

    "q.m09#15.p" to "¿Para qué se usa principalmente el nifedipino?",
    "q.m09#15.o0" to "Para la prevención y el tratamiento del HAPE",
    "q.m09#15.o1" to "Para el AMS",
    "q.m09#15.o2" to "Para las congelaciones",
    "q.m09#15.o3" to "Para la deshidratación",
    "q.m09#15.e" to "El nifedipino actúa reduciendo la resistencia vascular pulmonar, con 20–30 mg cada 12 horas como pauta habitual. No trata el AMS.",

    "q.m09#16.p" to "Los síntomas mejoran claramente tras la dexametasona. ¿Qué es lo correcto?",
    "q.m09#16.o0" to "Descender igualmente: el fármaco solo gana tiempo",
    "q.m09#16.o1" to "Cancelar el descenso",
    "q.m09#16.o2" to "Seguir subiendo",
    "q.m09#16.o3" to "Suspender la medicación y observar",
    "q.m09#16.e" to "El corticoide tapa los síntomas, pero el proceso sigue avanzando. Seguir subiendo cuando ya han mejorado es el error de juicio más peligroso.",

    "q.m09#17.p" to "¿Por qué «llevar medicación» no es lo mismo que «saber usarla»?",
    "q.m09#17.o0" to "Dosis, indicaciones y contraindicaciones requieren criterio médico; los compañeros no deben recomendarse fármacos entre sí",
    "q.m09#17.o1" to "Porque caduca",
    "q.m09#17.o2" to "Porque pesa",
    "q.m09#17.o3" to "Porque el prospecto es difícil",
    "q.m09#17.e" to "En altitud hay muchas trampas: alergia a sulfamidas, asma, interacciones. Tomar algo sin evaluación puede tener más riesgo que beneficio.",

    "q.m09#18.p" to "¿Qué papel tiene la aspirina en altitud?",
    "q.m09#18.o0" to "Aliviar el dolor de cabeza; es tratamiento sintomático y no cambia el curso",
    "q.m09#18.o1" to "Prevenir el HAPE",
    "q.m09#18.o2" to "Tratar el HACE",
    "q.m09#18.o3" to "Subir la saturación de oxígeno",
    "q.m09#18.e" to "Conviene tener claro qué es sintomático: te hace sentir mejor, pero no significa que puedas seguir subiendo.",

    "q.m09#19.p" to "¿Cuándo es la opción más segura «no tomar nada y descender cuanto antes»?",
    "q.m09#19.o0" to "Cuando los síntomas son graves, no se puede determinar la causa o no hay criterio médico",
    "q.m09#19.o1" to "Siempre",
    "q.m09#19.o2" to "Solo en casos leves",
    "q.m09#19.o3" to "Solo si el descenso es cómodo",
    "q.m09#19.e" to "El descenso es la única medida con eficacia segura. Cuando la medicación pasa a ser «a ojo», descender siempre es el camino más seguro.",
    // ---------- l9 Nudos básicos ----------
    "q.l9#10.p" to "¿Qué ventaja tiene el nudo de ocho (figure-eight) frente al nudo simple?",
    "q.l9#10.o0" to "Se deshace con relativa facilidad tras cargarlo y su estructura es clara y fácil de revisar",
    "q.l9#10.o1" to "Es más pequeño",
    "q.l9#10.o2" to "Gasta menos cuerda",
    "q.l9#10.o3" to "No necesita remate",
    "q.l9#10.e" to "El nudo simple se aprieta bajo carga y en el campo cuesta mucho deshacerlo. El de ocho sigue desmontándose después de trabajar, y por eso es el nudo de unión estándar.",

    "q.l9#11.p" to "¿Dónde se hace normalmente el nudo de tope (stopper knot)?",
    "q.l9#11.o0" to "En el extremo de la cuerda, para que el cabo no se salga del dispositivo",
    "q.l9#11.o1" to "En el centro de la cuerda",
    "q.l9#11.o2" to "En la reunión",
    "q.l9#11.o3" to "En el anillo del arnés",
    "q.l9#11.e" to "Al rapelar, destensar o subir en top rope el cabo puede escaparse. El nudo de tope es el último seguro mecánico.",

    "q.l9#12.p" to "¿Para qué se usa principalmente el nudo de pescador doble?",
    "q.l9#12.o0" to "Para unir dos cuerdas de diámetro parecido",
    "q.l9#12.o1" to "Para unir cuerda y arnés",
    "q.l9#12.o2" to "Como nudo autobloqueante",
    "q.l9#12.o3" to "Para fijar una reunión",
    "q.l9#12.e" to "Es compacto y pasa bien por los dispositivos, y va bien para cordinos y cintas. Pero cuesta deshacerlo tras cargarlo, así que hay que dejar cabo suficiente.",

    "q.l9#13.p" to "¿Qué hay que hacer siempre después de hacer un nudo?",
    "q.l9#13.o0" to "Revisar el trazado y la longitud de los cabos, repasándolo punto por punto en voz alta",
    "q.l9#13.o1" to "Tirar una vez y listo",
    "q.l9#13.o2" to "Hacer una foto como prueba",
    "q.l9#13.o3" to "Encerarlo",
    "q.l9#13.e" to "«Bien hecho» y «terminado» son dos cosas distintas. Un cabo demasiado corto se escurre bajo carga; la revisión tiene que ser un gesto fijo.",

    "q.l9#14.p" to "¿Por qué el punto donde hay un nudo se convierte en el eslabón débil del sistema?",
    "q.l9#14.o0" to "Porque el nudo curva la cuerda y su resistencia baja de forma clara",
    "q.l9#14.o1" to "Porque el nudo pesa",
    "q.l9#14.o2" to "Por el color",
    "q.l9#14.o3" to "Porque la fricción genera calor",
    "q.l9#14.e" to "En el nudo la cuerda va curvada y la carga se reparte mal. Al diseñar el sistema, el nudo va en una posición de poca carga, no en el punto que lo soporta todo.",

    "q.l9#15.p" to "¿Cuál es la característica más importante de un nudo autobloqueante (prusik y similares)?",
    "q.l9#15.o0" to "Muerde la cuerda principal bajo carga y se puede desplazar sin carga: sirve como respaldo de una sola dirección",
    "q.l9#15.o1" to "Se bloquea siempre",
    "q.l9#15.o2" to "Cuanto más grueso, mejor",
    "q.l9#15.o3" to "Solo vale para descender",
    "q.l9#15.e" to "Su valor está en la unilateralidad: bloquea con carga y se mueve en vacío. De ahí que sirva como respaldo y para subir.",

    // ---------- l10 Arnés y sistema de cordada ----------
    "q.l10#10.p" to "¿A qué se refiere el «refilado» que hay que comprobar tras ponerse el arnés?",
    "q.l10#10.o0" to "Si las hebillas del cinturón y de las perneras están refiladas por los dos anillos y queda cinta suficiente de sobra",
    "q.l10#10.o1" to "Si el mosquetón de seguridad está cerrado",
    "q.l10#10.o2" to "Si el nudo está apretado",
    "q.l10#10.o3" to "Si el casco está abrochado",
    "q.l10#10.e" to "El refilado incompleto es el error de arnés más común en principiantes: parece puesto, pero cede bajo carga.",

    "q.l10#11.p" to "Al avanzar en cordada, ¿qué se hace con el cabo de cuerda?",
    "q.l10#11.o0" to "Fijarlo a la bolsa de cuerda o al cuerpo, para que no arrastre por el suelo",
    "q.l10#11.o1" to "Dejarlo arrastrando por la nieve",
    "q.l10#11.o2" to "Extenderlo del todo",
    "q.l10#11.o3" to "Enrollarlo en la mano",
    "q.l10#11.e" to "Un cabo que arrastra se engancha en los crampones, en la roca y en los puentes de nieve, y en una caída se convierte en lazo. Recogerlo es disciplina básica.",

    "q.l10#12.p" to "¿Por qué la distancia entre miembros de la cordada no debe ser demasiado corta?",
    "q.l10#12.o0" to "Si una persona cae en una grieta arrastra directamente a los compañeros y no queda espacio para el rescate",
    "q.l10#12.o1" to "Porque no llega la cuerda",
    "q.l10#12.o2" to "Porque no se avanza rápido",
    "q.l10#12.o3" to "Porque queda feo",
    "q.l10#12.e" to "La distancia es la distancia de reacción. Demasiado corta ata a dos personas como un solo peso; demasiado larga complica el frenado y la comunicación.",

    "q.l10#13.p" to "Al pasar de la cordada al aseguramiento de punta, ¿qué se monta primero?",
    "q.l10#13.o0" to "Una reunión fiable y el autoaseguramiento",
    "q.l10#13.o1" to "La cuerda",
    "q.l10#13.o2" to "La comunicación",
    "q.l10#13.o3" to "La foto",
    "q.l10#13.e" to "El cambio es un punto de alta siniestralidad: en ese momento no se está ni en cordada ni asegurado. Primero la reunión, después soltar la cuerda.",

    "q.l10#14.p" to "¿Cuándo aumenta el riesgo la cordada?",
    "q.l10#14.o0" to "En pendientes suaves sin riesgo de caída, donde nudos y distancia añaden tropiezos y coste de coordinación",
    "q.l10#14.o1" to "Siempre",
    "q.l10#14.o2" to "Cuando hay grietas",
    "q.l10#14.o3" to "Al bajar",
    "q.l10#14.e" to "La cordada es una herramienta contra las caídas y las grietas. En el terreno equivocado, el estorbo supera al beneficio.",

    "q.l10#15.p" to "¿Qué hay que acordar en grupo antes de encordarse?",
    "q.l10#15.o0" to "Distancia de cuerda, voces, orden para pasar la zona de grietas y señales de alto",
    "q.l10#15.o1" to "La marca del material",
    "q.l10#15.o2" to "La velocidad de marcha",
    "q.l10#15.o3" to "El reparto de las fotos",
    "q.l10#15.e" to "La fiabilidad de la cordada viene de reaccionar igual. Sin voces acordadas, el primer imprevisto se convierte en caos.",

    // ---------- m06 Iniciación a la escalada técnica ----------
    "q.m06#10.p" to "En los tres sistemas de la escalada técnica, ¿qué es el «aseguramiento»?",
    "q.m06#10.o0" to "Detener una caída con anclajes y cuerda",
    "q.m06#10.o1" to "Caminar",
    "q.m06#10.o2" to "El gesto de escalar",
    "q.m06#10.o3" to "Comprar material",
    "q.m06#10.e" to "Movimiento, autoaseguramiento y aseguramiento del compañero (belay) forman un círculo cerrado: saber moverse, saber asegurarse y saber asegurar a otro. Si falta uno, no se domina la escalada técnica.",

    "q.m06#11.p" to "¿Por qué el orden habitual de un curso técnico es «primero frenar, luego escalar»?",
    "q.m06#11.o0" to "Porque la caída por deslizamiento es el peligro más frecuente y la autorretención es la capacidad básica",
    "q.m06#11.o1" to "Porque escalar es más difícil",
    "q.m06#11.o2" to "Por el orden del material",
    "q.m06#11.o3" to "Porque lo dicen los manuales",
    "q.m06#11.e" to "Saber escalar pero no saber parar multiplica el riesgo. Autorretención, cordada y aseguramiento — habilidades que no se usan cuando todo va bien — tienen que estar automatizadas primero.",

    "q.m06#12.p" to "¿Qué valor tiene repetir las maniobras en terreno seguro?",
    "q.m06#12.o0" to "Convierte el gesto en un reflejo que no exige pensar; solo entonces queda atención para decidir en una situación real",
    "q.m06#12.o1" to "Para pasar el tiempo",
    "q.m06#12.o2" to "Para hacer fotos",
    "q.m06#12.o3" to "Para conocer los precios del material",
    "q.m06#12.e" to "En una situación real la atención está ocupada por el tiempo, la fatiga y el miedo. Solo lo que sale automático aparece en el momento decisivo.",

    // ---------- m07 Fundamentos de la reunión ----------
    "q.m07#12.p" to "¿Hacia dónde debe mirar el gatillo de un mosquetón de seguridad?",
    "q.m07#12.o0" to "Hacia fuera de la pared, lejos del roce y de la dirección de carga, para que ni la cuerda ni una arista lo abran",
    "q.m07#12.o1" to "Hacia arriba",
    "q.m07#12.o2" to "Hacia abajo",
    "q.m07#12.o3" to "Da igual",
    "q.m07#12.e" to "Que una fuerza externa abra el gatillo es un modo de fallo real. Elegir mal la orientación es dejar la fiabilidad en manos de la suerte.",

    "q.m07#13.p" to "Al unir dos anclajes con una cinta, ¿por qué no debe pasar por una arista afilada?",
    "q.m07#13.o0" to "Porque la arista corta la cinta y su resistencia cae mucho bajo carga",
    "q.m07#13.o1" to "Porque queda feo",
    "q.m07#13.o2" to "Porque resbala",
    "q.m07#13.o3" to "Porque es demasiado corta",
    "q.m07#13.e" to "Con un pequeño corte la resistencia puede quedar en la mitad. Si hay que pasar por ahí, se añade funda o se alarga con una cadena.",

    "q.m07#14.p" to "¿En qué ángulo se clava normalmente un tornillo de hielo?",
    "q.m07#14.o0" to "Ligeramente hacia arriba (unos 10–15 grados), en sentido contrario a la carga",
    "q.m07#14.o1" to "Totalmente horizontal",
    "q.m07#14.o2" to "Inclinado hacia abajo",
    "q.m07#14.o3" to "Da igual",
    "q.m07#14.e" to "Ligeramente hacia arriba el tornillo sigue la dirección de la carga y se aprieta contra el hielo en lugar de salir arrancado. Con hielo malo, más largo y más inclinado.",

    "q.m07#15.p" to "La reunión tiene un solo anclaje. ¿Qué es lo más importante?",
    "q.m07#15.o0" to "Añadir un respaldo independiente o buscar un terreno más fiable",
    "q.m07#15.o1" to "Usarla tal cual",
    "q.m07#15.o2" to "Colgar más mosquetones",
    "q.m07#15.o3" to "Acortar la cuerda",
    "q.m07#15.e" to "El número de mosquetones no es redundancia. La redundancia exige que las causas de fallo sean distintas.",

    // ---------- m08 Montañas objetivo: Gangshika y Haba ----------
    "q.m08#12.p" to "En montañas de 5.000 m como Gangshika y Haba, ¿qué hay que planificar antes?",
    "q.m08#12.o0" to "El ritmo de aclimatación y la ventana de buen tiempo, no la dificultad técnica",
    "q.m08#12.o1" to "La compra del material",
    "q.m08#12.o2" to "Los puntos de foto",
    "q.m08#12.o3" to "El reparto de tareas",
    "q.m08#12.e" to "La dificultad de un 5.000 está casi siempre en la altura y el tiempo, no en la técnica. Invertir tiempo en aclimatar sale mejor que ensayar otra maniobra.",

    "q.m08#13.p" to "Sobre permisos y obligación de guía, ¿qué es lo correcto?",
    "q.m08#13.o0" to "Confirmar antes las normas locales y cumplir estrictamente lo que exija guía o registro",
    "q.m08#13.o1" to "Preguntar al llegar",
    "q.m08#13.o2" to "Rodear el control",
    "q.m08#13.o3" to "Pedir a un conocido que haga una excepción",
    "q.m08#13.e" to "Muchos 5.000 exigen registro o guía. Escalar sin permiso deja sin efecto a la vez el rescate y el seguro.",

    "q.m08#14.p" to "¿Cuál es la lógica de un itinerario progresivo del tipo «pico secundario, luego el principal»?",
    "q.m08#14.o0" to "Validar aclimatación y forma física en una ruta más fácil y después añadir la dificultad técnica",
    "q.m08#14.o1" to "Porque es más barato",
    "q.m08#14.o2" to "Porque está más cerca",
    "q.m08#14.o3" to "Porque hay más gente",
    "q.m08#14.e" to "La esencia de progresar es cambiar una sola variable cada vez. Si suben a la vez la altura y la dificultad técnica, cuando hay un problema cuesta saber por qué.",

    "q.m08#15.p" to "¿Qué información sobre la retirada hay que tener clara antes de salir?",
    "q.m08#15.o0" to "Ruta de descenso, ubicación de los campamentos de reserva, punto médico más cercano y contactos",
    "q.m08#15.o1" to "Solo la ruta de descenso",
    "q.m08#15.o2" to "Solo el punto médico",
    "q.m08#15.o3" to "Nada de eso",
    "q.m08#15.e" to "Retirarse no es simplemente volver. Cuando el tiempo empeora, el campamento de reserva más cercano puede ser la única opción viable.",
    // ---------- l11 Principios de la reunión: SRENE / EARNEST ----------
    "q.l11#12.p" to "Con dos puntos de anclaje y un ángulo de 0° (paralelos), ¿cuánta carga soporta cada uno?",
    "q.l11#12.o0" to "Un 50 % cada uno",
    "q.l11#12.o1" to "Un 71 % cada uno",
    "q.l11#12.o2" to "Un 100 % cada uno",
    "q.l11#12.o3" to "Un 25 % cada uno",
    "q.l11#12.e" to "Cuanto menor el ángulo, más se reparte la carga por igual. De ahí la regla de «mantener el ángulo de la cinta por debajo de 60°».",

    "q.l11#13.p" to "Con un ángulo de 60°, ¿qué carga soporta cada punto aproximadamente?",
    "q.l11#13.o0" to "Un 58 %",
    "q.l11#13.o1" to "Un 50 %",
    "q.l11#13.o2" to "Un 71 %",
    "q.l11#13.o3" to "Un 100 %",
    "q.l11#13.e" to "Del 50 % a 0° se pasa al 58 % a 60° y al 71 % a 90°: la carga sube rápido con el ángulo.",

    "q.l11#14.p" to "¿Por qué hay que «pretensar» la reunión?",
    "q.l11#14.o0" to "Para que, si falla un punto, no haya una extensión brusca y los demás sigan en su sitio",
    "q.l11#14.o1" to "Porque queda mejor",
    "q.l11#14.o2" to "Para ahorrar cuerda",
    "q.l11#14.o3" to "Para desmontarla más fácil",
    "q.l11#14.e" to "Un sistema flojo genera al cargarse un pico de choque mucho mayor que la carga estática. Eso es exactamente lo que dice el principio de no extensión.",

    "q.l11#15.p" to "Tres puntos de anclaje son mejores que dos siempre que...",
    "q.l11#15.o0" to "Los tres sean independientes, con causas de fallo distintas y carga equilibrada",
    "q.l11#15.o1" to "Cuantos más, mejor",
    "q.l11#15.o2" to "Basta con colgarlos",
    "q.l11#15.o3" to "Se unan con una sola cinta",
    "q.l11#15.e" to "Si los tres se encadenan en una sola cinta, un fallo sigue arrastrando todo. Cantidad no es redundancia.",

    "q.l11#16.p" to "¿Cómo debe trabajar un mosquetón de seguridad dentro de la reunión?",
    "q.l11#16.o0" to "A lo largo de su eje mayor, evitando que el gatillo trabaje de lado",
    "q.l11#16.o1" to "De través",
    "q.l11#16.o2" to "En cualquier dirección",
    "q.l11#16.o3" to "Colgado solo del lado del gatillo",
    "q.l11#16.e" to "La resistencia nominal del mosquetón es la del eje mayor. Cargado de través puede quedarse en un tercio, y el riesgo de que se abra el gatillo es mayor.",

    "q.l11#17.p" to "En un anclaje natural (árbol, pilastra), ¿qué hay que confirmar sobre todo?",
    "q.l11#17.o0" to "La solidez del conjunto y el estado de la base, no que «parezca grueso»",
    "q.l11#17.o1" to "El color de la corteza",
    "q.l11#17.o2" to "La altura",
    "q.l11#17.o3" to "Que quede bonito",
    "q.l11#17.e" to "Raíces muertas, troncos huecos o pilastras aflojadas por hielo y deshielo pueden parecer perfectos. Golpear con el mango del piolet y escuchar es una comprobación habitual.",

    "q.l11#18.p" to "¿De qué depende sobre todo la fiabilidad de un anclaje en nieve (estaca, ancla enterrada)?",
    "q.l11#18.o0" to "De la resistencia del manto, de la calidad de la instalación y de los cambios de temperatura",
    "q.l11#18.o1" to "Del color de la cuerda",
    "q.l11#18.o2" to "De cuánto se entierre",
    "q.l11#18.o3" to "De la marca de la estaca",
    "q.l11#18.e" to "Con el deshielo un tramo entero puede fallar; de ahí la regla de no quedarse sobre un sistema de anclajes de nieve por la tarde.",

    "q.l11#19.p" to "¿Qué riesgo real tiene montar la reunión despacio?",
    "q.l11#19.o0" to "Más tiempo expuesto, con el riesgo de piedra, de tiempo y de hipotermia subiendo a la vez",
    "q.l11#19.o1" to "Ninguno",
    "q.l11#19.o2" to "Solo un problema de eficiencia",
    "q.l11#19.o3" to "Afecta al ánimo",
    "q.l11#19.e" to "La reunión es una posición expuesta. Automatizar el procedimiento no es por rapidez, es para pasar menos tiempo dentro del peligro.",

    // ---------- l12 Grietas y progresión en cordada ----------
    "q.l12#12.p" to "Al pasar una zona con muchas grietas, ¿cómo se organiza el grupo?",
    "q.l12#12.o0" to "De uno en uno, con una sola persona en el tramo de riesgo cada vez",
    "q.l12#12.o1" to "Todo el grupo en paralelo",
    "q.l12#12.o2" to "Todos a la vez y rápido",
    "q.l12#12.o3" to "Por parejas, hombro con hombro",
    "q.l12#12.e" to "«De uno en uno» baja al mínimo la carga sobre el sistema y deja margen de reacción para frenar y rescatar.",

    "q.l12#13.p" to "¿Cada cuánto se hacen nudos en la cuerda?",
    "q.l12#13.o0" to "Cada 2–3 metros",
    "q.l12#13.o1" to "Cada 20 metros",
    "q.l12#13.o2" to "Solo en los extremos",
    "q.l12#13.o3" to "No hacen falta",
    "q.l12#13.e" to "Los nudos frecuentes añaden roce y puntos de enganche en una caída y reducen la profundidad de la caída. El precio es que la cuerda corre algo peor.",

    "q.l12#14.p" to "Un compañero ha caído en una grieta y estás frenando. ¿Qué postura hay que mantener?",
    "q.l12#14.o0" to "Boca abajo, centro de gravedad bajo y piolet clavado en la nieve",
    "q.l12#14.o1" to "De pie",
    "q.l12#14.o2" to "Sentado",
    "q.l12#14.o3" to "Boca arriba",
    "q.l12#14.e" to "Boca abajo el peso se convierte en rozamiento y el piolet clavado da un punto extra. De pie te arrastran directamente.",

    "q.l12#15.p" to "¿Cuál es la combinación de material clave en un rescate con sistema Z (3:1)?",
    "q.l12#15.o0" to "Nudo autobloqueante, polea (o mosquetón) y autobloqueante de respaldo",
    "q.l12#15.o1" to "Dos piolets",
    "q.l12#15.o2" to "Bloqueador y escala de cuerda",
    "q.l12#15.o3" to "Pala y sonda",
    "q.l12#15.e" to "El 3:1 se consigue con «polipasto más bloqueador unidireccional». Sin bloqueador, la cuerda que izas vuelve a irse en el acto.",

    "q.l12#16.p" to "Una vez detenida la persona que ha caído, ¿qué se hace primero?",
    "q.l12#16.o0" to "Comprobar conciencia y lesiones y hacer que se autoasegure (nudo o piolet)",
    "q.l12#16.o1" to "Empezar a izar de inmediato",
    "q.l12#16.o2" to "Que suba por su cuenta",
    "q.l12#16.o3" to "Aflojar la cuerda",
    "q.l12#16.e" to "Primero hay que conseguir que deje de depender de la cuerda; solo entonces el rescatador tiene las manos libres para montar el sistema. Izar es el paso siguiente.",

    "q.l12#17.p" to "¿Por qué se insiste tanto en la comunicación en un rescate de grieta?",
    "q.l12#17.o0" to "Porque la longitud de cuerda y el ruido invalidan la voz y hay que pactar señales con tirones",
    "q.l12#17.o1" to "Porque hay que conversar",
    "q.l12#17.o2" to "Porque los walkie-talkies son caros",
    "q.l12#17.o3" to "Porque el compañero tendrá miedo",
    "q.l12#17.e" to "Lo habitual es un tirón «alto», dos «izad» y tres «dad cuerda». Pactarlo antes evita el caos en el momento.",

    "q.l12#18.p" to "Al avanzar por zona de grietas, ¿en qué estado debe estar la cuerda?",
    "q.l12#18.o0" to "Con tensión moderada: ni arrastrando ni demasiado floja",
    "q.l12#18.o1" to "Arrastrando por completo",
    "q.l12#18.o2" to "Completamente tensa",
    "q.l12#18.o3" to "Recogida",
    "q.l12#18.e" to "Arrastrando se engancha en las puntas o en la roca; tensa de más, os tiráis unos a otros. La tensión moderada es la condición para poder frenar en el acto.",

    "q.l12#19.p" to "¿Por qué el final del glaciar y la zona de seracs se pasan normalmente de madrugada?",
    "q.l12#19.o0" to "Porque el frío mantiene más estables los puentes de nieve y el hielo, y caen menos bloques",
    "q.l12#19.o1" to "Porque hay menos gente",
    "q.l12#19.o2" to "Porque no da el sol",
    "q.l12#19.o3" to "Porque es la costumbre de los guías",
    "q.l12#19.e" to "La temperatura es la variable clave de la estabilidad. Por la tarde el deshielo y la caída de bloques aumentan claramente el riesgo.",

    // ---------- l18 Fundamentos de aludes e identificación ----------
    "q.l18#13.p" to "¿Por qué es más fácil que se forme una capa peligrosa en una ladera a sotavento?",
    "q.l18#13.o0" to "Porque el viento transporta la nieve y la acumula en el lado de sotavento en cornisas y en capas blandas sobre duras",
    "q.l18#13.o1" to "Porque hace más frío",
    "q.l18#13.o2" to "Porque la nieve es más húmeda",
    "q.l18#13.o3" to "Porque hay menos gente",
    "q.l18#13.e" to "El transporte por viento crea en sotavento una estructura de nieve blanda sobre una capa dura; al dispararse, suele deslizar toda la placa.",

    "q.l18#14.p" to "En la escala de peligro de aludes 1–5, ¿qué significa el nivel 5?",
    "q.l18#14.o0" to "Peligro extremo, aludes naturales generalizados; hay que evitar entrar en terreno de aludes",
    "q.l18#14.o1" to "Peligro leve",
    "q.l18#14.o2" to "Peligro moderado",
    "q.l18#14.o3" to "No se puede valorar",
    "q.l18#14.e" to "El nivel combina probabilidad y tamaño. Nivel 5 no significa «más difícil de subir», sino «no se va».",

    "q.l18#15.p" to "Antes de salir, ¿qué tres datos del boletín de aludes importan más?",
    "q.l18#15.o0" to "El nivel de peligro, el tipo de problema (placa de viento, nieve húmeda) y las orientaciones y cotas peligrosas",
    "q.l18#15.o1" to "Temperatura, humedad y presión",
    "q.l18#15.o2" to "Viento, nubosidad y visibilidad",
    "q.l18#15.o3" to "Longitud, desnivel y duración de la ruta",
    "q.l18#15.e" to "El mensaje central del boletín es «dónde, con qué problema y con qué facilidad se dispara». Quedarse solo con el nivel y no mirar orientaciones es no tener nada.",

    "q.l18#16.p" to "Al cruzar terreno de aludes en grupo, ¿qué es correcto?",
    "q.l18#16.o0" to "Que pase una persona a la vez, con el resto en un punto seguro observando",
    "q.l18#16.o1" to "Que pase todo el grupo junto",
    "q.l18#16.o2" to "En paralelo",
    "q.l18#16.o3" to "Corriendo rápido",
    "q.l18#16.e" to "De uno en uno se reduce al mínimo el número de personas que pueden quedar enterradas. Pasar todos juntos es la forma clásica de amplificar un accidente.",

    "q.l18#17.p" to "¿Cuál es el orden correcto de uso del equipo de rescate de aludes?",
    "q.l18#17.o0" to "Búsqueda con ARVA, localización con sonda y paleo",
    "q.l18#17.o1" to "Palar, sondear y luego buscar",
    "q.l18#17.o2" to "Los tres a la vez",
    "q.l18#17.o3" to "Sondear, buscar y palar",
    "q.l18#17.e" to "Equivocar el orden desperdicia los minutos más valiosos. La búsqueda sirve para «encontrar» y el paleo para «llegar».",

    "q.l18#18.p" to "¿Cuál es la diferencia principal entre un alud húmedo de primavera y uno seco de invierno?",
    "q.l18#18.o0" to "El húmedo es más lento pero denso y con gran capacidad de impacto, y suele caer por la tarde",
    "q.l18#18.o1" to "El húmedo es más rápido",
    "q.l18#18.o2" to "El húmedo no entierra a nadie",
    "q.l18#18.o3" to "No hay diferencia",
    "q.l18#18.e" to "El alud húmedo se dispara a menudo por agua de fusión y radiación solar, con una ventana muy centrada en la tarde. La planificación debe evitar esa franja.",

    "q.l18#19.p" to "¿Qué valor y qué límite tiene un test de manto (por ejemplo, una calicata)?",
    "q.l18#19.o0" to "Da información local, pero no representa toda la ladera",
    "q.l18#19.o1" to "Permite predecir los aludes por completo",
    "q.l18#19.o2" to "No tiene ningún valor",
    "q.l18#19.o3" to "Solo sirve en primavera",
    "q.l18#19.e" to "Una calicata es información de un punto. La influencia del terreno, la orientación y el viento abarca muchísimo más que un solo hoyo.",

    // ---------- m10 Meteorología de montaña y ventanas de tiempo ----------
    "q.m10#12.p" to "Cuando la humedad relativa roza la saturación, ¿qué significa meteorológicamente?",
    "q.m10#12.o0" to "Que baja la base de las nubes y son fáciles la niebla y la precipitación",
    "q.m10#12.o1" to "Que sube la temperatura",
    "q.m10#12.o2" to "Que amaina el viento",
    "q.m10#12.o3" to "Que sube la presión",
    "q.m10#12.e" to "Saturarse significa que el vapor empieza a condensar. En montaña, «la base de las nubes baja rápido» suele verse antes que «empieza a llover».",

    "q.m10#13.p" to "Tras el paso de un frente frío, ¿qué suele ocurrir?",
    "q.m10#13.o0" to "Baja la temperatura, rota el viento y mejora la visibilidad",
    "q.m10#13.o1" to "Sube la temperatura",
    "q.m10#13.o2" to "Llueve de forma continua",
    "q.m10#13.o3" to "Amaina el viento",
    "q.m10#13.e" to "Detrás del frente suele haber «buen tiempo pero frío y ventoso». De ahí que muchas cordadas subestimen la sensación térmica cuando «mejora el tiempo».",

    "q.m10#14.p" to "¿Qué indican las nubes orográficas (pegadas a la ladera) para la ascensión?",
    "q.m10#14.o0" to "Viento fuerte y humedad alta: puede que la cresta ya no sea transitable",
    "q.m10#14.o1" to "Solo que es bonito",
    "q.m10#14.o2" to "Que el tiempo es estable",
    "q.m10#14.o3" to "Que no tienen relación con el viento",
    "q.m10#14.e" to "Son la visualización de «viento y humedad». Si se ven desplazarse rápido, lo normal es que el viento en la cresta esté fuera de límites.",

    "q.m10#15.p" to "¿Por qué cuanto mayor es el plazo del pronóstico, menos fiable es?",
    "q.m10#15.o0" to "Porque la atmósfera es un sistema caótico y el error crece de forma exponencial con el tiempo",
    "q.m10#15.o1" to "Porque los modelos son malos",
    "q.m10#15.o2" to "Porque faltan datos",
    "q.m10#15.o3" to "Por la altitud",
    "q.m10#15.e" to "La tendencia a tres días es bastante fiable; a partir de siete solo sirve de referencia. La planificación debe dejar tiempo para «esperar la ventana».",

    "q.m10#16.p" to "¿De dónde viene principalmente la diferencia entre los datos de una estación de montaña y la altura a la que vas?",
    "q.m10#16.o0" to "Del desnivel, que cambia temperatura, viento y forma de la precipitación",
    "q.m10#16.o1" to "Del error del instrumento",
    "q.m10#16.o2" to "De la zona horaria",
    "q.m10#16.o3" to "De la latitud",
    "q.m10#16.e" to "La «lluvia débil» de una estación de valle puede ser «nieve fuerte con viento» a 5.000 m. Leer un pronóstico exige convertir la altura.",

    "q.m10#17.p" to "Si oyes el trueno menos de 30 segundos después del relámpago, ¿qué significa?",
    "q.m10#17.o0" to "Que la tormenta está muy cerca y hay que salir del terreno expuesto de inmediato",
    "q.m10#17.o1" to "Que está lejos",
    "q.m10#17.o2" to "Que estás a salvo",
    "q.m10#17.o3" to "Que es casualidad",
    "q.m10#17.e" to "La diferencia entre la velocidad de la luz y la del sonido permite estimar la distancia. Cuanto más corto el intervalo, más cerca; 30 segundos es el umbral de actuación habitual.",

    "q.m10#18.p" to "¿Por qué se suele atacar la cumbre de madrugada?",
    "q.m10#18.o0" to "Porque la nieve helada es más estable y por la tarde suele haber más nubes y viento",
    "q.m10#18.o1" to "Para hacer fotos",
    "q.m10#18.o2" to "Porque hay menos gente",
    "q.m10#18.o3" to "Porque es la costumbre de los guías",
    "q.m10#18.e" to "La nieve dura de la madrugada y la ventana de tiempo estable son el motivo principal. El precio es frío y falta de sueño, y hay que prepararlo.",

    "q.m10#19.p" to "Cuando la ventana de tiempo se estrecha, ¿qué es lo primero que hay que abandonar?",
    "q.m10#19.o0" to "El objetivo de cumbre, no los márgenes de seguridad",
    "q.m10#19.o1" to "La capa de abrigo",
    "q.m10#19.o2" to "El material de respaldo",
    "q.m10#19.o3" to "El equipo de comunicación",
    "q.m10#19.e" to "Con poca ventana lo que se recorta suele ser el margen, y ahí empieza el accidente. El sacrificio correcto es renunciar al objetivo.",

    // ---------- m11 Montañas objetivo: cuatro seismiles ----------
    "q.m11#12.p" to "¿Por qué la cara sur del Yuzhu Feng sirve como primera parada en los 6.000?",
    "q.m11#12.o0" to "Porque la pendiente de nieve es suave, el acceso es posible y la ruta está consolidada",
    "q.m11#12.o1" to "Porque es la más alta",
    "q.m11#12.o2" to "Porque es la más técnica",
    "q.m11#12.o3" to "Porque hay menos gente",
    "q.m11#12.e" to "El objetivo del primer 6.000 es validar aclimatación y forma física, no desafiar la técnica. Una ruta consolidada reduce lo desconocido.",

    "q.m11#13.p" to "¿A qué cordillera pertenece el Qizi Feng?",
    "q.m11#13.o0" to "A la cordillera de Nyainqêntanglha",
    "q.m11#13.o1" to "A la cordillera del Kunlun",
    "q.m11#13.o2" to "Al Himalaya",
    "q.m11#13.o3" to "Al Karakórum",
    "q.m11#13.e" to "El Qizi está en Damxung, Tíbet, en la Nyainqêntanglha. La cordillera determina el clima y la ventana de temporada, y es un dato clave al elegir montaña.",

    "q.m11#14.p" to "¿Para qué se usa más típicamente el Lobuche East?",
    "q.m11#14.o0" to "Como transición y entrenamiento técnico entre los 6.000 y los 8.000",
    "q.m11#14.o1" to "Como ruta turística",
    "q.m11#14.o2" to "Como estación de esquí",
    "q.m11#14.o3" to "Como mirador",
    "q.m11#14.e" to "Está junto a la ruta de trekking del Everest, con pendientes de nieve algo más inclinadas y buen acceso, y es una montaña de transición habitual.",

    "q.m11#15.p" to "¿Cuál es la característica técnica del Island Peak (Imja Tse)?",
    "q.m11#15.o0" to "Exige cordada y progresión por grietas: es un 6.000 técnico clásico",
    "q.m11#15.o1" to "Es solo senderismo",
    "q.m11#15.o2" to "Solo requiere caminar por nieve",
    "q.m11#15.o3" to "No tiene nieve en todo el año",
    "q.m11#15.e" to "Su parte técnica está sobre todo en el glaciar y las grietas, no en la pared. La cordada y el rescate en grieta son capacidades imprescindibles.",

    "q.m11#16.p" to "Al elegir un 6.000, ¿qué importa más que la altitud?",
    "q.m11#16.o0" to "La forma de la ruta (nieve, glaciar, pared) y la dificultad de la retirada",
    "q.m11#16.o1" to "Que el nombre suene bien",
    "q.m11#16.o2" to "La distancia",
    "q.m11#16.o3" to "El coste",
    "q.m11#16.e" to "Dos montañas de 6.100 m pueden exigir cosas de un orden distinto según sean de nieve o de glaciar. Primero la forma, después la altitud.",

    "q.m11#17.p" to "Los requisitos de permiso y guía en los 6.000 suelen ser, frente a los 5.000...",
    "q.m11#17.o0" to "Más estrictos: a menudo exigen registro o guía obligatorio",
    "q.m11#17.o1" to "Más laxos",
    "q.m11#17.o2" to "Exactamente iguales",
    "q.m11#17.o3" to "Inexistentes",
    "q.m11#17.e" to "A más altura y rutas más remotas, más control. Confirmar las normas antes de salir ahorra mucho más que preguntar al pie de la montaña.",

    "q.m11#18.p" to "¿Por qué en un 6.000 hay que «suponer que hay grietas»?",
    "q.m11#18.o0" to "Porque bajo un puente de nieve no se ven y hay que encordarse como si existieran",
    "q.m11#18.o1" to "Porque siempre existen",
    "q.m11#18.o2" to "Porque lo exige el guía",
    "q.m11#18.o3" to "Porque lo exige el seguro",
    "q.m11#18.e" to "«No se ve» no es «no hay». Encordarse cuesta poco; caer en una grieta cuesta muchísimo.",

    "q.m11#19.p" to "La aclimatación en un 6.000 suele ser, frente a un 5.000...",
    "q.m11#19.o0" to "Más larga, porque se duerme más alto y la recuperación es más lenta",
    "q.m11#19.o1" to "Más corta",
    "q.m11#19.o2" to "Igual",
    "q.m11#19.o3" to "Innecesaria",
    "q.m11#19.e" to "Cada escalón de altura exige más tiempo de aclimatación. Trasladar el ritmo de un 5.000 a un 6.000 es una subestimación habitual.",
    // ---------- t01 Dificultad de la ruta y nivel propio ----------
    "q.t01#0.p" to "¿Qué conjunto de datos basta mejor para juzgar la dificultad de una ruta de senderismo?",
    "q.t01#0.o0" to "Los kilómetros",
    "q.t01#0.o1" to "Distancia, desnivel acumulado, tipo de firme y puntos de avituallamiento y salida",
    "q.t01#0.o2" to "La altitud máxima",
    "q.t01#0.o3" to "Lo que tardaron otros",
    "q.t01#0.e" to "Los kilómetros son solo un factor. En los mismos 10 km, 80 m y 800 m de desnivel pueden triplicar el tiempo; y que el firme sea tierra, pedrera o roca resbaladiza decide el riesgo de torcedura.",

    "q.t01#1.p" to "Dos rutas de 10 km: A acumula 80 m de desnivel y B, 800 m. ¿Cuál es la diferencia principal?",
    "q.t01#1.o0" to "Lo bonitas que sean",
    "q.t01#1.o1" to "El tiempo y el gasto de energía: B viene a ser el doble o el triple de A",
    "q.t01#1.o2" to "La altitud",
    "q.t01#1.o3" to "Casi ninguna",
    "q.t01#1.e" to "El desnivel es la variable que más se olvida. Como regla, 100 m de subida equivalen a unos 500 m llanos: 800 m de desnivel son 4 km extra sobre el papel.",

    "q.t01#2.p" to "¿Qué condiciones debería cumplir una ruta para la primera salida?",
    "q.t01#2.o0" to "Poder terminarla en menos de 3 horas",
    "q.t01#2.o1" to "Desnivel acumulado por debajo de 300 m",
    "q.t01#2.o2" to "Que haya carretera o pueblo para abandonar a mitad",
    "q.t01#2.o3" to "Cobertura móvil completa en todo el recorrido",
    "q.t01#2.e" to "Las tres primeras son límites de riesgo controlables. La cobertura es cuestión de suerte y no forma parte del plan: en muchos valles sencillamente no hay.",

    "q.t01#3.p" to "¿Por qué conviene confirmar los puntos de salida antes que las vistas?",
    "q.t01#3.o0" to "Porque allí suele haber aseos",
    "q.t01#3.o1" to "Porque permiten bajar cerca si el tiempo o las fuerzas fallan, sin tener que completar todo el recorrido",
    "q.t01#3.o2" to "Para hacer mejores fotos",
    "q.t01#3.o3" to "Porque lo exige el seguro",
    "q.t01#3.e" to "Un punto de salida convierte «tengo que llegar» en «puedo parar». En el plan debería constar, para cada tramo, dónde está la bajada más cercana y cuánto se tarda en llegar a ella.",

    "q.t01#4.p" to "La misma ruta se vuelve bastante más difícil tras la lluvia. ¿Cuál es el motivo principal?",
    "q.t01#4.o0" to "Baja la temperatura",
    "q.t01#4.o1" to "El firme se vuelve resbaladizo y embarrado y puede haber algún vadeo; suben a la vez el tiempo y el riesgo de torcedura",
    "q.t01#4.o2" to "El paisaje empeora",
    "q.t01#4.o3" to "Hay menos gente",
    "q.t01#4.e" to "La humedad alarga el tiempo y aumenta la probabilidad de resbalón y esguince. Una ruta de cuatro horas pasa a cinco o seis tras la lluvia, y hay que reevaluar varios descensos empinados.",

    "q.t01#5.p" to "Alguien dice «esta ruta la hice en cuatro horas». ¿Cómo hay que entenderlo?",
    "q.t01#5.o0" to "Entonces yo también tardaré cuatro horas",
    "q.t01#5.o1" to "Ese es el ritmo de una persona con experiencia; el grupo debe calcular con el más lento y aplicar un factor de 1,3 a 1,5",
    "q.t01#5.o2" to "Significa que la ruta es fácil",
    "q.t01#5.o3" to "No sirve de referencia en absoluto",
    "q.t01#5.e" to "El tiempo ajeno depende de la forma física, la carga y el conocimiento del terreno. Calcular con el más lento y añadir pausas, fotos y búsqueda de camino se acerca mucho más a la realidad.",

    "q.t01#6.p" to "¿Cuál es el cálculo rápido habitual para estimar el tiempo de una ruta?",
    "q.t01#6.o0" to "Tiempo base por distancia y 30 minutos más por cada 300–500 m de subida",
    "q.t01#6.o1" to "Solo por distancia",
    "q.t01#6.o2" to "Solo por desnivel",
    "q.t01#6.o3" to "Por peso corporal",
    "q.t01#6.e" to "Calcular solo por distancia subestima el coste de subir. Separar el tiempo de distancia y el de desnivel y luego aplicar un factor de grupo reduce mucho el error.",

    "q.t01#7.p" to "¿Por qué hay que tener claros los puntos de salida antes de empezar?",
    "q.t01#7.o0" to "Porque solo con una bajada posible hay seguridad y margen para ajustar",
    "q.t01#7.o1" to "Para las fotos",
    "q.t01#7.o2" to "Para ahorrar en la entrada",
    "q.t01#7.o3" to "Para ir más ligero",
    "q.t01#7.e" to "El punto de salida es la válvula de seguridad de la ruta. Sin él, solo queda seguir hasta el final pase lo que pase.",

    // ---------- t02 Botas, calcetines y pies ----------
    "q.t02#0.p" to "¿Cuál es el criterio clave de ajuste en unas botas de senderismo?",
    "q.t02#0.o0" to "Cuanto más apretadas, más estables",
    "q.t02#0.o1" to "Que el talón no se mueva y que al bajar los dedos no choquen con la puntera",
    "q.t02#0.o2" to "Cuanto más grandes, más cómodas",
    "q.t02#0.o3" to "La marca y el precio",
    "q.t02#0.e" to "Probar por la tarde, con calcetines de senderismo y caminando un tramo cuesta abajo. Si el pie se desliza dentro de la bota, al subir roza el tendón de Aquiles y al bajar chocan los dedos: en ambos sentidos salen ampollas.",

    "q.t02#1.p" to "¿Cuál es la causa más directa de las ampollas?",
    "q.t02#1.o0" to "Que las botas son nuevas",
    "q.t02#1.o1" to "La suma de humedad, roce y presión local",
    "q.t02#1.o2" to "Caminar demasiadas horas",
    "q.t02#1.o3" to "El color de los calcetines",
    "q.t02#1.e" to "Un solo factor rara vez actúa solo. La arena dentro de la bota genera presión local, el sudor ablanda la piel y en media hora aparece la ampolla.",

    "q.t02#2.p" to "¿Cuál es la combinación más eficaz para prevenir ampollas?",
    "q.t02#2.o0" to "Poner esparadrapo en los puntos de roce antes de salir, mantener los calcetines secos y cambiarlos a mitad",
    "q.t02#2.o1" to "Llevar dos pares de calcetines de algodón",
    "q.t02#2.o2" to "Remojarse los pies antes de salir",
    "q.t02#2.o3" to "No parar nunca para no tener que calzarse",
    "q.t02#2.e" to "El esparadrapo traslada el roce de la piel al apósito y el cambio de calcetín resuelve la humedad. Las dos cosas juntas evitan la mayoría de las ampollas.",

    "q.t02#3.p" to "¿Cómo se atan los cordones en un descenso largo?",
    "q.t02#3.o0" to "Más apretados, para que el pie no avance hacia delante",
    "q.t02#3.o1" to "Completamente flojos",
    "q.t02#3.o2" to "Igual que al subir",
    "q.t02#3.o3" to "Solo la parte del tobillo",
    "q.t02#3.e" to "Al bajar el pie se desplaza hacia la puntera. Apretar la zona media y el tobillo y dejar algo más flojo el empeine sujeta el talón sin oprimir el dorso del pie.",

    "q.t02#4.p" to "Aparece un punto caliente en el pie: enrojecido, caliente y algo doloroso al presionar. ¿Qué se hace?",
    "q.t02#4.o0" to "Parar de inmediato y tratarlo",
    "q.t02#4.o1" to "Poner esparadrapo o un apósito",
    "q.t02#4.o2" to "Revisar botas y calcetines en busca de arrugas y arena",
    "q.t02#4.o3" to "Seguir hasta que se abra",
    "q.t02#4.e" to "Un punto caliente es una fase reversible y se resuelve en dos minutos. Cuando la piel ya está abierta, la herida crece con cada paso y puede infectarse.",

    "q.t02#5.p" to "¿Por qué no se recomiendan calcetines de algodón en rutas largas?",
    "q.t02#5.o0" to "Porque el algodón absorbe el sudor y no lo evacua; mojado roza más y deja de abrigar",
    "q.t02#5.o1" to "Porque son caros",
    "q.t02#5.o2" to "Porque no transpiran y huelen",
    "q.t02#5.o3" to "Porque destiñen",
    "q.t02#5.e" to "La fibra de algodón mojada se pega a la piel y sube el coeficiente de rozamiento; si baja la temperatura, el calcetín húmedo roba calor muy rápido. La lana o la fibra sintética evacuan y aún abrigan mojadas.",

    "q.t02#6.p" to "¿Para qué sirve el atado «heel lock» (bloqueo de talón)?",
    "q.t02#6.o0" to "Para fijar el talón al contrafuerte y que los dedos choquen menos al bajar",
    "q.t02#6.o1" to "Para que la bota quede más apretada",
    "q.t02#6.o2" to "Para calzarse más rápido",
    "q.t02#6.o3" to "Para reducir el desgaste",
    "q.t02#6.e" to "Al bajar el pie avanza y el choque repetido de los dedos es la causa principal de uñas negras y ampollas. El bloqueo de talón lo resuelve directamente.",

    "q.t02#7.p" to "¿Cuánto espacio conviene dejar delante de los dedos al comprar botas?",
    "q.t02#7.o0" to "Un dedo de ancho aproximadamente, porque el pie se hincha en rutas largas",
    "q.t02#7.o1" to "Que queden justas",
    "q.t02#7.o2" to "Una talla más",
    "q.t02#7.o3" to "Dos tallas más",
    "q.t02#7.e" to "Tras muchas horas el pie se hincha ligeramente. Un dedo de margen evita el choque en los descensos sin que la bota quede tan holgada que roce.",

    // ---------- t03 Mochila y carga ----------
    "q.t03#0.p" to "¿Cuál es el límite habitual de carga en senderismo?",
    "q.t03#0.o0" to "10–20 % del peso corporal, con los principiantes en el límite bajo",
    "q.t03#0.o1" to "Cuanto más peso, más seguridad",
    "q.t03#0.o2" to "30 % del peso corporal",
    "q.t03#0.o3" to "No hay límite",
    "q.t03#0.e" to "El peso se traduce directamente en carga articular y consumo de oxígeno. Para la primera travesía de varios días, mantener la mochila en un 12–15 % del peso corporal: si al terminar aún quedaban reservas, la cantidad era la correcta.",

    "q.t03#1.p" to "¿Dónde va el peso dentro de la mochila?",
    "q.t03#1.o0" to "Pegado a la espalda, entre los omóplatos y la cintura",
    "q.t03#1.o1" to "En el fondo",
    "q.t03#1.o2" to "En la parte exterior",
    "q.t03#1.o3" to "En el bolsillo superior",
    "q.t03#1.e" to "Pegado a la espalda y a la altura del centro de gravedad, la mochila oscila menos al caminar. En el fondo tira hacia abajo y carga la zona lumbar; por fuera desplaza el centro de gravedad y la espalda y el cuello compensan.",

    "q.t03#2.p" to "¿Cómo se reparte el trabajo entre tirantes y cinturón?",
    "q.t03#2.o0" to "Los tirantes cargan el peso",
    "q.t03#2.o1" to "El cinturón soporta la mayor parte y los tirantes mantienen y estabilizan",
    "q.t03#2.o2" to "El cinturón es solo decorativo",
    "q.t03#2.o3" to "Da igual uno u otro",
    "q.t03#2.e" to "El cinturón pasa el peso a la pelvis, la parte del cuerpo que mejor lo soporta. Unos tirantes demasiado apretados comprimen los vasos del hombro y a las horas los brazos se duermen.",

    "q.t03#3.p" to "¿Qué va en el bolsillo superior o colgado por fuera?",
    "q.t03#3.o0" to "Chubasquero, mapa, frontal",
    "q.t03#3.o1" to "El agua y la comida del día",
    "q.t03#3.o2" to "Los varillajes de la tienda cruzados por fuera",
    "q.t03#3.o3" to "La cantimplora más pesada",
    "q.t03#3.e" to "El bolsillo superior y el exterior son para lo que se usa a cada rato o para lo que tiene forma rara. El peso por fuera rompe el centro de gravedad y se engancha en ramas y roca.",

    "q.t03#4.p" to "¿Qué consecuencia tiene que la mochila no quede pegada a la espalda?",
    "q.t03#4.o0" to "El centro de gravedad se va atrás, la espalda y el cuello compensan y el descenso es más inestable",
    "q.t03#4.o1" to "Solo queda feo",
    "q.t03#4.o2" to "El volumen se reduce",
    "q.t03#4.o3" to "No tiene ninguna consecuencia",
    "q.t03#4.e" to "Si queda un hueco entre el panel y la espalda, la mochila oscila con cada paso. Para estabilizarla uno se inclina hacia delante y sube los hombros, y a las pocas horas la espalda duele primero.",

    "q.t03#5.p" to "¿Por qué conviene pesar la mochila antes de salir?",
    "q.t03#5.o0" to "Porque solo con un peso de referencia se puede juzgar qué sobra",
    "q.t03#5.o1" to "Porque lo revisan en el aeropuerto",
    "q.t03#5.o2" to "Para las redes sociales",
    "q.t03#5.o3" to "No tiene ninguna utilidad práctica",
    "q.t03#5.e" to "Pesar convierte «pesa algo» en un número. Con la misma mochila, quitar el menaje duplicado, ropa sobrante y botellas llenas suele ahorrar dos o tres kilos.",

    "q.t03#6.p" to "¿Qué porcentaje del peso corporal se cita a menudo como límite para una mochila de senderismo?",
    "q.t03#6.o0" to "20–25 %",
    "q.t03#6.o1" to "10 %",
    "q.t03#6.o2" to "40 %",
    "q.t03#6.o3" to "No hay límite",
    "q.t03#6.e" to "Por encima de esa proporción suben claramente el gasto energético en las subidas y el riesgo de lesión. Aligerar empieza por el material que no se lleva.",

    "q.t03#7.p" to "¿Para qué sirven sobre todo los bastones al bajar?",
    "q.t03#7.o0" to "Para descargar las rodillas y dar un punto de apoyo más",
    "q.t03#7.o1" to "Para ir más rápido",
    "q.t03#7.o2" to "Para reducir el peso de la mochila",
    "q.t03#7.o3" to "Para defenderse",
    "q.t03#7.e" to "Al bajar, las rodillas reciben varias veces las fuerzas de la subida. Los bastones pasan parte de la carga al tren superior y añaden un tercer punto de contacto.",

    // ---------- t04 Ritmo, hidratación y energía ----------
    "q.t04#0.p" to "¿Cómo se mantiene un ritmo sostenible en una subida?",
    "q.t04#0.o0" to "Con una intensidad que permita hablar en frases completas, descansando antes de agotarse",
    "q.t04#0.o1" to "Subir de una sola tirada hasta arriba y descansar allí",
    "q.t04#0.o2" to "Ir con la persona más rápida",
    "q.t04#0.o3" to "Mantener un ritmo muy lento todo el rato",
    "q.t04#0.e" to "La prueba del habla es la medida de intensidad más sencilla. Si no puedes decir una frase entera, baja el ritmo; si paras cuando ya te falta el aire, tardas mucho más en recuperarte.",

    "q.t04#1.p" to "¿Cuál es el ritmo correcto para beber?",
    "q.t04#1.o0" to "Beber cuando se tiene sed",
    "q.t04#1.o1" to "Pequeños sorbos cada 20–30 minutos, con electrolitos si hace calor",
    "q.t04#1.o2" to "Beber un litro de una vez",
    "q.t04#1.o3" to "Beber lo mínimo para ir menos al baño",
    "q.t04#1.e" to "Cuando aparece la sed ya falta un 1–2 % del peso corporal en agua y el juicio y la resistencia empiezan a caer. Los sorbos pequeños y regulares se absorben mejor que un litro de golpe.",

    "q.t04#2.p" to "¿Cómo se aporta energía de forma más eficaz durante la marcha?",
    "q.t04#2.o0" to "30–60 g de hidratos por hora, en pequeñas cantidades",
    "q.t04#2.o1" to "Una comida copiosa cuando llega el hambre",
    "q.t04#2.o2" to "Solo bebidas deportivas",
    "q.t04#2.o3" to "Aguantar con fuerza de voluntad hasta el campamento",
    "q.t04#2.e" to "El cuerpo solo absorbe una cantidad limitada de hidratos por hora; demasiado de golpe hincha el estómago. Comer caminando —frutos secos, barritas, pan— es más fiable que una gran parada para comer.",

    "q.t04#3.p" to "¿Cuáles son las señales tempranas de una bajada de azúcar?",
    "q.t04#3.o0" to "Temblor en las manos y sudor frío",
    "q.t04#3.o1" to "Irritabilidad repentina o reacciones más lentas",
    "q.t04#3.o2" to "Visión blanca y flotante",
    "q.t04#3.o3" to "Más energía de repente",
    "q.t04#3.e" to "Si aparecen, parar y tomar 15–20 g de hidratos rápidos (azúcar, zumo); en diez minutos mejora claramente. Seguir apretando puede acabar en desmayo.",

    "q.t04#4.p" to "¿Por qué las pausas no deberían durar más de diez minutos?",
    "q.t04#4.o0" to "El cuerpo se enfría, los músculos se agarrotan y retomar cuesta más",
    "q.t04#4.o1" to "Los compañeros se quejan",
    "q.t04#4.o2" to "Se pierde tiempo",
    "q.t04#4.o3" to "No hay ningún motivo",
    "q.t04#4.e" to "Tras un parón largo bajan la frecuencia cardíaca y la temperatura muscular, y el primer kilómetro pesa mucho más. Varias pausas cortas cuestan menos tiempo total que una larga.",

    "q.t04#5.p" to "¿Cuándo aparece típicamente el «muro» en una caminata?",
    "q.t04#5.o0" to "A las dos o tres horas, cuando se agota el glucógeno y apenas se ha comido nada antes",
    "q.t04#5.o1" to "El primer día antes de salir",
    "q.t04#5.o2" to "Al bajar",
    "q.t04#5.o3" to "Con falta de sueño",
    "q.t04#5.e" to "Las reservas de glucógeno alcanzan para unos 90–120 minutos de esfuerzo moderado. Quien no aporta hidratos después nota una caída brusca de fuerza, mareo y ganas de no hablar.",

    "q.t04#6.p" to "¿Cuál es el indicador subjetivo más práctico de que el ritmo es el adecuado?",
    "q.t04#6.o0" to "La prueba del habla: todavía se pueden decir frases completas",
    "q.t04#6.o1" to "La cifra de frecuencia cardíaca",
    "q.t04#6.o2" to "La cantidad de sudor",
    "q.t04#6.o3" to "La cadencia de pasos",
    "q.t04#6.e" to "Hablar en frases completas indica que sigues en zona aeróbica. Si no puedes hablar, la intensidad es excesiva y en rutas largas te vaciarás antes.",

    "q.t04#7.p" to "¿Cuándo se olvidan más los electrolitos con calor?",
    "q.t04#7.o0" to "Antes de salir y en la primera mitad de la ruta, no cuando ya aparecen los calambres",
    "q.t04#7.o1" to "Después de bajar",
    "q.t04#7.o2" to "Antes de dormir",
    "q.t04#7.o3" to "Al comer",
    "q.t04#7.e" to "Los calambres indican que el déficit ya existe. Poco, pronto y repartido durante toda la ruta funciona mejor que beber mucho al final.",

    // ---------- t15 Mapa y navegación en la práctica ----------
    "q.t15#0.p" to "¿Qué es lo más importante que hay que hacer con los mapas del móvil antes de entrar en la montaña?",
    "q.t15#0.o0" to "Descargar los mapas sin conexión y comprobar que la localización funciona offline",
    "q.t15#0.o1" to "Vaciar la caché",
    "q.t15#0.o2" to "Poner el modo nocturno",
    "q.t15#0.o3" to "Activar el ahorro de energía",
    "q.t15#0.e" to "Mapa offline más track offline es la única solución que sigue funcionando cuando hay «batería pero no cobertura».",

    "q.t15#1.p" to "En un mapa 1:50.000, ¿a cuántos metros equivalen 2 cm sobre el terreno?",
    "q.t15#1.o0" to "1.000 m",
    "q.t15#1.o1" to "100 m",
    "q.t15#1.o2" to "500 m",
    "q.t15#1.o3" to "2.000 m",
    "q.t15#1.e" to "1 cm son 500 m, así que 2 cm son 1.000 m. Un error en la escala arrastra todos los demás.",

    "q.t15#2.p" to "¿Qué significa que las curvas de nivel estén muy juntas?",
    "q.t15#2.o0" to "Que la pendiente es más fuerte",
    "q.t15#2.o1" to "Que la pendiente es más suave",
    "q.t15#2.o2" to "Que la altitud es mayor",
    "q.t15#2.o3" to "Que el camino es más ancho",
    "q.t15#2.e" to "Más juntas significa más desnivel en la misma distancia horizontal. Ahí se ve si un tramo va a costar.",

    "q.t15#3.p" to "¿Cuál es la forma más fiable de orientarse en el campo sin electrónica?",
    "q.t15#3.o0" to "Brújula y mapa",
    "q.t15#3.o1" to "Por el crecimiento de los árboles",
    "q.t15#3.o2" to "Por la dirección de las nubes",
    "q.t15#3.o3" to "Por intuición",
    "q.t15#3.e" to "La vegetación y las nubes solo sirven como pista adicional y fallan mucho. Brújula y mapa es la única combinación estable.",

    "q.t15#4.p" to "Sospechas que te has desviado. ¿Qué es lo primero que hay que hacer?",
    "q.t15#4.o0" to "Parar y comprobar la posición con tres referencias claras del terreno",
    "q.t15#4.o1" to "Seguir caminando y buscar el camino",
    "q.t15#4.o2" to "Aumentar el ritmo",
    "q.t15#4.o3" to "Llamar a un amigo",
    "q.t15#4.e" to "Parar y mirar atrás es la única forma de pasar de «creo que vamos mal» a «vamos mal». Seguir caminando solo agranda el error.",

    "q.t15#5.p" to "¿Qué hay que preparar antes en un paquete de navegación sin conexión?",
    "q.t15#5.o0" to "Mapa sin conexión",
    "q.t15#5.o1" to "Track de la ruta (GPX)",
    "q.t15#5.o2" to "Energía de reserva",
    "q.t15#5.o3" to "Aplicaciones de redes sociales",
    "q.t15#5.e" to "Los tres primeros aseguran que funcione «sin cobertura». Las redes sociales no ayudan sin red en la montaña.",

    "q.t15#6.p" to "Ordena una comprobación de posición.",
    "q.t15#6.o0" to "Abrir el mapa sin conexión y localizar la posición actual",
    "q.t15#6.o1" to "Contrastar con el terreno: qué ladera y qué forma tienen las curvas de nivel",
    "q.t15#6.o2" to "Identificar la siguiente referencia clara del terreno",
    "q.t15#6.o3" to "Confirmar la dirección de marcha y la distancia restante",
    "q.t15#6.e" to "Situarse no es «mirar el punto azul», sino «que el punto azul encaje con el terreno». El segundo paso es el decisivo.",

    "q.t15#7.p" to "Alguien dice «sigamos a la gente, así no nos equivocamos». ¿Cuál es la mejor respuesta?",
    "q.t15#7.o0" to "Esa gente puede ir a otro destino; primero comprobar la ruta y luego seguir",
    "q.t15#7.o1" to "Seguir es lo más cómodo",
    "q.t15#7.o2" to "Con mucha gente la seguridad es mayor",
    "q.t15#7.o3" to "Basta con preguntar",
    "q.t15#7.e" to "En los cruces, «la gente» suele ir por otra ruta. Mirar el mapa una vez cuesta diez segundos.",

    // ---------- t05 Diseñar una ruta de varios días ----------
    "q.t05#0.p" to "¿Qué se fija primero al diseñar una ruta de varios días?",
    "q.t05#0.o0" to "Los límites diarios de distancia y desnivel, y los puntos de avituallamiento y de salida",
    "q.t05#0.o1" to "Qué lugares de interés hay en el camino",
    "q.t05#0.o2" to "En qué alojamiento se duerme",
    "q.t05#0.o3" to "Qué fotos se hacen",
    "q.t05#0.e" to "Primero se traza la línea de «cuánto es posible al día» y luego se mete la ruta dentro. Al revés salen planes imposibles que obligan a caminar de noche.",

    "q.t05#1.p" to "¿Para qué sirve un día de reserva?",
    "q.t05#1.o0" to "Para que los retrasos por tiempo o lesiones no se conviertan en marchas nocturnas",
    "q.t05#1.o1" to "Para dormir más",
    "q.t05#1.o2" to "Para las fotos",
    "q.t05#1.o3" to "No tiene utilidad práctica",
    "q.t05#1.e" to "En rutas de varios días casi siempre hay retrasos. Con día de reserva se recorta un tramo; sin él, el retraso se convierte en caminar de noche o en forzar un paso peligroso.",

    "q.t05#2.p" to "¿Qué partidas de tiempo se subestiman más?",
    "q.t05#2.o0" to "Buscar el camino y corregir el rumbo",
    "q.t05#2.o1" to "Coger y filtrar agua",
    "q.t05#2.o2" to "Montar la tienda, cocinar y recoger",
    "q.t05#2.o3" to "Caminar en llano",
    "q.t05#2.e" to "La distancia del mapa solo cubre el caminar. En un día real se suman búsqueda de camino, agua, tienda, cocina y recoger mochila: normalmente 1,5–2 horas.",

    "q.t05#3.p" to "¿Qué densidad de puntos de salida se recomienda?",
    "q.t05#3.o0" to "Al menos un cruce o pueblo con bajada posible por día",
    "q.t05#3.o1" to "Uno para toda la ruta basta",
    "q.t05#3.o2" to "No hacen falta",
    "q.t05#3.o3" to "Uno cada cinco días",
    "q.t05#3.e" to "Puntos de salida demasiado espaciados equivalen a escribir «hay que llegar» en el plan. Solo sabiendo la bajada más cercana de cada tramo hay libertad real de decisión.",

    "q.t05#4.p" to "¿Por qué el día más largo no debería ser el primero?",
    "q.t05#4.o0" to "Porque el primer día el estado y el juicio son peores y aún no hay adaptación a la carga ni a la altura",
    "q.t05#4.o1" to "Porque el primer día el paisaje es peor",
    "q.t05#4.o2" to "Porque el primer día suele llover",
    "q.t05#4.o3" to "Da igual",
    "q.t05#4.e" to "El cuerpo necesita uno o dos días de adaptación: los hombros al peso, los pies a las botas, la persona al ritmo. Poner el día más duro en el medio mejora el éxito y reduce las lesiones.",

    "q.t05#5.p" to "El plan dice «llegada prevista en 6 horas». ¿Qué falta?",
    "q.t05#5.o0" to "Una hora límite de llegada a partir de la cual se aplica el plan alternativo",
    "q.t05#5.o1" to "La temperatura prevista",
    "q.t05#5.o2" to "El teléfono de los compañeros",
    "q.t05#5.o3" to "No falta nada",
    "q.t05#5.e" to "La hora prevista es una expectativa; la hora límite es una línea de decisión. Si se supera, se usa el campamento de reserva o se vuelve por donde se vino, en lugar de seguir confiando.",

    "q.t05#6.p" to "¿Por qué hay que prever días de reserva en una ruta de varios días?",
    "q.t05#6.o0" to "Porque el tiempo, las lesiones y los retrasos de transporte consumen tiempo; sin reserva se recorta el margen de seguridad",
    "q.t05#6.o1" to "Para descansar",
    "q.t05#6.o2" to "Para las fotos",
    "q.t05#6.o3" to "Para ahorrar",
    "q.t05#6.e" to "El día de reserva forma parte del plan. Quien lo considera un desperdicio acaba recortando el descanso y la seguridad.",

    "q.t05#7.p" to "¿A qué hora conviene llegar al campamento en una ruta de varios días?",
    "q.t05#7.o0" to "Con 1–2 horas de luz para montar la tienda y cocinar",
    "q.t05#7.o1" to "Justo antes de que anochezca",
    "q.t05#7.o2" to "Cuanto más tarde, más fresco",
    "q.t05#7.o3" to "Da igual",
    "q.t05#7.e" to "Montar de noche es muy ineficiente y deja pasar peligros del lugar. Fijar la hora de llegada en el plan es disciplina.",

    // ---------- t06 Elegir campamento y montar la tienda ----------
    "q.t06#0.p" to "¿A qué distancia mínima del agua debe estar el campamento?",
    "q.t06#0.o0" to "5 m",
    "q.t06#0.o1" to "60 m",
    "q.t06#0.o2" to "200 m",
    "q.t06#0.o3" to "Cuanto más cerca, mejor",
    "q.t06#0.e" to "60 m es el mínimo en la mayoría de espacios protegidos. Más cerca se contamina el agua y aparecen animales que bajan a beber de noche. Lavarse y fregar también a más de 60 m.",

    "q.t06#1.p" to "¿Qué lugares hay que evitar para acampar?",
    "q.t06#1.o0" to "Zonas de caída de piedras justo bajo una ladera empinada",
    "q.t06#1.o1" to "Cauces secos",
    "q.t06#1.o2" to "Bajo un árbol grande y aislado",
    "q.t06#1.o3" to "Sitios por donde cruza un paso de animales",
    "q.t06#1.e" to "Los cuatro son sitios donde «normalmente no pasa nada» y, cuando pasa, es grave: piedras, riada, rayo, animales. Un campamento está quieto toda la noche y ahí no hay margen.",

    "q.t06#2.p" to "¿Por qué conviene que el suelo tenga una ligera inclinación?",
    "q.t06#2.o0" to "Para que el agua drene y no se forme un charco con la lluvia",
    "q.t06#2.o1" to "Porque se duerme mejor",
    "q.t06#2.o2" to "Porque queda más ordenado",
    "q.t06#2.o3" to "Para que la tienda no se deforme",
    "q.t06#2.e" to "Un suelo totalmente plano acumula agua con lluvia fuerte. Con 2–3° de pendiente el agua corre, y con la cabeza algo más alta no se resbala hacia abajo.",

    "q.t06#3.p" to "¿Cómo se orienta la tienda para que sea más estable?",
    "q.t06#3.o0" to "Entrada a sotavento y el lado largo al viento",
    "q.t06#3.o1" to "Entrada contra el viento",
    "q.t06#3.o2" to "Como sea",
    "q.t06#3.o3" to "Orientada al sol",
    "q.t06#3.e" to "Con la entrada a sotavento no entra viento ni lluvia al entrar y salir. Con el lado largo al viento la superficie expuesta es mínima y los arcos trabajan más repartidos.",

    "q.t06#4.p" to "¿Por qué no se acampa en una cresta?",
    "q.t06#4.o0" to "Por el viento fuerte y el alto riesgo de rayo",
    "q.t06#4.o1" to "Porque hay demasiadas vistas",
    "q.t06#4.o2" to "Porque el suelo es demasiado duro",
    "q.t06#4.o3" to "Porque está demasiado cerca del agua",
    "q.t06#4.e" to "Una cresta es el punto más alto del terreno: el viento no tiene abrigo y con tormenta es el lugar más expuesto. El campamento va en la vertiente de sotavento, algo más abajo.",

    "q.t06#5.p" to "¿Qué hay que hacer al levantar el campamento?",
    "q.t06#5.o0" to "Restituir el suelo, llevarse toda la basura y comprobar que no queda nada",
    "q.t06#5.o1" to "Irse sin más",
    "q.t06#5.o2" to "Enterrar la basura",
    "q.t06#5.o3" to "Dejar leña para el siguiente",
    "q.t06#5.e" to "El sitio lo usará más gente. Revisar piquetas, envoltorios y restos de comida y levantar la hierba pisada es lo mínimo.",

    // ---------- t07 Cocina y planificación de comidas ----------
    "q.t07#0.p" to "¿Cómo se calcula a grandes rasgos el consumo de combustible?",
    "q.t07#0.o0" to "30–50 g de cartucho de gas por persona y día",
    "q.t07#0.o1" to "200 g por persona y día",
    "q.t07#0.o2" to "50 g por grupo y día",
    "q.t07#0.o3" to "No hace falta calcular",
    "q.t07#0.e" to "En rutas normales, en las que sobre todo se hierve agua, 30–50 g por persona y día es fiable. Con frío, nieve derretida y mucha cocina hay que subir, y conviene llevar un cartucho de reserva.",

    "q.t07#1.p" to "¿Qué características tienen prioridad al planificar la comida?",
    "q.t07#1.o0" to "Alta densidad energética",
    "q.t07#1.o1" to "Buena conservación, que no se estropee",
    "q.t07#1.o2" to "Poco lavado y poco fregado",
    "q.t07#1.o3" to "Que exija largos guisos",
    "q.t07#1.e" to "Cada gramo en la mochila cuesta esfuerzo y cada minuto al fuego cuesta gas. La comida liofilizada, los frutos secos, la avena y el pan —«añadir agua y listo»— es lo más rentable.",

    "q.t07#2.p" to "¿Por qué se prefieren los hidratos en altitud?",
    "q.t07#2.o0" to "Su digestión consume menos oxígeno, se transforman rápido y dan energía utilizable antes",
    "q.t07#2.o1" to "Porque son más baratos",
    "q.t07#2.o2" to "Porque pesan menos",
    "q.t07#2.o3" to "No hay diferencia",
    "q.t07#2.e" to "La grasa da más energía por gramo, pero su metabolismo exige más oxígeno. Con poco oxígeno, los hidratos son el combustible que «ahorra oxígeno».",

    "q.t07#3.p" to "¿Qué es lo más importante al usar el hornillo dentro de la tienda?",
    "q.t07#3.o0" to "Ventilar y evitar la intoxicación por monóxido de carbono",
    "q.t07#3.o1" to "Poner la llama más baja",
    "q.t07#3.o2" to "No hablar",
    "q.t07#3.o3" to "Precalentar con una vela",
    "q.t07#3.e" to "Los primeros síntomas de la intoxicación por CO —dolor de cabeza, somnolencia— apenas se distinguen del mal de altura y del cansancio, y suele ocurrir mientras se duerme. La tienda necesita ventilación obligatoriamente.",

    "q.t07#4.p" to "¿Cuál es el tratamiento más fiable para el agua cogida en el campo?",
    "q.t07#4.o0" to "Hervirla un minuto",
    "q.t07#4.o1" to "Filtrarla con un paño",
    "q.t07#4.o2" to "Dejarla decantar",
    "q.t07#4.o3" to "Añadir azúcar",
    "q.t07#4.e" to "Hervir mata bacterias, virus y parásitos. Los filtros son limitados frente a virus y las pastillas químicas necesitan tiempo de espera. En altitud el agua hierve a menos temperatura, así que hay que prolongar la ebullición.",

    "q.t07#5.p" to "¿Cuál es la mejor forma de racionar la comida?",
    "q.t07#5.o0" to "En bolsas por día, etiquetadas, para no revolver todo el saco cada vez",
    "q.t07#5.o1" to "Todo en un saco grande",
    "q.t07#5.o2" to "Meter los envases originales en la mochila",
    "q.t07#5.o3" to "Separar por sabores",
    "q.t07#5.e" to "Las raciones diarias controlan el consumo y evitan «demasiado al principio, poco al final». La etiqueta dice además qué bolsa va primero.",

    // ---------- t08 Meteorología básica para senderistas ----------
    "q.t08#0.p" to "¿Qué tres datos del tiempo importan más antes de salir?",
    "q.t08#0.o0" to "Tendencia de las próximas 24–48 horas, probabilidad de precipitación y viento con sensación térmica",
    "q.t08#0.o1" to "La temperatura máxima del día",
    "q.t08#0.o2" to "El tiempo de ayer",
    "q.t08#0.o3" to "La humedad relativa",
    "q.t08#0.e" to "«Cuántos grados hace hoy» informa poco. La tendencia decide si se cambia el plan, la probabilidad de precipitación qué se lleva y el viento la sensación térmica y si se puede estar de pie en campo abierto.",

    "q.t08#1.p" to "El cumulonimbo se abre arriba en forma de yunque. ¿Qué significa?",
    "q.t08#1.o0" to "Que la tormenta ha madurado, con precipitación intensa, granizo y rayos",
    "q.t08#1.o1" to "Que va a despejar",
    "q.t08#1.o2" to "Que son nubes altas sin consecuencias",
    "q.t08#1.o3" to "Que va a nevar",
    "q.t08#1.e" to "El yunque indica que las corrientes ascendentes han llegado a la tropopausa y la nube está en su fase más potente. Toca salir de la cresta, del campo abierto y de los árboles aislados.",

    "q.t08#2.p" to "¿Qué señales pueden preceder a una tormenta?",
    "q.t08#2.o0" to "Trueno lejano",
    "q.t08#2.o1" to "Base nubosa negra y descendente",
    "q.t08#2.o2" to "Giro brusco del viento y caída rápida de la temperatura",
    "q.t08#2.o3" to "Pelos erizados y piel con hormigueo",
    "q.t08#2.e" to "La última indica una carga ya muy alta: el rayo está cerca. Hay que perder altura de inmediato, ponerse en cuclillas con los pies juntos y no tumbarse.",

    "q.t08#3.p" to "¿Qué es lo correcto con tormenta?",
    "q.t08#3.o0" to "Salir de la cresta y de los árboles aislados, perder altura y mantener unos 50 m entre personas",
    "q.t08#3.o1" to "Ponerse bajo el árbol más alto",
    "q.t08#3.o2" to "Cruzar la cresta rápido",
    "q.t08#3.o3" to "Juntarse todos para darse calor",
    "q.t08#3.e" to "El rayo busca el punto más alto. Separarse sirve para que, si uno recibe la descarga, los demás puedan auxiliarlo; juntarse convierte un impacto en varios heridos.",

    "q.t08#4.p" to "¿Cuál es la señal más temprana y fiable de hipotermia?",
    "q.t08#4.o0" to "Temblor continuo, movimientos torpes y habla pastosa",
    "q.t08#4.o1" to "Piel enrojecida",
    "q.t08#4.o2" to "Sudor abundante",
    "q.t08#4.o3" to "Pulso lento",
    "q.t08#4.e" to "El temblor es el intento del cuerpo de generar calor. Que cese no es mejorar, puede ser una señal peor. Orden de actuación: cortar el viento, ropa seca, aislar del suelo, bebida caliente.",

    "q.t08#5.p" to "¿Por qué con la misma temperatura se siente más frío si hay viento?",
    "q.t08#5.o0" to "Porque el viento acelera la pérdida de calor en la piel y la sensación térmica queda muy por debajo de la temperatura del aire",
    "q.t08#5.o1" to "Porque el viento mete aire frío en la ropa",
    "q.t08#5.o2" to "Es puro efecto psicológico",
    "q.t08#5.o3" to "Por cambios de humedad",
    "q.t08#5.e" to "Es el efecto del windchill. 0 °C con 40 km/h se sienten como unos -10 °C. Cuánto abrigarse depende de la sensación térmica, no del número del termómetro.",
    // ---------- t09 Mal de altura y ritmo de ascenso ----------
    "q.t09#0.p" to "Por encima de 3.000 m, ¿a qué ritmo debería subir la altitud de pernocta?",
    "q.t09#0.o0" to "Como máximo 500 m al día",
    "q.t09#0.o1" to "1.000 m al día",
    "q.t09#0.o2" to "1.500 m al día",
    "q.t09#0.o3" to "Sin límite",
    "q.t09#0.e" to "«Subir alto, dormir bajo» es la estrategia habitual: durante el día se puede subir más, pero la altitud de pernocta no sube más de 500 m al día. Subir demasiado rápido es la primera causa de AMS.",

    "q.t09#1.p" to "¿Cuál es el cuadro más típico del mal agudo de montaña (AMS)?",
    "q.t09#1.o0" to "Dolor de cabeza con náuseas o falta de apetito, más mareo y debilidad",
    "q.t09#1.o1" to "Dolor articular y erupción en la piel",
    "q.t09#1.o2" to "Tos persistente con sangre",
    "q.t09#1.o3" to "Fiebre de 39 °C",
    "q.t09#1.e" to "Solo la combinación tiene valor: un dolor de cabeza aislado puede ser deshidratación o cansancio; con falta de apetito y debilidad se parece mucho más al AMS.",

    "q.t09#2.p" to "Aparecen síntomas de AMS. ¿Qué es lo correcto?",
    "q.t09#2.o0" to "Detener el ascenso y aclimatarse en el sitio o descender",
    "q.t09#2.o1" to "Tomar medicación y seguir subiendo según el plan",
    "q.t09#2.o2" to "Beber mucho, seguir caminando y aguantar",
    "q.t09#2.o3" to "Acelerar hasta el campamento y descansar allí",
    "q.t09#2.e" to "La clave es «no subir con síntomas». Si son leves y las condiciones lo permiten, ayuda un día extra en el sitio; si empeoran, hay que descender.",

    "q.t09#3.p" to "¿Qué señales exigen descender de inmediato?",
    "q.t09#3.o0" to "Falta de aire ya en reposo",
    "q.t09#3.o1" to "Marcha inestable, como de borrachera",
    "q.t09#3.o2" to "Confusión o comportamiento anómalo",
    "q.t09#3.o3" to "Dolor de cabeza leve",
    "q.t09#3.e" to "Las tres primeras apuntan a HAPE o HACE. El tratamiento tiene una sola dirección: descender, dar oxígeno y pedir ayuda médica.",

    "q.t09#4.p" to "¿Por qué se recomienda «dormir más bajo»?",
    "q.t09#4.o0" to "Porque de noche la respiración se hace más superficial y la hipoxia es máxima; dormir más bajo la reduce",
    "q.t09#4.o1" to "Porque abajo hay menos ruido",
    "q.t09#4.o2" to "Porque abajo hace más calor",
    "q.t09#4.o3" to "Porque abajo hay mejores vistas",
    "q.t09#4.e" to "Al dormir baja la ventilación y la saturación cae más que despierto. Situar el campamento unos cientos de metros por debajo del punto más alto del día es una reserva para la noche.",

    "q.t09#5.p" to "¿Las personas con mejor forma física son menos propensas al mal de altura?",
    "q.t09#5.o0" to "No necesariamente; lo decisivo son la velocidad de ascenso y la susceptibilidad individual",
    "q.t09#5.o1" to "Sí, cuanto mejor forma, más seguridad",
    "q.t09#5.o2" to "No, cuanto mejor forma, más riesgo",
    "q.t09#5.o3" to "Depende solo de la edad",
    "q.t09#5.e" to "La gente en forma suele ir más rápido y más alto, y por eso tiene problemas con más frecuencia. Separar forma física y capacidad de aclimatación es esencial en altura.",

    // ---------- t10 Abrigo y protección solar en altitud ----------
    "q.t10#0.p" to "¿En cuántas capas se organiza habitualmente el sistema de vestimenta en altitud?",
    "q.t10#0.o0" to "Capa de evacuación, capa de abrigo y capa cortavientos",
    "q.t10#0.o1" to "Ropa interior y chaqueta",
    "q.t10#0.o2" to "Camiseta de algodón, jersey, chubasquero",
    "q.t10#0.o3" to "Cuantas más, mejor",
    "q.t10#0.e" to "Las capas no están para llevar más ropa, sino para regular. Al caminar se quita la capa exterior y al parar se pone de inmediato: el enfriamiento suele ocurrir en esos diez minutos de pausa.",

    "q.t10#1.p" to "¿Cuánto aumenta aproximadamente la intensidad ultravioleta por cada 1.000 m de altitud?",
    "q.t10#1.o0" to "10–12 %",
    "q.t10#1.o1" to "2 %",
    "q.t10#1.o2" to "50 %",
    "q.t10#1.o3" to "No cambia",
    "q.t10#1.e" to "El aire es más fino y filtra menos UV. Sumado al 80 % que refleja la nieve, la exposición real de cara y nariz es casi la de «dos soles».",

    "q.t10#2.p" to "¿Qué incluye la protección solar en altitud?",
    "q.t10#2.o0" to "Gafas de sol UV400",
    "q.t10#2.o1" to "Crema SPF50+, reaplicada cada 2–3 horas",
    "q.t10#2.o2" to "Protector labial con filtro",
    "q.t10#2.o3" to "Sombrero o buff",
    "q.t10#2.e" to "Cuatro cosas para cuatro zonas: ojos, piel, labios y cara. Los labios no tienen melanina, se agrietan antes y son lo que más se olvida.",

    "q.t10#3.p" to "¿Por qué se enfrían primero las manos y los pies?",
    "q.t10#3.o0" to "Porque el cuerpo prioriza la temperatura central y cierra los vasos de las extremidades",
    "q.t10#3.o1" to "Porque tienen poca grasa",
    "q.t10#3.o2" to "Porque se mueven poco",
    "q.t10#3.o3" to "Es una sensación subjetiva",
    "q.t10#3.e" to "Es un mecanismo de supervivencia normal. Por eso hay que calentar el tronco: con el centro caliente vuelve la circulación a manos y pies. Ponerse solo guantes sirve de poco.",

    "q.t10#4.p" to "Se han mojado los guantes y los calcetines. ¿Qué se hace?",
    "q.t10#4.o0" to "Cambiarlos de inmediato: una capa mojada roba calor sin parar",
    "q.t10#4.o1" to "Dejarlos puestos, caminando se secan",
    "q.t10#4.o2" to "Escurrirlos y ya está",
    "q.t10#4.o3" to "Cambiarlos al día siguiente",
    "q.t10#4.e" to "Un textil mojado conduce el calor varias veces más rápido que uno seco. Con manos y pies agarrotados los movimientos se ralentizan y aumentan los errores al manejar el material y al caminar.",

    "q.t10#5.p" to "¿Qué es la ceguera de nieve?",
    "q.t10#5.o0" to "Una quemadura UV de la córnea que suele doler 6–12 horas después, con fotofobia y lagrimeo",
    "q.t10#5.o1" to "Cansancio ocular por la luz reflejada",
    "q.t10#5.o2" to "Congelación del globo ocular",
    "q.t10#5.o3" to "Falta de vitamina A",
    "q.t10#5.e" to "Aparece con retraso: de día nada y por la noche dolor. La prevención depende casi por completo de las gafas, también con nubes y con nieve levantada.",

    // ---------- t11 Comer y dormir en altitud ----------
    "q.t11#0.p" to "¿Qué hacer cuando en altitud no apetece comer?",
    "q.t11#0.o0" to "Comer activamente en raciones pequeñas y frecuentes, sobre todo hidratos",
    "q.t11#0.o1" to "No comer y esperar a tener apetito",
    "q.t11#0.o2" to "Beber solo agua caliente",
    "q.t11#0.o3" to "Aguantar con café",
    "q.t11#0.e" to "El déficit energético frena directamente la aclimatación. Dividir una comida grande en varios tentempiés es más fácil que forzarse a terminarla.",

    "q.t11#1.p" to "¿Cuál es el indicador más sencillo de que se bebe suficiente?",
    "q.t11#1.o0" to "Que la orina siga siendo amarillo claro",
    "q.t11#1.o1" to "Beber 3 litros al día",
    "q.t11#1.o2" to "No tener sed",
    "q.t11#1.o3" to "Mantener el peso",
    "q.t11#1.e" to "El color de la orina es el indicador de hidratación más directo. Amarillo oscuro significa poco; totalmente transparente puede ser demasiado, y entonces conviene añadir electrolitos.",

    "q.t11#2.p" to "¿Cuál es la causa más frecuente de dormir mal en altitud?",
    "q.t11#2.o0" to "La respiración periódica por falta de oxígeno, que saca una y otra vez del sueño ligero",
    "q.t11#2.o1" to "La tienda es incómoda",
    "q.t11#2.o2" to "Hay demasiado silencio",
    "q.t11#2.o3" to "Se ha caminado poco durante el día",
    "q.t11#2.e" to "Es fisiológico y no hay que angustiarse por «no dormir ocho horas». Lo que sí alarma es el insomnio con dolor de cabeza y náuseas: puede ser AMS.",

    "q.t11#3.p" to "¿Qué ayuda a dormir mejor en altitud?",
    "q.t11#3.o0" to "No cenar demasiado",
    "q.t11#3.o1" to "No beber alcohol",
    "q.t11#3.o2" to "Beber lo justo antes de dormir",
    "q.t11#3.o3" to "Usar acetazolamida bajo indicación médica",
    "q.t11#3.e" to "Las tres primeras están en la mano de cada uno; la última exige valoración médica. La medicación es una decisión clínica y no debe recomendarse entre compañeros.",

    "q.t11#4.p" to "¿Por qué es más peligroso el alcohol en altitud que en el llano?",
    "q.t11#4.o0" to "Porque deprime la respiración, agrava la hipoxia y enmascara los síntomas del AMS",
    "q.t11#4.o1" to "Porque deshidrata",
    "q.t11#4.o2" to "Porque impide dormirse",
    "q.t11#4.o3" to "Porque tiene demasiadas calorías",
    "q.t11#4.e" to "En altura el impulso respiratorio ya está debilitado y el alcohol lo frena todavía más. Además, el cuadro de una persona ebria se parece mucho al HACE incipiente.",

    "q.t11#5.p" to "¿Se puede tomar cafeína en altitud?",
    "q.t11#5.o0" to "Con moderación sí, pero no sustituye al descanso ni a la hidratación",
    "q.t11#5.o1" to "En absoluto",
    "q.t11#5.o2" to "Cuanta más, mejor",
    "q.t11#5.o3" to "Solo por la mañana",
    "q.t11#5.e" to "Un café no provoca mal de altura ni cura el cansancio. Ayuda algo con el dolor de cabeza, pero usarlo para aguantar solo retrasa el problema.",

    // ---------- t12 Grupo y preparación mental ----------
    "q.t12#0.p" to "¿Cuál es la preparación mental más importante antes de la salida?",
    "q.t12#0.o0" to "Aceptar que puede que no se llegue y tratar la retirada como parte del plan",
    "q.t12#0.o1" to "Decidir no rendirse nunca",
    "q.t12#0.o2" to "Escribirse el objetivo en la mano",
    "q.t12#0.o3" to "No contar la ruta a la familia",
    "q.t12#0.e" to "Con la retirada en el plan uno para cuando hay que parar. Si el objetivo es «llegar sí o sí», los avisos se pasan por alto para conseguirlo.",

    "q.t12#1.p" to "Te das cuenta de que no sigues el ritmo del grupo. ¿Qué es lo mejor?",
    "q.t12#1.o0" to "Decirlo abiertamente y pedir que el grupo vaya al ritmo del más lento",
    "q.t12#1.o1" to "Apretar los dientes para no frenar a nadie",
    "q.t12#1.o2" to "Ir quedándote atrás sin decir nada",
    "q.t12#1.o3" to "Volver solo sin avisar",
    "q.t12#1.e" to "Apretar lleva en pocas horas a la sobrecarga, y después llegan los errores y las lesiones. Ir al ritmo del más lento es eficacia y seguridad.",

    "q.t12#2.p" to "¿Qué ayuda frente a la exposición y el miedo a las alturas?",
    "q.t12#2.o0" to "Mirar los pies, tramo a tramo, sin fijar la vista en la distancia",
    "q.t12#2.o1" to "Respirar despacio y centrar la atención en el movimiento",
    "q.t12#2.o2" to "Mantener tres puntos de contacto y hacer gestos pequeños",
    "q.t12#2.o3" to "Pasar rápido con los ojos cerrados",
    "q.t12#2.e" to "El miedo hace la respiración superficial y el movimiento rígido, y la rigidez es la fuente de los fallos. Volver la atención al siguiente apoyo es lo más eficaz.",

    "q.t12#3.p" to "¿Qué problema tiene pensar «hemos llegado muy lejos, no puede ser en balde»?",
    "q.t12#3.o0" to "Convierte el tiempo ya invertido en motivo para seguir arriesgando",
    "q.t12#3.o1" to "No es lo bastante positivo",
    "q.t12#3.o2" to "Hace que uno vaya demasiado despacio",
    "q.t12#3.o3" to "No tiene ningún problema",
    "q.t12#3.e" to "El tiempo invertido no vuelve por seguir caminando, pero seguir puede añadir costes nuevos e irreversibles. Se juzga hacia delante, no hacia atrás.",

    "q.t12#4.p" to "¿Qué debe acordar el grupo antes de salir?",
    "q.t12#4.o0" to "Quién puede decir «alto», dónde se reencuentra el grupo si se separa y a partir de cuándo sin noticias se activa el plan de emergencia",
    "q.t12#4.o1" to "Quién hace las fotos",
    "q.t12#4.o2" to "Quién camina más rápido",
    "q.t12#4.o3" to "Quién lleva más peso",
    "q.t12#4.e" to "«Alto» pasa a ser una competencia concedida de antemano y no una prueba de valor personal, y así uno se atreve a hablar en el momento justo. Lo mismo vale para el punto de reunión y el plan de emergencia.",

    "q.t12#5.p" to "Alguien se vuelve de repente taciturno, habla poco y se mueve más despacio. ¿Qué hay que considerar primero?",
    "q.t12#5.o0" to "Falta de energía o de líquidos, pero también signos tempranos de mal de altura o hipotermia",
    "q.t12#5.o1" to "Solo mal humor",
    "q.t12#5.o2" to "Un rasgo de carácter",
    "q.t12#5.o3" to "Necesita estar un rato a solas",
    "q.t12#5.e" to "En el campo, un cambio de ánimo suele ser la primera cara de un problema físico. Primero comida, agua, más abrigo y una revisión del estado; después hablamos del ánimo.",

    // ---------- t13 Planificación de travesías largas y avituallamiento ----------
    "q.t13#0.p" to "¿Qué densidad se recomienda para los puntos de avituallamiento en una travesía larga?",
    "q.t13#0.o0" to "Uno cada 3–5 días",
    "q.t13#0.o1" to "Uno para toda la travesía",
    "q.t13#0.o2" to "Uno al día",
    "q.t13#0.o3" to "No hace falta avituallamiento",
    "q.t13#0.e" to "Los puntos de avituallamiento dividen la travesía en tramos que se pueden evaluar y abandonar por separado. Si están demasiado lejos, un retraso por tiempo arrastra toda la ruta.",

    "q.t13#1.p" to "¿Cuánto pesa aproximadamente la comida deshidratada por día?",
    "q.t13#1.o0" to "600–800 g",
    "q.t13#1.o1" to "200 g",
    "q.t13#1.o2" to "1,5 kg",
    "q.t13#1.o3" to "3 kg",
    "q.t13#1.e" to "600–800 g de comida principal deshidratada aportan unas 2.500–3.000 kcal. Con frutos secos y sobres de aceite como refuerzo energético, el peso total sube algo.",

    "q.t13#2.p" to "¿Qué normas hay que aclarar antes de una travesía larga?",
    "q.t13#2.o0" to "El permiso del parque o espacio protegido",
    "q.t13#2.o1" to "Si se permite el fuego",
    "q.t13#2.o2" to "Si hay que sacar toda la basura",
    "q.t13#2.o3" to "Si se pueden volar drones",
    "q.t13#2.e" to "No son detalles: sin permiso te hacen volver, el fuego no autorizado provoca incendios con facilidad en época seca y en muchos espacios protegidos el vuelo de drones está totalmente prohibido.",

    "q.t13#3.p" to "¿Por qué conviene llevar algo de efectivo?",
    "q.t13#3.o0" to "Porque en los pueblos y los transportes de montaña a menudo solo se acepta efectivo y puede no haber cobertura para pagar",
    "q.t13#3.o1" to "Porque parece profesional",
    "q.t13#3.o2" to "Para calzar una mesa",
    "q.t13#3.o3" to "Para pesar mejor",
    "q.t13#3.e" to "Cuanto más remoto el lugar, más depende todo del efectivo. Los billetes pequeños son lo más útil; el dinero de emergencia va aparte, sin mezclarlo con el gasto diario.",

    "q.t13#4.p" to "¿Cómo se prepara la comunicación de emergencia en una travesía larga?",
    "q.t13#4.o0" to "Un dispositivo satelital o una baliza, más un mapa en papel y el plan de ruta en manos de un contacto",
    "q.t13#4.o1" to "Solo el móvil",
    "q.t13#4.o2" to "Solo un silbato",
    "q.t13#4.o3" to "Nada de eso",
    "q.t13#4.e" to "En muchas travesías largas no hay cobertura en todo el recorrido. El dispositivo envía mensajes; el mapa y el plan dicen a quien se queda en casa adónde vas y cuándo hay que dar la alarma.",

    "q.t13#5.p" to "¿Qué significa concretamente reservar un 20 %?",
    "q.t13#5.o0" to "Llevar comida, combustible, tiempo y efectivo un quinto por encima de lo teórico",
    "q.t13#5.o1" to "Llevar solo más agua",
    "q.t13#5.o2" to "Reservar solo tiempo",
    "q.t13#5.o3" to "No hace falta",
    "q.t13#5.e" to "La reserva es espacio para lo imprevisto: un día de retraso por tiempo, dos cocciones extra, un transporte no previsto. Nada de eso debe poner la salida en apuros de inmediato.",

    // ---------- t14 Urgencias frecuentes y pedir ayuda ----------
    "q.t14#0.p" to "¿Cuál es la regla básica de primeros auxilios ante un esguince de tobillo?",
    "q.t14#0.o0" to "Reposo, frío, compresión y elevación (RICE)",
    "q.t14#0.o1" to "Calor y masaje de inmediato",
    "q.t14#0.o2" to "Seguir caminando hasta que se suelte",
    "q.t14#0.o3" to "Extender el hematoma con fuerza",
    "q.t14#0.e" to "El calor y el masaje en la fase aguda aumentan la hemorragia y la inflamación. Las primeras 48 horas: frío, compresión y elevación; después, carga progresiva según la evolución.",

    "q.t14#1.p" to "¿Cuál es el orden correcto en una hipotermia?",
    "q.t14#1.o0" to "Cortar el viento, ropa seca, aislar del suelo, bebida caliente solo si está consciente y recalentar despacio",
    "q.t14#1.o1" to "Dar agua caliente y luego cambiar la ropa",
    "q.t14#1.o2" to "Frotar manos y pies para activar la circulación",
    "q.t14#1.o3" to "Hacer caminar rápido para generar calor",
    "q.t14#1.e" to "Primero se detiene la pérdida de calor; después se habla de recalentar. Frotar las extremidades y forzar la marcha pueden devolver sangre fría al centro y empeorar la situación.",

    "q.t14#2.p" to "Ante la sospecha de golpe de calor, ¿qué se hace primero?",
    "q.t14#2.o0" to "Llevar a la sombra sin demora, abrir la ropa y empezar a enfriar físicamente",
    "q.t14#2.o1" to "Dar mucha agua",
    "q.t14#2.o2" to "Dejar que siga caminando, sudar ayuda",
    "q.t14#2.o3" to "Abrigar para que no se enfríe",
    "q.t14#2.e" to "En el golpe de calor falla la disipación; primero se enfría y después se hidrata. Con la conciencia alterada no se da de beber, para evitar la aspiración.",

    "q.t14#3.p" to "¿Qué datos debe incluir un aviso de emergencia?",
    "q.t14#3.o0" to "Posición exacta o coordenadas",
    "q.t14#3.o1" to "Número de personas y lesiones",
    "q.t14#3.o2" to "Material y víveres disponibles",
    "q.t14#3.o3" to "Forma de contacto y batería restante",
    "q.t14#3.e" to "El rescate necesita saber primero dónde, cuántos, con qué gravedad y cuánto tiempo pueden aguantar. Una información incompleta cuesta a menudo horas de preguntas.",

    "q.t14#4.p" to "¿Cómo se prepara un plan para el caso de no tener noticias?",
    "q.t14#4.o0" to "Fijar horas de control: a partir de cuándo llama quién a quién y cuándo se da la alarma",
    "q.t14#4.o1" to "Ya se verá",
    "q.t14#4.o2" to "Decir a la familia solo por encima adónde se va",
    "q.t14#4.o3" to "Ese plan no hace falta",
    "q.t14#4.e" to "El plan debe incluir hora y acción: a partir de qué hora se llama, tras cuántas horas más se contacta con el rescate local. Un vago «avisadme si pasa algo» no es un plan.",

    "q.t14#5.p" to "¿Cuándo hay que pedir ayuda en vez de seguir tratando por cuenta propia?",
    "q.t14#5.o0" to "Cuando la persona no puede caminar, la conciencia está alterada o el estado empeora de forma continua",
    "q.t14#5.o1" to "Con un poco de cansancio",
    "q.t14#5.o2" to "Con los pies rozados",
    "q.t14#5.o3" to "Con dos horas de retraso sobre el plan",
    "q.t14#5.e" to "El umbral debe estar claro de antemano: puede caminar, está consciente y mejora, se baja solo; no puede caminar, está confuso o empeora, se pide ayuda pronto.",

    // ---------- t16 Vida en el campamento e higiene en el campo ----------
    "q.t16#0.p" to "¿Cómo se dividen básicamente las tres zonas de un campamento?",
    "q.t16#0.o0" to "Dormir, cocinar y letrina, separadas",
    "q.t16#0.o1" to "Hombres, mujeres y común",
    "q.t16#0.o2" to "Tienda, vehículo y fuego",
    "q.t16#0.o3" to "No hace falta dividir",
    "q.t16#0.e" to "La división resuelve tres cosas: riesgo de fuego abierto, olores que atraen animales y contaminación cruzada higiénica.",

    "q.t16#1.p" to "¿Qué profundidad y qué distancia al agua son razonables para un hoyo de letrina?",
    "q.t16#1.o0" to "15–20 cm de profundidad y al menos 60 m del agua",
    "q.t16#1.o1" to "5 cm de profundidad y 5 m del agua",
    "q.t16#1.o2" to "Cuanto más profundo y más lejos, mejor",
    "q.t16#1.o3" to "No hace falta cavar",
    "q.t16#1.e" to "Demasiado somero no se descompone y demasiado cerca contamina el agua. 60 m es la distancia habitual.",

    "q.t16#2.p" to "¿Cómo se trata correctamente el papel higiénico?",
    "q.t16#2.o0" to "En una bolsa y se lleva",
    "q.t16#2.o1" to "Se quema",
    "q.t16#2.o2" to "Se entierra en el hoyo",
    "q.t16#2.o3" to "Se tira a la hierba",
    "q.t16#2.e" to "Quemar papel conlleva riesgo de incendio en época seca, y enterrado reaparece con el deshielo o cuando un animal escarba. Llevárselo es lo más limpio.",

    "q.t16#3.p" to "¿Cómo se elimina correctamente el agua de fregar?",
    "q.t16#3.o0" to "Filtrar los restos y llevarlos, y verter el agua repartida en una zona amplia",
    "q.t16#3.o1" to "Verterla directamente al arroyo",
    "q.t16#3.o2" to "Verterla junto a la tienda",
    "q.t16#3.o3" to "Verterla en el hoyo de letrina",
    "q.t16#3.e" to "Los restos contaminan y atraen animales, así que se filtran y se llevan; el agua restante se vierte repartida, sin concentrarla en un punto.",

    "q.t16#4.p" to "¿Cuáles son las tres cosas clave del cuidado de los pies al caminar?",
    "q.t16#4.o0" to "Lavarlos a diario, cambiar a calcetines secos y airear las botas",
    "q.t16#4.o1" to "Caminar mucho",
    "q.t16#4.o2" to "Llevar calcetines gruesos",
    "q.t16#4.o3" to "Aplicar crema",
    "q.t16#4.e" to "Las ampollas y las maceraciones vienen de la humedad y el roce. Secar ayuda más que cualquier crema.",

    "q.t16#5.p" to "¿Qué hay que evitar en la higiene del campamento?",
    "q.t16#5.o0" to "Comer dentro de la tienda",
    "q.t16#5.o1" to "Dejar restos de comida en el campamento",
    "q.t16#5.o2" to "Fregar en el agua",
    "q.t16#5.o3" to "Dejar las botas en la entrada de la tienda por la noche",
    "q.t16#5.e" to "Las tres primeras traen animales y contaminación a la zona de dormir. Las botas en el zaguán es habitual, pero hay que sacudirlas antes.",

    "q.t16#6.p" to "Ordena el desmontaje del campamento por la mañana.",
    "q.t16#6.o0" to "Guardar primero el saco en su bolsa",
    "q.t16#6.o1" to "Recoger los objetos sueltos y la basura de dentro de la tienda",
    "q.t16#6.o2" to "Desmontar la tienda y sacudir el rocío y la escarcha",
    "q.t16#6.o3" to "Revisar el sitio y confirmar que no queda nada",
    "q.t16#6.e" to "El último paso es el que más se olvida: los objetos dejados atrás son el fallo más habitual en «no dejar rastro».",

    "q.t16#7.p" to "Aparecen rastros de animales cerca del campamento (excrementos, escarbaduras). ¿Qué se hace?",
    "q.t16#7.o0" to "Colgar la comida en alto o guardarla bien cerrada y lejos de la zona de dormir",
    "q.t16#7.o1" to "Seguir cocinando donde estaba",
    "q.t16#7.o2" to "Darle algo de comida",
    "q.t16#7.o3" to "Meter la comida en la tienda",
    "q.t16#7.e" to "Los animales se sienten atraídos por el olor. Meter la comida en la tienda es lo más peligroso: atrae al animal justo donde se duerme.",
    // ---------- t17 Deshidratación, golpe de calor y lesiones frecuentes ----------
    "q.t17#0.p" to "¿Cuál es el indicador más práctico de hidratación al caminar?",
    "q.t17#0.o0" to "Que la orina siga siendo amarillo claro",
    "q.t17#0.o1" to "La sensación de sed",
    "q.t17#0.o2" to "La cantidad de sudor",
    "q.t17#0.o3" to "El peso corporal",
    "q.t17#0.e" to "La sed aparece cuando ya falta agua. El color de la orina es el autocontrol diario más barato.",

    "q.t17#1.p" to "¿Cuál es el criterio central del golpe de calor?",
    "q.t17#1.o0" to "Temperatura central por encima de 40 °C con alteración de la conciencia",
    "q.t17#1.o1" to "Sudoración abundante",
    "q.t17#1.o2" to "Piel enrojecida",
    "q.t17#1.o3" to "Pulso rápido",
    "q.t17#1.e" to "La alteración de la conciencia es la señal clave. Sin termómetro en el lugar, se decide por el estado de conciencia y se enfría de inmediato.",

    "q.t17#2.p" to "¿Cuál es el orden correcto ante un agotamiento por calor?",
    "q.t17#2.o0" to "Sombra, abrir la ropa, enfriar y aportar electrolitos",
    "q.t17#2.o1" to "Primero líquidos y después enfriar",
    "q.t17#2.o2" to "Masajear primero las extremidades",
    "q.t17#2.o3" to "Dar agua primero",
    "q.t17#2.e" to "Enfriar tiene prioridad. El líquido tarda en hacer efecto y el daño orgánico por calor es inmediato.",

    "q.t17#3.p" to "¿Qué es lo correcto en las primeras 48 horas tras un esguince de tobillo?",
    "q.t17#3.o0" to "Frío, compresión y elevación; evitar calor y masaje enérgico",
    "q.t17#3.o1" to "Calor y masaje",
    "q.t17#3.o2" to "Seguir caminando",
    "q.t17#3.o3" to "Extender el hematoma",
    "q.t17#3.e" to "El calor y el roce en la fase aguda aumentan la hemorragia y la hinchazón. En RICE no falta ninguno de los cuatro pasos.",

    "q.t17#4.p" to "¿Qué se hace si una persona sobrecalentada tiene la conciencia alterada?",
    "q.t17#4.o0" to "No darle de beber; enfriar con paños húmedos y pedir ayuda sin demora",
    "q.t17#4.o1" to "Darle agua",
    "q.t17#4.o2" to "Darle pastillas de sal",
    "q.t17#4.o3" to "Dejar que beba por su cuenta",
    "q.t17#4.e" to "Con el reflejo de deglución poco fiable, dar de beber provoca aspiración. En ese momento solo funcionan el enfriamiento y el rescate profesional.",

    "q.t17#5.p" to "Una ampolla impide caminar. ¿Cuál es el manejo correcto?",
    "q.t17#5.o0" to "Desinfectar, drenar desde el borde, conservar la piel y cubrir",
    "q.t17#5.o1" to "Arrancar toda la piel",
    "q.t17#5.o2" to "Pinchar en el centro",
    "q.t17#5.o3" to "Ignorarla",
    "q.t17#5.e" to "La piel conservada es el mejor apósito. Pinchar en el centro desgarra con facilidad.",

    "q.t17#6.p" to "¿Qué aumenta el riesgo de sufrir un problema por calor al caminar?",
    "q.t17#6.o0" to "Humedad alta sin viento",
    "q.t17#6.o1" to "Subir en pleno mediodía",
    "q.t17#6.o2" to "Beber solo agua sin electrolitos",
    "q.t17#6.o3" to "Ropa clara y transpirable",
    "q.t17#6.e" to "Los tres primeros reducen la disipación o desequilibran los electrolitos. La ropa clara y transpirable es justamente una medida de refrigeración.",

    "q.t17#7.p" to "¿Qué no puede faltar en un botiquín de senderismo?",
    "q.t17#7.o0" to "Apósitos para ampollas y gasas",
    "q.t17#7.o1" to "Analgésicos y antitérmicos",
    "q.t17#7.o2" to "Venda elástica",
    "q.t17#7.o3" to "Antibióticos",
    "q.t17#7.e" to "Los tres primeros cubren los problemas más frecuentes: pies, dolor y esguinces. Los antibióticos requieren valoración médica.",

    "q.t17#8.p" to "Ordena el tratamiento de un agotamiento por calor.",
    "q.t17#8.o0" to "Parar la actividad y llevar a la sombra",
    "q.t17#8.o1" to "Abrir la ropa y empezar a enfriar",
    "q.t17#8.o2" to "Aportar líquido con electrolitos",
    "q.t17#8.o3" to "Vigilar conciencia y estado, y pedir ayuda si hace falta",
    "q.t17#8.e" to "El núcleo del orden es «primero cortar la exposición al calor». Seguir caminando empuja el agotamiento hacia el golpe de calor.",

    "q.t17#9.p" to "Alguien presenta de repente dolor de cabeza, náuseas y piel fría y sudorosa subiendo al mediodía. ¿Qué se hace?",
    "q.t17#9.o0" to "Parar de inmediato, enfriar, dar electrolitos y observar",
    "q.t17#9.o1" to "Seguir hasta el campamento",
    "q.t17#9.o2" to "Dar un analgésico y continuar",
    "q.t17#9.o3" to "Abrigarle",
    "q.t17#9.e" to "Es el cuadro típico del agotamiento por calor. Seguir empeora rápido, y un golpe de calor puede matar en pocas decenas de minutos.",

    // ---------- t18 Leer un río y elegir el paso ----------
    "q.t18#0.p" to "¿Qué combinación de magnitudes decide sobre todo si un vado es posible?",
    "q.t18#0.o0" to "Profundidad por velocidad de la corriente",
    "q.t18#0.o1" to "La profundidad",
    "q.t18#0.o2" to "La anchura del río",
    "q.t18#0.o3" to "La temperatura del agua",
    "q.t18#0.e" to "A la misma profundidad, el doble de velocidad significa el doble de fuerza. Medir solo la profundidad es el error más común al vadear.",

    "q.t18#1.p" to "¿Dónde está el límite técnico de seguridad para vadear?",
    "q.t18#1.o0" to "Profundidad por velocidad superior a 1,0 metros cuadrados por segundo se considera no vadeable",
    "q.t18#1.o1" to "Profundidad superior a 0,5 m",
    "q.t18#1.o2" to "Velocidad superior a 3 m/s",
    "q.t18#1.o3" to "Anchura superior a 20 m",
    "q.t18#1.e" to "El 1,0 vale para adultos sanos, tramos cortos y sin carga pesada. Un grupo puede fijar 0,8 como línea interna, pero eso es práctica conservadora, no norma.",

    "q.t18#2.p" to "¿Cómo se estima la velocidad con un palo?",
    "q.t18#2.o0" to "Si hay que trotar por la orilla para seguirlo, ya supera la velocidad de paso",
    "q.t18#2.o1" to "Si el palo se hunde",
    "q.t18#2.o2" to "Si el palo gira",
    "q.t18#2.o3" to "Si hay espuma en la superficie",
    "q.t18#2.e" to "Caminar por la orilla siguiéndolo es la medición más directa. Si hay que trotar, la corriente ya es excesiva.",

    "q.t18#3.p" to "¿A partir de qué profundidad hay que buscar otro punto?",
    "q.t18#3.o0" to "Por encima del muslo de la persona más baja del grupo",
    "q.t18#3.o1" to "A la altura de la cintura del jefe de cordada",
    "q.t18#3.o2" to "A la altura de la rodilla",
    "q.t18#3.o3" to "A la altura del pecho",
    "q.t18#3.e" to "Se calcula con la persona más baja, no con la más fuerte. El grupo está limitado por el más débil: es la regla de hierro de los vadeos.",

    "q.t18#4.p" to "¿Qué es el «run-out»?",
    "q.t18#4.o0" to "La zona aguas abajo a la que la corriente arrastraría a una persona caída",
    "q.t18#4.o1" to "La ladera empinada de la orilla",
    "q.t18#4.o2" to "La pendiente del cauce",
    "q.t18#4.o3" to "La cuenca aguas arriba",
    "q.t18#4.e" to "Si en el run-out hay cascadas, troncos o taludes, ese punto no sirve, aunque el agua frente a ti parezca somera.",

    "q.t18#5.p" to "¿Qué se busca primero al elegir un vado?",
    "q.t18#5.o0" to "Tramos anchos y poco profundos",
    "q.t18#5.o1" to "Tramos estrechos y profundos",
    "q.t18#5.o2" to "El exterior de una curva",
    "q.t18#5.o3" to "Cerca de troncos acumulados",
    "q.t18#5.e" to "Cuanto más ancho suele ser más somero y lento; en el exterior de la curva hay profundidad y velocidad, y los troncos son una trampa mortal.",

    "q.t18#6.p" to "¿Cuánto tiene que subir el nivel del agua para volver peligroso un punto antes seguro?",
    "q.t18#6.o0" to "15 cm",
    "q.t18#6.o1" to "1 m",
    "q.t18#6.o2" to "50 cm",
    "q.t18#6.o3" to "Con tan poco no cambia nada",
    "q.t18#6.e" to "15 cm ya cambian claramente la profundidad y la velocidad, sobre todo en zonas de agua de deshielo glaciar.",

    "q.t18#7.p" to "¿En qué casos hay que descartar el punto de vado de inmediato?",
    "q.t18#7.o0" to "No se ve el fondo y el agua está turbia",
    "q.t18#7.o1" to "Aguas abajo hay troncos o taludes",
    "q.t18#7.o2" to "Ha llovido fuerte aguas arriba",
    "q.t18#7.o3" to "El cauce es una gravera plana",
    "q.t18#7.e" to "Los tres primeros significan «no evaluable» o «un error no es asumible». Una gravera es justamente el buen cauce.",

    "q.t18#8.p" to "¿Qué hay que resolver en el material antes de cruzar?",
    "q.t18#8.o0" to "Abrir el esternón",
    "q.t18#8.o1" to "Aflojar los tirantes",
    "q.t18#8.o2" to "Apretar las fijaciones exteriores para que no recoja agua",
    "q.t18#8.o3" to "Guardar móvil y medicamentos en una bolsa estanca",
    "q.t18#8.e" to "Los dos primeros permiten soltar la mochila y los otros dos protegen el material crítico. Las cuatro cosas se resuelven antes de entrar al agua.",

    "q.t18#9.p" to "Ordena la secuencia de decisión de un vadeo.",
    "q.t18#9.o0" to "Preguntar primero: ¿tengo de verdad que cruzar? (rodeo, puente, esperar a que baje)",
    "q.t18#9.o1" to "Elegir el punto y medir profundidad y velocidad",
    "q.t18#9.o2" to "Acordar un procedimiento único para mochila y ropa en todo el grupo",
    "q.t18#9.o3" to "Cruzar en formación o de uno en uno",
    "q.t18#9.e" to "La primera pregunta elimina la mayor parte del riesgo. Mucha gente la salta y empieza directamente a pensar cómo pasar.",

    "q.t18#10.p" to "El río lleva bastante más agua por la tarde que por la mañana. ¿A qué se debe principalmente?",
    "q.t18#10.o0" to "Al ciclo diario del agua de deshielo glaciar, con el máximo por la tarde",
    "q.t18#10.o1" to "A que llueve más por la tarde",
    "q.t18#10.o2" to "Al desembalse de un pantano aguas arriba",
    "q.t18#10.o3" to "A la evaporación",
    "q.t18#10.e" to "Los ríos de deshielo tienen un ciclo muy regular: mínimo por la mañana y máximo por la tarde. Los cruces se programan preferentemente por la mañana.",

    // ---------- t19 Formaciones y manejo de la caída ----------
    "q.t19#0.p" to "¿Cómo se forma correctamente el triángulo?",
    "q.t19#0.o0" to "Tres personas mirándose, agarradas a hombro o mochila, con una sola persona y una sola pierna en movimiento cada vez",
    "q.t19#0.o1" to "Tres personas en línea, de la mano, avanzando a la vez",
    "q.t19#0.o2" to "Tres personas una detrás de otra",
    "q.t19#0.o3" to "Dos que llevan a una tercera",
    "q.t19#0.e" to "Avanzar todos a la vez hace que toda la formación pierda el apoyo. Agarrarse de los brazos cansa y se suelta con facilidad: se agarra el hombro o la mochila.",

    "q.t19#1.p" to "¿Dónde se colocan las personas más fuertes en la formación en línea?",
    "q.t19#1.o0" to "En los extremos, sobre todo aguas arriba",
    "q.t19#1.o1" to "En el centro",
    "q.t19#1.o2" to "Al final",
    "q.t19#1.o3" to "En cualquier sitio",
    "q.t19#1.e" to "El extremo de aguas arriba recibe el golpe principal de la corriente y el de aguas abajo hace de red. Los inexpertos van en el centro, con una persona fuerte en cada punta.",

    "q.t19#2.p" to "¿Cuál es el ritmo de voces en la formación?",
    "q.t19#2.o0" to "«Un paso, alto, un paso»",
    "q.t19#2.o1" to "«Uno-dos, uno-dos» seguido",
    "q.t19#2.o2" to "Sin voces",
    "q.t19#2.o3" to "Cada uno a su ritmo",
    "q.t19#2.e" to "El ritmo común sirve para que solo se mueva una persona cada vez. Avanzar todos a la vez es el error más frecuente en una formación.",

    "q.t19#3.p" to "¿Cuál es la primera regla tras una caída al agua?",
    "q.t19#3.o0" to "No ponerse de pie",
    "q.t19#3.o1" to "Levantarse de inmediato",
    "q.t19#3.o2" to "Agarrarse a la cuerda",
    "q.t19#3.o3" to "Agarrarse a un tronco",
    "q.t19#3.e" to "El pie puede quedar atrapado en una grieta o bajo un tronco y la corriente empuja el cuerpo bajo el agua («foot entrapment»), el mecanismo típico de las muertes en ríos.",

    "q.t19#4.p" to "¿Cuál es la postura correcta tras una caída?",
    "q.t19#4.o0" to "Boca arriba, pies aguas abajo y cerca de la superficie, cabeza alta",
    "q.t19#4.o1" to "Boca abajo nadando",
    "q.t19#4.o2" to "Vertical, haciendo pie",
    "q.t19#4.o3" to "Con las rodillas al pecho",
    "q.t19#4.e" to "Boca arriba y con los pies aguas abajo se pueden apartar los obstáculos con los pies en lugar de chocar, y se protege la cabeza.",

    "q.t19#5.p" to "¿Qué se hace con el cinturón de la mochila al vadear?",
    "q.t19#5.o0" to "La escuela estadounidense lo abre para poder soltarla; Nueva Zelanda (MSC) lo cierra para usarla como flotación; lo decisivo es que todo el grupo haga lo mismo",
    "q.t19#5.o1" to "Tiene que ir abierto",
    "q.t19#5.o2" to "Tiene que ir cerrado",
    "q.t19#5.o3" to "Da igual",
    "q.t19#5.e" to "Cada escuela tiene sus premisas. Lo verdaderamente peligroso es «la mitad abierta y la mitad cerrada»: así, en un rescate, nada encaja.",

    "q.t19#6.p" to "La mochila se engancha en una piedra. ¿Qué se hace?",
    "q.t19#6.o0" to "Levantar los brazos y salir de los tirantes; mejor perder la mochila",
    "q.t19#6.o1" to "Tirar con fuerza",
    "q.t19#6.o2" to "Bucear para soltarla",
    "q.t19#6.o3" to "Esperar a los compañeros",
    "q.t19#6.e" to "Con la mochila enganchada, la corriente empuja a la persona hacia abajo. Levantar los brazos y escabullirse es la liberación más rápida.",

    "q.t19#7.p" to "¿Cómo se actúa justo antes de llegar a la orilla?",
    "q.t19#7.o0" to "Abrir primero el cinturón, luego quitarse el tirante de aguas arriba y usar la mochila como flotación delante para incorporarse",
    "q.t19#7.o1" to "Levantarse primero y luego soltar la mochila",
    "q.t19#7.o2" to "Lanzar la mochila a la orilla",
    "q.t19#7.o3" to "Trepar directamente",
    "q.t19#7.e" to "La flotación de la mochila ayuda, pero en orden equivocado se pierde el apoyo. Primero el cinturón y luego el tirante de aguas arriba: es el orden estándar.",

    "q.t19#8.p" to "¿Qué incluye la preparación de un cruce en formación?",
    "q.t19#8.o0" to "Ensayar agarres y voces en tierra",
    "q.t19#8.o1" to "Decidir quién va aguas arriba",
    "q.t19#8.o2" to "Unificar el manejo de cinturón y esternón",
    "q.t19#8.o3" to "Que cada uno decida su forma de cruzar",
    "q.t19#8.e" to "Una formación vive de la coordinación, y la coordinación solo existe si se ha construido antes. Cada uno por su cuenta deshace la formación en el agua.",

    "q.t19#9.p" to "¿Qué es correcto sobre el aseguramiento con cuerda en un vadeo?",
    "q.t19#9.o0" to "La mayoría de los grupos no lo domina y el riesgo puede superar el beneficio",
    "q.t19#9.o1" to "La cuerda se fija en la orilla y también al cuerpo",
    "q.t19#9.o2" to "Se cruza por el lado de aguas abajo de la cuerda",
    "q.t19#9.o3" to "Una cuerda transversal bien tensa sobre la corriente es lo más seguro",
    "q.t19#9.e" to "Una cuerda transversal tensa empuja a la persona bajo el agua. El aseguramiento con cuerda es una técnica propia y no se improvisa sobre el terreno.",

    "q.t19#10.p" to "Ordena un cruce en formación.",
    "q.t19#10.o0" to "Elegir el punto y comprobar el run-out",
    "q.t19#10.o1" to "Abrir el esternón en todo el grupo y acordar el manejo del cinturón",
    "q.t19#10.o2" to "Ensayar la formación y las voces en tierra",
    "q.t19#10.o3" to "Avanzar de lado con la voz común, un paso por persona",
    "q.t19#10.o4" to "En la orilla, ropa seca y algo caliente",
    "q.t19#10.e" to "El último paso es el que más se olvida: la hipotermia en agua fría es a menudo más frecuente que la caída.",

    "q.t19#11.p" to "Alguien se queda quieto de repente en el agua. ¿Qué es lo más probable?",
    "q.t19#11.o0" to "Que tenga el pie atrapado; hay que ayudarle de inmediato y mantenerle boca arriba",
    "q.t19#11.o1" to "Que esté descansando",
    "q.t19#11.o2" to "Que esté mirando el paisaje",
    "q.t19#11.o3" to "Que espere una voz",
    "q.t19#11.e" to "Quedarse inmóvil de golpe es típico del pie atrapado. En ese momento necesita sobre todo no luchar, mantener la posición boca arriba y que alguien se acerque desde aguas arriba.",

    // ---------- t20 Mantenimiento y reparación del material ----------
    "q.t20#0.p" to "¿Cuál es la avería más frecuente del material en travesías largas?",
    "q.t20#0.o0" to "Suelas que se despegan y colchonetas que pierden aire",
    "q.t20#0.o1" to "Correas de mochila que se rompen",
    "q.t20#0.o2" to "Agueros en la tienda",
    "q.t20#0.o3" to "Bastones que se parten",
    "q.t20#0.e" to "Las dos primeras llevan directamente a «no poder caminar» o «no poder dormir». La revisión previa debe empezar por ahí.",

    "q.t20#1.p" to "La suela empieza a despegarse. ¿Qué es lo más sensato en el lugar?",
    "q.t20#1.o0" to "Fijarla primero con cinta para que no siga rasgándose; en un pueblo, adhesivo específico",
    "q.t20#1.o1" to "Fundirla con fuego",
    "q.t20#1.o2" to "Atarla con un cordón",
    "q.t20#1.o3" to "Seguir caminando hasta que se caiga",
    "q.t20#1.e" to "La cinta contiene el daño, no lo repara. Si sigue rasgándose se despega la suela entera y entonces sí que no se puede caminar.",

    "q.t20#2.p" to "Se ha roto un varillaje de la tienda. ¿Cuál es la solución más práctica en el lugar?",
    "q.t20#2.o0" to "Meter un tubo de reparación sobre la rotura y seguir usándolo",
    "q.t20#2.o1" to "Envolverlo todo con cinta",
    "q.t20#2.o2" to "Tirar la tienda",
    "q.t20#2.o3" to "Sustituir todo el varillaje por una rama",
    "q.t20#2.e" to "El tubo recupera buena parte de la resistencia. La cinta aguanta una o dos noches y empeora la rotura.",

    "q.t20#3.p" to "Se ha hecho un pequeño agujero en la chaqueta de plumas. ¿Cómo se actúa?",
    "q.t20#3.o0" to "Pegar un parche y presionar, sin golpear",
    "q.t20#3.o1" to "Sacudir las plumas que salen",
    "q.t20#3.o2" to "Fundir el borde con fuego",
    "q.t20#3.o3" to "Coserlo con aguja e hilo",
    "q.t20#3.e" to "Golpear hace que sigan saliendo plumas por los agujeros de la costura. Parche y una ligera presión es la contención más eficaz.",

    "q.t20#4.p" to "¿Cuál no es una causa típica de fuga en una colchoneta hinchable?",
    "q.t20#4.o0" to "La exposición al sol",
    "q.t20#4.o1" to "Piedras puntiagudas en el suelo",
    "q.t20#4.o2" to "Una válvula no del todo cerrada",
    "q.t20#4.o3" to "Costuras fatigadas",
    "q.t20#4.e" to "El sol no pincha una cámara. Además de las tres primeras, la causa más habitual es un suelo mal despejado.",

    "q.t20#5.p" to "¿Qué conviene llevar en un kit de reparación de senderismo?",
    "q.t20#5.o0" to "Cinta de Dyneema",
    "q.t20#5.o1" to "Parches y adhesivo para la colchoneta",
    "q.t20#5.o2" to "Hebillas de recambio",
    "q.t20#5.o3" to "Un juego completo de destornilladores",
    "q.t20#5.e" to "Los tres primeros cubren los tres grupos de averías frecuentes: tejido de tienda, cámara de aire y cierres de mochila. Un juego de destornilladores es peso que no se usa.",

    "q.t20#6.p" to "¿Qué merece la pena revisar cinco minutos al llegar al campamento?",
    "q.t20#6.o0" to "Si hay arena y piedras dentro de la bota",
    "q.t20#6.o1" to "Si los calcetines están empapados",
    "q.t20#6.o2" to "Las costuras y los cierres de la mochila",
    "q.t20#6.o3" to "La longitud de los bastones",
    "q.t20#6.e" to "Los dos primeros deciden el estado de los pies y el tercero si mañana se rompe una correa de golpe. La longitud de los bastones se ajusta en cualquier momento.",

    "q.t20#7.p" to "¿Cuál es la idea correcta sobre la «caducidad» del material?",
    "q.t20#7.o0" to "Juzgar por intensidad de uso y estado, no por el año de compra",
    "q.t20#7.o1" to "Lo nuevo siempre es mejor",
    "q.t20#7.o2" to "Cambiarlo solo cuando se rompe",
    "q.t20#7.o3" to "Cuanto más viejo, más fiable",
    "q.t20#7.e" to "En la misma pieza, la vida útil varía mucho según la frecuencia de uso. Mirar el desgaste —suela, cierres, tratamientos— es más fiable que mirar la fecha.",

    // ---------- t21 Marcha nocturna y tormentas ----------
    "q.t21#0.p" to "¿Cuál es la actitud más sensata ante la marcha nocturna?",
    "q.t21#0.o0" to "Solo cuando sea necesario; y si lo es, más despacio y con una gestión de grupo más estricta",
    "q.t21#0.o1" to "De noche hace más fresco, va bien para avanzar",
    "q.t21#0.o2" to "De noche es más seguro",
    "q.t21#0.o3" to "Con un frontal basta",
    "q.t21#0.e" to "De noche la lectura del terreno y la navegación se multiplican en dificultad, y también la siniestralidad. La marcha nocturna es la opción cuando no hay otra, no una estrategia.",

    "q.t21#1.p" to "¿Cómo se compone correctamente la iluminación para una marcha nocturna?",
    "q.t21#1.o0" to "Frontal, pilas de repuesto y una segunda fuente de luz (linterna pequeña o segundo frontal)",
    "q.t21#1.o1" to "Solo la linterna del móvil",
    "q.t21#1.o2" to "Solo un frontal",
    "q.t21#1.o3" to "Una vela",
    "q.t21#1.e" to "Sin luz de noche uno queda sin capacidad de actuar. La segunda fuente es redundancia, con la misma lógica que en un sistema de cuerda.",

    "q.t21#2.p" to "¿Cómo se gestiona la distancia en el grupo durante una marcha nocturna?",
    "q.t21#2.o0" to "Acortarla, con la cabeza confirmando con frecuencia que la cola sigue y alguien esperando en los cruces",
    "q.t21#2.o1" to "Aumentarla y que cada uno vaya a su aire",
    "q.t21#2.o2" to "Separarse según la forma física",
    "q.t21#2.o3" to "Que la cola busque el camino",
    "q.t21#2.e" to "De noche el campo visual es estrecho y a quien se queda atrás se le ve muy tarde. Dejar a alguien en los cruces es el seguro más barato.",

    "q.t21#3.p" to "¿Cuál no es una señal temprana de tormenta cercana?",
    "q.t21#3.o0" to "La temperatura sube poco a poco",
    "q.t21#3.o1" to "El cumulonimbo crece rápido",
    "q.t21#3.o2" to "Trueno lejano y sordo",
    "q.t21#3.o3" to "Pelos erizados y piel con hormigueo",
    "q.t21#3.e" to "Con la tormenta acercándose la temperatura suele bajar. Los pelos erizados indican carga alta: hay que abandonar el punto alto de inmediato.",

    "q.t21#4.p" to "¿Qué es lo más importante con tormenta en la montaña?",
    "q.t21#4.o0" to "Perder altura rápido y salir de la cresta, del agua y de los árboles aislados",
    "q.t21#4.o1" to "Refugiarse bajo un gran bloque en la cima",
    "q.t21#4.o2" to "Ponerse bajo un árbol",
    "q.t21#4.o3" to "Seguir caminando",
    "q.t21#4.e" to "Los puntos altos, el agua, los árboles aislados y el metal son las vías preferentes del rayo. Perder altura y separarse es la única medida eficaz.",

    "q.t21#5.p" to "¿Cuál es la postura correcta con tormenta?",
    "q.t21#5.o0" to "Separados en cuclillas, con los pies juntos, sin tumbarse",
    "q.t21#5.o1" to "Tumbado en el suelo",
    "q.t21#5.o2" to "De pie, bien recto",
    "q.t21#5.o3" to "Abrazado a un árbol",
    "q.t21#5.e" to "Con los pies juntos se reduce la tensión de paso; tumbado se aumenta la superficie de contacto con el suelo y el riesgo.",

    "q.t21#6.p" to "¿De qué hay que protegerse además con tiempo de tormenta?",
    "q.t21#6.o0" to "De la hipotermia por la caída brusca de temperatura",
    "q.t21#6.o1" to "De las riadas por lluvia intensa",
    "q.t21#6.o2" to "De perderse por la bajada repentina de visibilidad",
    "q.t21#6.o3" to "De las quemaduras UV",
    "q.t21#6.e" to "Las tormentas suelen traer bajada de temperatura, lluvia fuerte y niebla. Es un grupo de riesgos, no un riesgo único.",

    "q.t21#7.p" to "¿Para qué sirve dejar el plan de ruta a un contacto en caso de marcha nocturna o tormenta?",
    "q.t21#7.o0" to "Para que desde fuera se pueda activar una búsqueda a tiempo si el grupo no llega",
    "q.t21#7.o1" to "Por cortesía",
    "q.t21#7.o2" to "Para el seguro",
    "q.t21#7.o3" to "No sirve de nada",
    "q.t21#7.e" to "De noche y con mal tiempo el margen de error es mínimo. El plan de ruta es la condición para que alguien te busque.",
    // ---------- l32 Cuerdas fijas y sistemas de anclaje ----------
    "q.l32#0.p" to "Las cuerdas fijas se dividen en tres tipos según su uso. ¿Cuál de estos grupos es correcto?",
    "q.l32#0.o0" to "Pasamanos, cuerda fija corta, equipamiento de ruta",
    "q.l32#0.o1" to "Cuerda simple, doble y gemela",
    "q.l32#0.o2" to "Dinámica, estática y auxiliar",
    "q.l32#0.o3" to "Tramo superior, tramo medio, tramo inferior",
    "q.l32#0.e" to "Cada tipo corresponde a un escenario y a una forma estándar de trabajar. Si confundes el escenario, acabarás aplicando el criterio de un pasamanos a una ruta que se usa toda la temporada.",
    "q.l32#1.p" to "¿Qué cuerda se usa para una instalación fija de gran longitud?",
    "q.l32#1.o0" to "Cuerda estática (poco alargamiento)",
    "q.l32#1.o1" to "Cuerda dinámica",
    "q.l32#1.o2" to "Cuerda auxiliar",
    "q.l32#1.o3" to "Cinta plana",
    "q.l32#1.e" to "El alargamiento de la dinámica está pensado para absorber caídas; usada como fija hace que la persona rebote sobre la cuerda y además se desgasta antes.",
    "q.l32#2.p" to "¿Cuál es el diámetro habitual de la cuerda estática empleada como fija?",
    "q.l32#2.o0" to "9–11 mm",
    "q.l32#2.o1" to "5–6 mm",
    "q.l32#2.o2" to "7–8 mm",
    "q.l32#2.o3" to "12–14 mm",
    "q.l32#2.e" to "Demasiado fina se desgasta rápido y resbala en la mano; demasiado gruesa suma peso y volumen. 9–11 mm es el rango habitual del equipamiento de expedición.",
    "q.l32#3.p" to "¿Cuál es el problema de «dos anclajes enlazados en una misma cinta»?",
    "q.l32#3.o0" to "Es un fallo en serie, no redundancia",
    "q.l32#3.o1" to "Desperdicia cinta",
    "q.l32#3.o2" to "Queda feo",
    "q.l32#3.o3" to "Afecta a la velocidad de la cuerda",
    "q.l32#3.e" to "En una conexión en serie, el fallo de un punto afloja todo el sistema y provoca un cambio brusco de carga. La redundancia exige que cada punto llegue por separado al mosquetón principal.",
    "q.l32#4.p" to "En la lista de cinco controles del anclaje, ¿qué significa «independiente»?",
    "q.l32#4.o0" to "Que los dos anclajes estén en roca distinta, en árboles distintos o en bolts distintos",
    "q.l32#4.o1" to "Que los dos anclajes estén cerca",
    "q.l32#4.o2" to "Que usen la misma cinta",
    "q.l32#4.o3" to "Dos empotradores en la misma grieta",
    "q.l32#4.e" to "Dos empotradores en la misma grieta se arrancan juntos cuando falla ese bloque de roca. La independencia se juzga por si la causa del fallo es la misma.",
    "q.l32#5.p" to "¿A qué se refiere el control de «dirección» del anclaje?",
    "q.l32#5.o0" to "A que el anclaje aguante la dirección real del esfuerzo, no solo hacia abajo",
    "q.l32#5.o1" to "A que el anclaje mire al paisaje",
    "q.l32#5.o2" to "A que la cuerda vaya recta",
    "q.l32#5.o3" to "A que el anclaje quede arriba",
    "q.l32#5.e" to "El péndulo lateral al equipar y el balanceo al ascender generan esfuerzos laterales. Un anclaje pensado solo para abajo falla cuando la carga llega de lado.",
    "q.l32#6.p" to "¿Qué exige más atención en un anclaje en nieve?",
    "q.l32#6.o0" to "La resistencia del manto y el riesgo de fusión: al derretirse puede fallar todo el tramo",
    "q.l32#6.o1" to "Que la nieve blanda entierra mal",
    "q.l32#6.o2" to "Que la nieve moja la cuerda",
    "q.l32#6.o3" to "Que la estaca de nieve pesa mucho",
    "q.l32#6.e" to "La fiabilidad de un anclaje en nieve depende mucho de la temperatura y del tiempo transcurrido. El mismo anclaje por la tarde, con la nieve fundiendo, puede no ser el mismo que al amanecer.",
    "q.l32#7.p" to "¿Para qué sirve el nudo de tope al final de la cuerda?",
    "q.l32#7.o0" to "Para impedir que el cabo se salga del dispositivo",
    "q.l32#7.o1" to "Para recoger la cuerda más fácil",
    "q.l32#7.o2" to "Para marcar la longitud",
    "q.l32#7.o3" to "Para aumentar la fricción",
    "q.l32#7.e" to "Si el cabo sale del dispositivo al descender o al seguir de segundo, la persona pierde la conexión. El nudo de tope es el seguro más barato y el de mayor rendimiento.",
    "q.l32#8.p" to "¿Cuál es la función principal de un reenvío intermedio (re-belay)?",
    "q.l32#8.o0" to "Que la cuerda pase con suavidad y limitar caída y desgaste a un solo tramo",
    "q.l32#8.o1" to "Añadir peso",
    "q.l32#8.o2" to "Facilitar las fotos",
    "q.l32#8.o3" to "Sustituir a la reunión",
    "q.l32#8.e" to "Sin reenvíos, en una ruta larga la cuerda forma un ángulo enorme en cada esquina: cuesta recuperarla, el desgaste se concentra y la caída se alarga.",
    "q.l32#9.p" to "Al equipar una ruta, ¿puede haber gente debajo?",
    "q.l32#9.o0" to "No: mientras el equipador trabaja arriba, debajo debe quedar despejado",
    "q.l32#9.o1" to "Sí, para pasar herramientas",
    "q.l32#9.o2" to "Sí, siempre que lleven casco",
    "q.l32#9.o3" to "Sí, siempre que no jueguen",
    "q.l32#9.e" to "La caída de piedras es la principal fuente de lesiones al equipar. Tener gente debajo es regalarle al compañero la posición más peligrosa.",
    "q.l32#10.p" to "¿Qué cuatro cosas hay que decidir ya en la fase de planificación del equipamiento?",
    "q.l32#10.o0" to "Inicio y fin de cada tramo, reenvíos y puntos de retirada, longitud de cuerda, forma de fijación",
    "q.l32#10.o1" to "Color, marca, precio, peso",
    "q.l32#10.o2" to "Quién sube primero, quién hace fotos, quién hierve agua, quién lleva las cuentas",
    "q.l32#10.o3" to "Tiempo, humor, presupuesto, vacaciones",
    "q.l32#10.e" to "Esos cuatro puntos deciden si el equipamiento se puede retirar con seguridad. Saltarse la planificación y empezar a colgar cuerda es dejar la retirada en manos de la suerte.",
    "q.l32#11.p" to "¿Por qué una cuerda fija exige «revisión periódica y registro por escrito»?",
    "q.l32#11.o0" to "Porque las rutas equipadas suelen usarse toda la temporada y el estado cambia con el sol, el roce y los ciclos de hielo-deshielo",
    "q.l32#11.o1" to "Por auditoría",
    "q.l32#11.o2" to "Para repartir responsabilidades",
    "q.l32#11.o3" to "No hace falta",
    "q.l32#11.e" to "La funda peluda, el cuerpo endurecido y los aplastamientos localizados son señales de retirada. Sin registro, nadie puede decir cuántos días lleva colgada esa cuerda.",
    "q.l32#12.p" to "¿Cuáles forman parte de los cinco controles del anclaje?",
    "q.l32#12.o0" to "Independencia",
    "q.l32#12.o1" to "Equilibrio de cargas",
    "q.l32#12.o2" to "Dirección del esfuerzo",
    "q.l32#12.o3" to "Protección de aristas",
    "q.l32#12.e" to "El quinto es el respaldo. El más fácil de olvidar es la arista: una cinta cortada por un canto puede conservar solo una fracción de su resistencia.",
    "q.l32#13.p" to "¿Qué situaciones indican que una cuerda fija debe retirarse?",
    "q.l32#13.o0" to "Funda peluda y núcleo que se puede palpar",
    "q.l32#13.o1" to "Cuerda endurecida, tacto quebradizo",
    "q.l32#13.o2" to "Aplastamiento o deformación localizada",
    "q.l32#13.o3" to "El color se ha destenido",
    "q.l32#13.e" to "Los tres primeros son daño estructural. El color es solo apariencia, aunque conviene recordar su relación con el envejecimiento por radiación ultravioleta.",
    "q.l32#14.p" to "¿Qué incluye la autoprotección durante el equipamiento?",
    "q.l32#14.o0" to "Al menos dos puntos de conexión en todo momento",
    "q.l32#14.o1" to "Casco puesto",
    "q.l32#14.o2" to "Vigilancia arriba y control de caída de piedras",
    "q.l32#14.o3" to "Gestión del cabo sobrante en la bolsa de cuerda",
    "q.l32#14.e" to "Los cuatro forman la seguridad de la zona de trabajo. El único principio rígido es el de los dos puntos; la excepción es ir encordado directamente en punta.",
    "q.l32#15.p" to "¿En qué niveles se puede aplicar redundancia en un sistema de cuerda fija?",
    "q.l32#15.o0" to "Redundancia de anclaje (dos puntos independientes)",
    "q.l32#15.o1" to "Redundancia de conexión (PAS o cinta de respaldo)",
    "q.l32#15.o2" to "Redundancia de dispositivo (nudo autobloqueante de respaldo)",
    "q.l32#15.o3" to "Redundancia de color (comprar varios colores)",
    "q.l32#15.e" to "Las tres capas cubren que el sistema no falle, que la transferencia no quede en el aire y que ningún dispositivo cargue solo. El color no tiene nada que ver con la seguridad.",
    "q.l32#16.p" to "Ordena correctamente la instalación de un tramo de cuerda fija.",
    "q.l32#16.o0" to "Fijar inicio, fin y posición de los reenvíos, y estimar la longitud de cuerda",
    "q.l32#16.o1" to "Montar los anclajes (independientes, equilibrados, con respaldo)",
    "q.l32#16.o2" to "Tender la cuerda y colocar los reenvíos intermedios",
    "q.l32#16.o3" to "Hacer el nudo de tope y registrar el estado de la cuerda",
    "q.l32#16.e" to "Al estimar la longitud hay que dejar margen para nudos y conexiones: mejor larga que corta. El nudo de tope va al final, pero no se puede omitir.",
    "q.l32#17.p" to "Si uno de los anclajes resulta dudoso, ¿cuál es el orden correcto de actuación?",
    "q.l32#17.o0" to "Dejar de usar ese tramo y poner a las personas en un lugar seguro",
    "q.l32#17.o1" to "Añadir un punto de respaldo independiente",
    "q.l32#17.o2" to "Volver a equilibrar las cargas",
    "q.l32#17.o3" to "Revisar, registrar y decidir después si se continúa",
    "q.l32#17.e" to "Primero se pone a la gente a salvo y luego se habla de soluciones técnicas. Si el orden se invierte, la propia maniobra se convierte en el accidente.",
    "q.l32#18.p" to "¿Cuál es la rutina diaria correcta en una cuerda fija de uso prolongado?",
    "q.l32#18.o0" to "Revisar anclajes y estado de la cuerda antes de salir",
    "q.l32#18.o1" to "Confirmar las dos conexiones al pasar",
    "q.l32#18.o2" to "Revisar desgaste y nudo de tope al recoger",
    "q.l32#18.o3" to "Anotar la fecha de revisión y los problemas",
    "q.l32#18.e" to "El valor de esta rutina es convertir la revisión en hábito. Gestionar de memoria una cuerda fija de toda la temporada acaba en un olvido.",
    "q.l32#19.p" to "La norma de la cuerda dinámica es EN ______.",
    "q.l32#19.a0" to "892",
    "q.l32#19.e" to "Dinámica EN 892 / UIAA 101; estática EN 1891 / UIAA 110. Al comprar y al revisar, se contrasta por número de norma.",
    "q.l32#20.p" to "Para una cuerda fija se elige cuerda ______ (responde «dinámica» o «estática»).",
    "q.l32#20.a0" to "estática",
    "q.l32#20.a1" to "cuerda estática",
    "q.l32#20.e" to "La estática tiene poco alargamiento y buena resistencia al roce, ideal para fijación prolongada. El alargamiento de la dinámica hace que la fija rebote sin parar.",
    "q.l32#21.p" to "Al equipar, el cabo debe ______ para que no se salga del dispositivo.",
    "q.l32#21.a0" to "hacer un nudo",
    "q.l32#21.a1" to "nudo de tope",
    "q.l32#21.e" to "Es el paso que más se omite y el de consecuencias más directas.",
    "q.l32#22.p" to "El rango de diámetro habitual de la cuerda estática de expedición es ______–11 mm.",
    "q.l32#22.a0" to "9",
    "q.l32#22.e" to "9–11 mm equilibra resistencia al roce y peso. Por debajo de 9 mm se desgasta rápido; por encima de 11 mm la carga se nota mucho.",
    "q.l32#23.p" to "Relaciona cada tipo de cuerda fija con su escenario típico.",
    "q.l32#23.l0" to "Pasamanos",
    "q.l32#23.l1" to "Cuerda fija corta",
    "q.l32#23.l2" to "Equipamiento de ruta",
    "q.l32#23.l3" to "Reenvío intermedio",
    "q.l32#23.r0" to "Tramo expuesto y corto, se pasa agarrándose",
    "q.l32#23.r1" to "Una pendiente o un largo por el que se sube y se baja repetidamente",
    "q.l32#23.r2" to "Ruta larga, varios largos, con carga, de uso toda la temporada",
    "q.l32#23.r3" to "Dividir la cuerda larga y reducir ángulos y desgaste",
    "q.l32#23.e" to "El escenario fija el criterio: cuanto más duradero, más cargado y más expuesto, mayores exigencias de redundancia y de registro del estado de la cuerda.",
    "q.l32#24.p" to "Relaciona cada equipo con su norma.",
    "q.l32#24.l0" to "Cuerda estática",
    "q.l32#24.l1" to "Cuerda dinámica",
    "q.l32#24.l2" to "Bloqueador",
    "q.l32#24.l3" to "Arnés",
    "q.l32#24.r0" to "EN 1891 / UIAA 110",
    "q.l32#24.r1" to "EN 892 / UIAA 101",
    "q.l32#24.r2" to "EN 567",
    "q.l32#24.r3" to "EN 12277",
    "q.l32#24.e" to "La norma es la base para comprar y revisar, y también sirve para saber para qué tipo de carga se diseñó cada equipo.",
    "q.l32#25.p" to "Relaciona cada problema de anclaje con su consecuencia.",
    "q.l32#25.l0" to "Fallo en serie",
    "q.l32#25.l1" to "Dirección de carga única",
    "q.l32#25.l2" to "Arista sin proteger",
    "q.l32#25.l3" to "Punto único sin respaldo",
    "q.l32#25.r0" to "Un punto que falla afloja todo el sistema y cambia la carga de golpe",
    "q.l32#25.r1" to "El anclaje se arranca o se rompe ante carga lateral",
    "q.l32#25.r2" to "La cinta se corta y pierde gran parte de su resistencia",
    "q.l32#25.r3" to "Si falla la única conexión, se pierde toda la protección",
    "q.l32#25.e" to "Cuatro problemas, cuatro modos de fallo. Suelen coincidir, así que la revisión se hace punto por punto, no con un «parece que está bien».",
    "q.l32#26.p" to "Un compañero dice «esta cuerda solo lleva una temporada, no hace falta revisarla». ¿Cuál es la respuesta más razonable?",
    "q.l32#26.o0" to "El desgaste de una fija depende de la exposición y el roce, no de la duración de la temporada",
    "q.l32#26.o1" to "Tiene razón, no hace falta revisarla",
    "q.l32#26.o2" to "Basta con cambiarle el color",
    "q.l32#26.o3" to "Mientras no se rompa, se puede usar",
    "q.l32#26.e" to "El sol, los ciclos de hielo-deshielo y el roce contra las aristas acumulan daño. La periodicidad de revisión la marca la intensidad de uso, no el calendario.",
    "q.l32#27.p" to "¿Cuál es el criterio para estimar la longitud de cuerda al equipar?",
    "q.l32#27.o0" to "Dejar margen para nudos y conexiones: mejor larga que corta",
    "q.l32#27.o1" to "Exactamente la longitud del tramo",
    "q.l32#27.o2" to "Cuanto más corta, más ligera y mejor",
    "q.l32#27.o3" to "Calcularla con la distancia en línea recta del mapa",
    "q.l32#27.e" to "Si queda corta se pierde el tramo entero; si queda larga, solo pesa un poco más. Nudos, conexiones y reenvíos consumen metros y hay que contarlos.",
    "q.l32#28.p" to "Un compañero va a pasar un tramo de cuerda fija con péndulo lateral. ¿Qué debe confirmar ante todo?",
    "q.l32#28.o0" to "Si los anclajes aguantan carga lateral y si hay un segundo punto de conexión",
    "q.l32#28.o1" to "El color de la cuerda",
    "q.l32#28.o2" to "La longitud de la cuerda",
    "q.l32#28.o3" to "Su peso corporal",
    "q.l32#28.e" to "El péndulo lateral convierte un anclaje pensado «hacia abajo» en carga lateral, y así es exactamente como se arrancan muchos anclajes.",
    "q.l32#29.p" to "¿Por qué una ruta con cuerda fija necesita «puntos de retirada»?",
    "q.l32#29.o0" to "Para poder salir con seguridad dentro de un tramo si cambia el tiempo o el estado de la gente",
    "q.l32#29.o1" to "Para descansar",
    "q.l32#29.o2" to "Para acumular material",
    "q.l32#29.o3" to "Para hacer fotos",
    "q.l32#29.e" to "En una ruta larga no siempre se llega arriba. El punto de retirada decide si, cuando la cosa empeora, todavía queda alternativa.",

    // ---------- l33 Ascenso, paso de nudos y cambio de cuerda ----------
    "q.l33#0.p" to "¿Qué elemento NO forma parte de la configuración estándar para ascender por una cuerda fija?",
    "q.l33#0.o0" to "Descendedor (ocho o tubular)",
    "q.l33#0.o1" to "Bloqueador de mano",
    "q.l33#0.o2" to "Estribo",
    "q.l33#0.o3" to "Nudo autobloqueante de respaldo",
    "q.l33#0.e" to "Al ascender no hace falta descendedor; pertenece al cambio de cuerda y al descenso. La lista se arma según la maniobra actual, no colgando todo el material.",
    "q.l33#1.p" to "¿Cuál es la secuencia rítmica del ascenso?",
    "q.l33#1.o0" to "Levantarse, sentarse, empujar",
    "q.l33#1.o1" to "Tirar, apoyar, saltar",
    "q.l33#1.o2" to "Agacharse, saltar, agarrar",
    "q.l33#1.o3" to "Empujar, tirar, sentarse",
    "q.l33#1.e" to "Pisar el estribo y levantarse, subir el centro de gravedad, empujar el bloqueador de pecho, sentarse y empujar el de mano. Con el ritmo correcto se ahorra la mitad de la energía.",
    "q.l33#2.p" to "¿Dónde debe ir el centro de gravedad al ascender?",
    "q.l33#2.o0" to "Pegado a la cuerda",
    "q.l33#2.o1" to "Lo más hacia fuera posible",
    "q.l33#2.o2" to "Balanceándose a los lados",
    "q.l33#2.o3" to "Lo más inclinado hacia atrás posible",
    "q.l33#2.e" to "Si el peso se va hacia fuera, los bloqueadores reciben carga lateral y pueden soltarse, y el gasto físico se dispara. Pegarse a la cuerda es seguridad y también eficacia.",
    "q.l33#3.p" to "¿Cuál es la excepción al principio de las dos conexiones?",
    "q.l33#3.o0" to "Ir encordado directamente en punta",
    "q.l33#3.o1" to "Cuando hace buen tiempo",
    "q.l33#3.o2" to "De día",
    "q.l33#3.o3" to "En tramos cortos",
    "q.l33#3.e" to "Al abrir en punta la persona forma parte del sistema y no puede colgar un segundo punto. Fuera de eso, siempre deben existir dos conexiones independientes.",
    "q.l33#4.p" to "¿Cuál es el primer principio al pasar un nudo?",
    "q.l33#4.o0" to "Primero crear la conexión nueva y después soltar la vieja",
    "q.l33#4.o1" to "Primero soltar la vieja y después crear la nueva",
    "q.l33#4.o2" to "Mover los dos bloqueadores a la vez",
    "q.l33#4.o3" to "Saltarse el nudo directamente",
    "q.l33#4.e" to "Con el orden invertido aparece un instante con un solo punto, o con ninguno. Pasar un nudo es, en esencia, una transferencia de sistema controlada.",
    "q.l33#5.p" to "Al pasar un nudo, ¿se pueden soltar los dos bloqueadores a la vez?",
    "q.l33#5.o0" to "No: en todo momento al menos uno debe estar en la cuerda y cargado",
    "q.l33#5.o1" to "Sí, si se hace rápido",
    "q.l33#5.o2" to "Sí, si alguien mira",
    "q.l33#5.o3" to "Sí, con nudos cortos",
    "q.l33#5.e" to "Soltar los dos significa perder toda conexión ascendente. Mejor gastar un minuto en recolocar que jugársela una vez.",
    "q.l33#6.p" to "¿Cuál es el primer paso al pasar de ascenso a descenso?",
    "q.l33#6.o0" to "Colgarse del anclaje con PAS o cinta",
    "q.l33#6.o1" to "Soltar primero el bloqueador de mano",
    "q.l33#6.o2" to "Montar primero el descendedor",
    "q.l33#6.o3" to "Abrir primero el bloqueador de pecho",
    "q.l33#6.e" to "Primero se obtiene una conexión independiente del sistema de ascenso; solo entonces se puede desmontar el sistema viejo. Es el punto de partida de toda maniobra de cambio de cuerda.",
    "q.l33#7.p" to "Una vez montado el descendedor y antes de soltar el bloqueador, ¿qué hay que hacer?",
    "q.l33#7.o0" to "Cargar el descendedor y probarlo",
    "q.l33#7.o1" to "Abrir el arnés",
    "q.l33#7.o2" to "Recoger la cuerda",
    "q.l33#7.o3" to "Quitarse el casco",
    "q.l33#7.e" to "«Probar la carga» es la única forma de confirmar que el sistema nuevo aguanta de verdad el peso. Si se salta este paso y se desmonta el viejo, la caída es inmediata.",
    "q.l33#8.p" to "¿Para qué sirve el nudo de fricción de respaldo por encima del descendedor?",
    "q.l33#8.o0" to "Se bloquea solo si se suelta la mano, como respaldo independiente",
    "q.l33#8.o1" to "Aumentar la velocidad de descenso",
    "q.l33#8.o2" to "Proteger la cuerda",
    "q.l33#8.o3" to "Marcar la posición",
    "q.l33#8.e" to "El nudo de fricción muerde la cuerda al soltar la mano de freno. Es la única defensa en el instante más peligroso: el de la mano abierta.",
    "q.l33#9.p" to "¿Para qué se hace el nudo de tope antes de descender?",
    "q.l33#9.o0" to "Para que el cabo no se salga del descendedor",
    "q.l33#9.o1" to "Para recoger la cuerda más fácil",
    "q.l33#9.o2" to "Para marcar la longitud",
    "q.l33#9.o3" to "Para reducir el desgaste",
    "q.l33#9.e" to "Si la cuerda no llega, que el cabo se salga significa perder el frenado al instante. El nudo de tope es revisión obligatoria antes de descender.",
    "q.l33#10.p" to "Al pasar un reenvío intermedio, ¿cuál es el orden correcto?",
    "q.l33#10.o0" to "Colgarse primero del anclaje del reenvío, mover después los bloqueadores y soltar al final la conexión al anclaje",
    "q.l33#10.o1" to "Mover primero los bloqueadores y colgarse después",
    "q.l33#10.o2" to "Pasar directamente, sin colgarse",
    "q.l33#10.o3" to "Soltar primero el anclaje y moverse después",
    "q.l33#10.e" to "En el reenvío la cuerda queda retenida por el mosquetón: hay poco espacio y los gestos se deforman. Con una conexión independiente ya montada existe margen de error.",
    "q.l33#11.p" to "¿Cómo se resuelve una cuerda atascada?",
    "q.l33#11.o0" to "Cambiar el ángulo de tracción o tirar desde un lado; nunca tirar con fuerza desde debajo",
    "q.l33#11.o1" to "Tirar con fuerza desde la vertical",
    "q.l33#11.o2" to "Tirar con todo el peso del cuerpo",
    "q.l33#11.o3" to "Cortar directamente",
    "q.l33#11.e" to "Tirar desde la vertical expone a la cuerda que rebota o a las piedras, y además puede apretar más el nudo. Cambiar el ángulo es el primer paso más eficaz.",
    "q.l33#12.p" to "Al recuperar la cuerda tras un rápel, ¿de qué lado se tira?",
    "q.l33#12.o0" to "Del lado con menos fricción",
    "q.l33#12.o1" to "Del lado con más fricción",
    "q.l33#12.o2" to "De cualquiera de los dos",
    "q.l33#12.o3" to "De los dos lados a la vez",
    "q.l33#12.e" to "Tirar del lado con menos fricción facilita la recuperación y reduce el desgaste de la funda. Eso sí, con el cabo ya anudado y sin enganches.",
    "q.l33#13.p" to "Al ascender por cuerda fija, ¿qué material hay que llevar siempre encima?",
    "q.l33#13.o0" to "Bloqueador de mano y de pecho (o un segundo nudo autobloqueante)",
    "q.l33#13.o1" to "Estribo",
    "q.l33#13.o2" to "Nudo autobloqueante de respaldo y PAS",
    "q.l33#13.o3" to "Casco",
    "q.l33#13.e" to "Los cuatro forman el sistema completo de ascenso y respaldo. Si falta uno, al pasar nudos y cambiar de cuerda te ves obligado a trabajar con un solo punto.",
    "q.l33#14.p" to "¿Cuáles son los errores más frecuentes en el cambio de cuerda?",
    "q.l33#14.o0" to "Soltar el sistema viejo antes de crear el nuevo",
    "q.l33#14.o1" to "Quitar los bloqueadores sin probar la carga del descendedor",
    "q.l33#14.o2" to "Soltar los dos bloqueadores a la vez",
    "q.l33#14.o3" to "Colgarse del anclaje antes de cambiar de cuerda",
    "q.l33#14.e" to "Los tres primeros son errores de orden. El último es justo lo correcto: colgarse primero del anclaje es precisamente lo que evita los otros tres.",
    "q.l33#15.p" to "¿Qué revisiones hay que completar antes de descender?",
    "q.l33#15.o0" to "El descendedor está enhebrado en el sentido correcto",
    "q.l33#15.o1" to "El nudo de fricción de respaldo está puesto y funciona",
    "q.l33#15.o2" to "El cabo está anudado",
    "q.l33#15.o3" to "La cuerda llega a la siguiente reunión",
    "q.l33#15.e" to "Si falta una, se puede perder el control. Esta batería de comprobaciones debe estar terminada antes de soltar la protección.",
    "q.l33#16.p" to "Al pasar un nudo, ¿qué puede servir como «conexión nueva»?",
    "q.l33#16.o0" to "PAS o cinta por encima del nudo",
    "q.l33#16.o1" to "Un anclaje cercano",
    "q.l33#16.o2" to "Un segundo bloqueador montado más arriba",
    "q.l33#16.o3" to "Agarrar la cuerda con la mano",
    "q.l33#16.e" to "Agarrar con la mano no es una conexión: al soltar desaparece. Las tres primeras forman un punto de carga independiente del sistema viejo.",
    "q.l33#17.p" to "Ordena los pasos para «ascender pasando un nudo».",
    "q.l33#17.o0" to "Reducir el ritmo al acercarse al nudo y observar su posición y el tramo de arriba",
    "q.l33#17.o1" to "Conectarse con PAS o cinta por encima del nudo o a un anclaje cercano",
    "q.l33#17.o2" to "Montar un segundo bloqueador o nudo por encima y levantarse para transferir el peso",
    "q.l33#17.o3" to "Soltar el bloqueador de abajo y montarlo por encima del nudo",
    "q.l33#17.o4" to "Confirmar que la conexión nueva está cargada y soltar después el PAS de respaldo",
    "q.l33#17.e" to "El núcleo de los cinco pasos es tener siempre un punto de más. Si falta uno, queda un hueco con un solo punto cargado o incluso sin conexión.",
    "q.l33#18.p" to "Ordena la secuencia de «ascenso a descenso».",
    "q.l33#18.o0" to "Colgarse del anclaje (PAS o cinta)",
    "q.l33#18.o1" to "Montar el descendedor con el enhebrado correcto",
    "q.l33#18.o2" to "Cargar el descendedor y probarlo",
    "q.l33#18.o3" to "Soltar el bloqueador de mano y conservar el de pecho o el de respaldo",
    "q.l33#18.o4" to "Soltar el otro bloqueador y confirmar descendedor y respaldo",
    "q.l33#18.o5" to "Soltar el PAS y empezar a descender",
    "q.l33#18.e" to "El orden es fijo, no se ajusta sobre la marcha. Cada paso garantiza que hay al menos una conexión fiable.",
    "q.l33#19.p" to "Ordena la secuencia de «descenso a ascenso».",
    "q.l33#19.o0" to "Montar un nudo o bloqueador por encima del descendedor y conectarlo al arnés",
    "q.l33#19.o1" to "Levantarse y transferir el peso al nudo",
    "q.l33#19.o2" to "Montar el segundo bloqueador o el estribo y confirmar la carga",
    "q.l33#19.o3" to "Soltar el descendedor",
    "q.l33#19.o4" to "Empezar a ascender",
    "q.l33#19.e" to "La clave está en el tercer paso: el sistema nuevo ya debe estar cargado para poder soltar el descendedor.",
    "q.l33#20.p" to "Ordena los tres pasos para «descender pasando un nudo».",
    "q.l33#20.o0" to "Hacer un respaldo con PAS por encima del nudo o al anclaje",
    "q.l33#20.o1" to "Mover el descendedor por debajo del nudo, tensar y probar la carga",
    "q.l33#20.o2" to "Soltar el PAS y seguir descendiendo",
    "q.l33#20.e" to "Cuando el nudo es grueso y no pasa, primero se baja el nudo de respaldo por debajo y luego el descendedor: entre las dos transferencias siempre queda una conexión fiable.",
    "q.l33#21.p" to "Al ascender por cuerda fija hay que mantener ______ puntos de conexión independientes en todo momento.",
    "q.l33#21.a0" to "2",
    "q.l33#21.a1" to "dos",
    "q.l33#21.e" to "Las dos conexiones son el principio rígido del trabajo con cuerda fija. La única excepción es ir encordado directamente en punta.",
    "q.l33#22.p" to "Al pasar de ascenso a descenso hay que colgarse primero del ______ y después soltar los bloqueadores.",
    "q.l33#22.a0" to "anclaje",
    "q.l33#22.a1" to "reunión",
    "q.l33#22.a2" to "reenvío",
    "q.l33#22.e" to "Obtener primero una conexión que no dependa del sistema viejo es el punto de partida de todo cambio de cuerda.",
    "q.l33#23.p" to "El nudo de fricción de respaldo montado por encima del descendedor suele ser un prusik o un ______.",
    "q.l33#23.a0" to "autoblock",
    "q.l33#23.a1" to "nudo francés",
    "q.l33#23.a2" to "nudo de fricción",
    "q.l33#23.e" to "Los dos son respaldos que bloquean al soltar la mano. Montados al revés o con la longitud equivocada no funcionan, así que hay que practicarlos hasta confirmarlos con los ojos cerrados.",
    "q.l33#24.p" to "Relaciona cada maniobra con su principio clave.",
    "q.l33#24.l0" to "Pasar un nudo",
    "q.l33#24.l1" to "Pasar un reenvío",
    "q.l33#24.l2" to "Ascenso a descenso",
    "q.l33#24.l3" to "Descenso a ascenso",
    "q.l33#24.r0" to "Primero crear la conexión nueva y después soltar la vieja",
    "q.l33#24.r1" to "Colgarse primero del anclaje y mover después los dispositivos",
    "q.l33#24.r2" to "Colgarse, montar descendedor, probar, soltar bloqueadores",
    "q.l33#24.r3" to "Soltar el descendedor solo cuando el sistema nuevo esté cargado",
    "q.l33#24.e" to "Las cuatro maniobras comparten la estructura «establecer, transferir, soltar». Recordar la estructura resiste mejor al olvido que memorizar pasos.",
    "q.l33#25.p" to "Relaciona cada letra de la lista ABCDE con su contenido.",
    "q.l33#25.l0" to "A de anclajes",
    "q.l33#25.l1" to "B de respaldo",
    "q.l33#25.l2" to "C de conexiones",
    "q.l33#25.l3" to "E de escape",
    "q.l33#25.r0" to "Dos puntos independientes, equilibrados, dirección de carga correcta, aristas protegidas",
    "q.l33#25.r1" to "PAS o nudo en su sitio, cada dispositivo con su respaldo",
    "q.l33#25.r2" to "Mosquetón cerrado, nudos apretados, cabo anudado",
    "q.l33#25.r3" to "Saber dónde está el punto de retirada más cercano, cuerda suficiente, comunicación clara",
    "q.l33#25.e" to "El valor de esta lista es repasarla antes de cada ascenso. No sustituye al criterio, pero frena la gran mayoría de los errores tontos.",
    "q.l33#26.p" to "Un compañero quiere «soltar un bloqueador y montar el otro enseguida» al pasar un nudo. ¿Qué le dices?",
    "q.l33#26.o0" to "Que primero hay que crear la conexión con PAS o al anclaje: no se admite un hueco sin conexión",
    "q.l33#26.o1" to "Que basta con hacerlo rápido",
    "q.l33#26.o2" to "Que de día se puede",
    "q.l33#26.o3" to "Que con nudos cortos se puede",
    "q.l33#26.e" to "«Enseguida» significa tolerancia cero si la mano falla. El margen para pasar un nudo hay que crearlo con una tercera conexión.",
    "q.l33#27.p" to "En un reenvío hay que sacar la cuerda del mosquetón y volver a meterla. ¿Cómo se hace?",
    "q.l33#27.o0" to "Colgarse primero del anclaje, manipular después la cuerda y soltar el respaldo al final",
    "q.l33#27.o1" to "Sacar primero la cuerda y colgarse después",
    "q.l33#27.o2" to "Pedir a alguien que sujete la cuerda",
    "q.l33#27.o3" to "Abrir el mosquetón directamente",
    "q.l33#27.e" to "En el instante de sacar la cuerda se puede depender por completo de la conexión vieja. Si antes no hay una conexión independiente, la maniobra no tiene sentido.",
    "q.l33#28.p" to "¿Por qué el cambio de cuerda es el momento más delicado del trabajo con cuerda fija?",
    "q.l33#28.o0" to "Porque hay que transferir entre desmontar el sistema viejo y montar el nuevo, con el margen de error más estrecho",
    "q.l33#28.o1" to "Porque hay mucho material",
    "q.l33#28.o2" to "Porque cansa mucho",
    "q.l33#28.o3" to "Porque hacen falta dos personas",
    "q.l33#28.e" to "Pasar un nudo es «añadir un punto»; cambiar de cuerda es «cambiar todo un sistema». Cualquier error de orden lleva directamente a perder la conexión.",
    // ---------- l34 Progresión en glaciar y elección de itinerario ----------
    "q.l34#0.p" to "¿Cuál es el terreno más peligroso y a la vez más subestimado de un glaciar?",
    "q.l34#0.o0" to "Las grietas y los puentes de nieve cubiertos por nieve reciente",
    "q.l34#0.o1" to "Las crestas de la morena",
    "q.l34#0.o2" to "Las llanuras de nieve llanas",
    "q.l34#0.o3" to "Las laderas de derrubios de los costados",
    "q.l34#0.e" to "Una grieta tapada por nieve nueva se ve igual que una superficie normal. En los accidentes de glaciar, la caída en grieta es la que más se repite.",
    "q.l34#1.p" to "¿Dónde aparecen con más frecuencia las grietas transversales?",
    "q.l34#1.o0" to "En los cambios de pendiente (parte alta, parte baja, al superar un resalte de hielo)",
    "q.l34#1.o1" to "En el centro exacto del glaciar",
    "q.l34#1.o2" to "En el extremo inferior del glaciar",
    "q.l34#1.o3" to "Sobre la morena",
    "q.l34#1.e" to "Un cambio brusco de pendiente implica tracción o compresión, y ahí se abren las grietas. Observar la zona de arriba antes de subir una pendiente es el hábito más útil.",
    "q.l34#2.p" to "Las grietas longitudinales de los laterales del glaciar se deben a...",
    "q.l34#2.o0" to "La tracción que genera el roce del hielo con el terreno en los bordes",
    "q.l34#2.o1" to "Impactos de piedras",
    "q.l34#2.o2" to "El pisoteo de los montañeros",
    "q.l34#2.o3" to "El agua de fusión",
    "q.l34#2.e" to "El centro fluye rápido y los bordes despacio; esa diferencia de velocidad genera cizalla y tracción. Por eso avanzar por la línea central suele ser más seguro que pegado al borde.",
    "q.l34#3.p" to "¿Qué distancia se deja normalmente entre los miembros de una cordada?",
    "q.l34#3.o0" to "8–10 m",
    "q.l34#3.o1" to "2–3 m",
    "q.l34#3.o2" to "20–30 m",
    "q.l34#3.o3" to "Cuanto menos, mejor",
    "q.l34#3.e" to "Con distancia corta, uno que cae arrastra al compañero; con distancia larga aumentan la distancia de frenado y la dificultad del rescate. En zona de grietas densas se acorta, pero no por debajo de 6–8 m.",
    "q.l34#4.p" to "¿Para qué se hacen nudos en la cuerda al ir encordados?",
    "q.l34#4.o0" to "Para limitar la profundidad de caída, añadir fricción de frenado y facilitar el agarre en el rescate",
    "q.l34#4.o1" to "Para que la cuerda no se enrede",
    "q.l34#4.o2" to "Para marcar la longitud",
    "q.l34#4.o3" to "Por estética",
    "q.l34#4.e" to "Los nudos crean resistencia y puntos de tope en la boca de la grieta y reducen claramente la profundidad. Como contrapartida, recuperar la cuerda cuesta algo más, pero merece la pena.",
    "q.l34#5.p" to "¿Cuál es la ventaja principal de una cordada de tres frente a una de dos?",
    "q.l34#5.o0" to "Si uno cae, dos frenan y uno puede preparar el sistema de rescate: hay mucho más margen",
    "q.l34#5.o1" to "Se avanza más rápido",
    "q.l34#5.o2" to "La cuerda pesa menos",
    "q.l34#5.o3" to "No hace falta hacer nudos",
    "q.l34#5.e" to "En una cordada de dos, quien frena apenas puede manejar el sistema de rescate; con tres existe el reparto «frenar + montar sistema».",
    "q.l34#6.p" to "Para juzgar si un puente de nieve es fiable, ¿qué se mira primero?",
    "q.l34#6.o0" to "El color y las depresiones: si está oscuro, azulado o tiene grietas radiales, es fino",
    "q.l34#6.o1" to "Cuántas huellas hay",
    "q.l34#6.o2" to "Si la superficie está lisa",
    "q.l34#6.o3" to "Si hay viento",
    "q.l34#6.e" to "La resistencia del puente depende de la luz y del espesor del manto. El color y las depresiones son la pista más directa; las huellas solo dicen que otros pasaron, no que sea seguro.",
    "q.l34#7.p" to "¿Cuál es el mejor momento para cruzar una zona de grietas densas?",
    "q.l34#7.o0" to "De madrugada o en las horas de baja temperatura nocturna",
    "q.l34#7.o1" to "A mediodía",
    "q.l34#7.o2" to "Por la tarde",
    "q.l34#7.o3" to "Da igual la hora",
    "q.l34#7.e" to "Con frío los puentes están más firmes; por la tarde, con la fusión, la resistencia baja de forma notable. El horario de paso se diseña alrededor de este hecho.",
    "q.l34#8.p" to "¿Cuál es la forma correcta de pasar por la zona de seracs?",
    "q.l34#8.o0" to "Pasar rápido, mantener distancia, llevar casco y no pararse dentro",
    "q.l34#8.o1" to "Ir encordados y despacio",
    "q.l34#8.o2" to "Descansar dentro de la zona",
    "q.l34#8.o3" to "Pararse a hacer fotos",
    "q.l34#8.e" to "En la zona de seracs el riesgo es el colapso de bloques de hielo, distinto del de las grietas: cae todo de golpe. Cuanto menos tiempo dentro, mejor, y no se hace reunión ahí.",
    "q.l34#9.p" to "Al avanzar por el glaciar, ¿en qué estado debe estar la cuerda?",
    "q.l34#9.o0" to "Ligeramente tensa: ni arrastrando por la nieve ni demasiado floja",
    "q.l34#9.o1" to "Totalmente floja, arrastrando",
    "q.l34#9.o2" to "Muy tensa",
    "q.l34#9.o3" to "Recogida en la mano",
    "q.l34#9.e" to "Una cuerda floja genera carga de choque en el instante de la caída; una cuerda tensa arrastra al compañero. Tensión moderada más nudos en la cuerda es la combinación más estable.",
    "q.l34#10.p" to "Ante una grieta evidente, ¿qué es lo primero?",
    "q.l34#10.o0" to "Rodearla y buscar un punto más estrecho o un puente ya formado",
    "q.l34#10.o1" to "Saltarla",
    "q.l34#10.o2" to "Pisar el borde para ver la profundidad",
    "q.l34#10.o3" to "Ensancharla con el piolet",
    "q.l34#10.e" to "El primer principio del itinerario glaciar es rodear. Saltar y asomarse al borde son las dos formas más habituales de autolesionarse.",
    "q.l34#11.p" to "¿Por qué avanzar por la línea central del glaciar suele ser más seguro?",
    "q.l34#11.o0" to "En los laterales hay más grietas por tracción; en el centro el esfuerzo está más repartido",
    "q.l34#11.o1" to "En el centro la nieve es más espesa",
    "q.l34#11.o2" to "El centro es más corto",
    "q.l34#11.o3" to "Por el centro pasa más gente",
    "q.l34#11.e" to "En el centro suele haber menos grietas y puentes de menor luz. Pero en la zona de seracs y en los resaltes hay que volver a evaluar: no se aplica mecánicamente.",
    "q.l34#12.p" to "¿Qué hay que valorar al evaluar el riesgo de un itinerario glaciar?",
    "q.l34#12.o0" to "Densidad de grietas y estado de los puentes",
    "q.l34#12.o1" to "Riesgo de seracs y de caída de hielo",
    "q.l34#12.o2" to "Temperatura y sol del día (afectan a la resistencia de los puentes)",
    "q.l34#12.o3" to "Número de personas y tipo de encordamiento",
    "q.l34#12.e" to "Los cuatro se influyen: la temperatura decide los puentes, el número decide la cordada y la cordada decide las consecuencias de una caída. Evaluar el riesgo es mirarlos juntos.",
    "q.l34#13.p" to "¿Qué señales indican que un puente de nieve puede no ser fiable?",
    "q.l34#13.o0" to "La superficie se hunde de forma evidente",
    "q.l34#13.o1" to "Color oscuro o azulado",
    "q.l34#13.o2" to "Grietas radiales en el borde",
    "q.l34#13.o3" to "Nieve nueva encima y eco hueco debajo",
    "q.l34#13.e" to "Los cuatro son formas distintas de decir «resistencia insuficiente». Si se oye eco hueco, hay que retroceder, no dar un paso más.",
    "q.l34#14.p" to "¿Qué prácticas aumentan el riesgo en un glaciar?",
    "q.l34#14.o0" to "Ir demasiado juntos en la cordada",
    "q.l34#14.o1" to "No hacer nudos en la cuerda",
    "q.l34#14.o2" to "Pararse a descansar en la zona de seracs",
    "q.l34#14.o3" to "Avanzar pegado al borde del glaciar",
    "q.l34#14.e" to "Los cuatro aumentan, respectivamente, el riesgo de caída en cadena, de enterramiento profundo, de impacto de hielo y de grieta lateral. Todos son decisiones evitables.",
    "q.l34#15.p" to "¿Qué hay que unificar antes de que la cordada cruce una zona de grietas densas?",
    "q.l34#15.o0" to "Distancia y forma de hacer los nudos",
    "q.l34#15.o1" to "Orden de paso y separación",
    "q.l34#15.o2" to "Criterio ante un puente (sondear, rodear, retroceder)",
    "q.l34#15.o3" to "Quién lleva la mochila más pesada",
    "q.l34#15.e" to "Los tres primeros definen cómo reacciona el grupo ante un imprevisto. Unificar antes es mucho más seguro que discutirlo al borde de la grieta.",
    "q.l34#16.p" to "Ordena el proceso para pasar un puente de nieve dudoso.",
    "q.l34#16.o0" to "Parar y observar color, hundimientos y grietas alrededor",
    "q.l34#16.o1" to "Sondear el espesor del puente con el piolet o la sonda",
    "q.l34#16.o2" to "Confirmar que no se puede rodear, acortar la distancia y pasar de uno en uno",
    "q.l34#16.o3" to "Cuando todos han pasado, el último suelta la protección y se reincorpora",
    "q.l34#16.e" to "El sondeo va antes de que nadie pise. Pasar de uno en uno significa «soportar el peso de una sola persona cada vez», y esa es la decisión clave.",
    "q.l34#17.p" to "Al planificar una etapa glaciar, ¿cuál es el orden correcto?",
    "q.l34#17.o0" to "Estudiar primero el mapa y la distribución de grietas",
    "q.l34#17.o1" to "Fijar la franja horaria de paso por la zona de grietas (madrugada o noche)",
    "q.l34#17.o2" to "Definir el tipo de encordamiento y la distancia",
    "q.l34#17.o3" to "Repasar el tiempo y la temperatura justo antes de salir",
    "q.l34#17.e" to "Primero el terreno, luego el horario, luego la formación y al final el repaso del tiempo. Si se invierte, aparece el clásico «vamos según el plan, pero a la hora equivocada».",
    "q.l34#18.p" to "Si un compañero cae en una grieta, ¿cuál es el orden de las tres primeras acciones?",
    "q.l34#18.o0" to "Frenar de inmediato y mantener la cuerda cargada",
    "q.l34#18.o1" to "Confirmar que la propia posición es segura y montar protección",
    "q.l34#18.o2" to "Pedir al compañero que prepare el sistema de rescate",
    "q.l34#18.o3" to "Ejecutar el protocolo de rescate de cordada",
    "q.l34#18.e" to "Frenar es lo único que no puede esperar; después vienen la protección y el sistema de rescate. El procedimiento detallado está en la lección de autorrescate y rescate de cordada.",
    "q.l34#19.p" to "La distancia habitual en una cordada glaciar es ______–10 m.",
    "q.l34#19.a0" to "8",
    "q.l34#19.e" to "8–10 m es el rango habitual. Se acorta en zona de grietas densas, pero nunca hasta el punto de que uno arrastre a toda la cordada.",
    "q.l34#20.p" to "Para juzgar la resistencia de un puente, además de mirar color y hundimientos, hay que ______ con el piolet.",
    "q.l34#20.a0" to "sondear",
    "q.l34#20.a1" to "probar",
    "q.l34#20.a2" to "tantear",
    "q.l34#20.e" to "El sondeo se hace antes de que nadie suba. Se clava la punta con suavidad y se nota el espesor del manto y si hay hueco debajo.",
    "q.l34#21.p" to "Lo mejor es cruzar la zona de grietas densas por la ______, cuando los puentes están más firmes.",
    "q.l34#21.a0" to "madrugada",
    "q.l34#21.a1" to "mañana temprano",
    "q.l34#21.a2" to "noche",
    "q.l34#21.e" to "El frío endurece y refuerza el puente; con la fusión de la tarde la resistencia cae de forma clara.",
    "q.l34#22.p" to "Relaciona cada tipo de grieta con su ubicación típica.",
    "q.l34#22.l0" to "Grieta transversal",
    "q.l34#22.l1" to "Grieta longitudinal",
    "q.l34#22.l2" to "Grieta diagonal",
    "q.l34#22.l3" to "Serac / zona de seracs",
    "q.l34#22.r0" to "Cambios de pendiente (parte alta, parte baja, resaltes)",
    "q.l34#22.r1" to "Bandas de tracción en los laterales, por roce con el terreno",
    "q.l34#22.r2" to "Donde el glaciar gira o cambia de anchura",
    "q.l34#22.r3" to "Bajo cascadas de hielo abruptas, con alto riesgo de caída de bloques",
    "q.l34#22.e" to "El origen de una grieta es la tracción. Con esto en la cabeza se puede prever dónde se va a romper el terreno en el siguiente tramo.",
    "q.l34#23.p" to "Relaciona cada señal del puente con su tratamiento.",
    "q.l34#23.l0" to "Superficie hundida",
    "q.l34#23.l1" to "Color oscuro o azulado",
    "q.l34#23.l2" to "Grietas radiales",
    "q.l34#23.l3" to "Eco hueco",
    "q.l34#23.r0" to "Bajar la prioridad de paso y buscar rodeo",
    "q.l34#23.r1" to "Indica manto fino: nada de sondearlo uno solo",
    "q.l34#23.r2" to "Estructura ya dañada: prohibido pasar",
    "q.l34#23.r3" to "Retroceder de inmediato y cambiar de itinerario",
    "q.l34#23.e" to "Las cuatro señales van de menor a mayor gravedad. Con cualquiera de ellas, lo primero es pensar en rodear, no en «pasar rápido».",
    "q.l34#24.p" to "Relaciona cada puesto con su función (cordada de tres).",
    "q.l34#24.l0" to "Primero (abre y guía)",
    "q.l34#24.l1" to "En medio",
    "q.l34#24.l2" to "Último",
    "q.l34#24.r0" to "Elegir itinerario y puentes, marcar el ritmo",
    "q.l34#24.r1" to "Atender a los de delante y detrás, transmitir consignas",
    "q.l34#24.r2" to "Recoger cuerda y vigilar la parte trasera y el cabo",
    "q.l34#24.e" to "El reparto de una cordada de tres se aclara antes de salir. El del medio no es «el sitio más seguro», es el eje por el que pasa la información.",
    "q.l34#25.p" to "Alguien propone «dar un pisotón a ver si aguanta» en un puente de nieve. ¿Qué haces?",
    "q.l34#25.o0" to "Pararlo y sondear con el piolet o la sonda, o rodear directamente",
    "q.l34#25.o1" to "Dejarlo, total vamos encordados",
    "q.l34#25.o2" to "Dejar que pase él solo primero",
    "q.l34#25.o3" to "Cruzar corriendo para reducir el tiempo de carga",
    "q.l34#25.e" to "Una persona son decenas de kilos de carga concentrada: un pisotón puede romperlo. Se sondea con herramienta, no con el peso del cuerpo.",
    "q.l34#26.p" to "Sube la temperatura al mediodía y aún faltan dos horas para la zona de grietas. ¿Qué se hace?",
    "q.l34#26.o0" to "Reevaluar: esperar al enfriamiento del atardecer o tomar el itinerario alternativo",
    "q.l34#26.o1" to "Seguir según el plan",
    "q.l34#26.o2" to "Acelerar y cruzar de golpe",
    "q.l34#26.o3" to "Quedarse ahí hasta mañana",
    "q.l34#26.e" to "La resistencia del puente es función del tiempo. El plan se diseña alrededor de «la franja más firme», y no al revés: no se hace que la gente se adapte al plan.",
    "q.l34#27.p" to "¿Por qué la zona de seracs no sirve como punto de espera de la cordada?",
    "q.l34#27.o0" to "El colapso de un serac cae en bloque; esperar alarga el tiempo de exposición",
    "q.l34#27.o1" to "Porque hay mucho viento",
    "q.l34#27.o2" to "Porque el suelo es irregular",
    "q.l34#27.o3" to "Porque no hay cobertura",
    "q.l34#27.e" to "El riesgo de grieta se reparte encordándose; el de caída de hielo solo se reduce con menos tiempo de exposición. Las dos estrategias van en direcciones opuestas.",
    "q.l34#28.p" to "Sobre el ritmo de marcha en glaciar, ¿qué afirmación es correcta?",
    "q.l34#28.o0" to "Paso constante y distancia mantenida es más seguro que alternar acelerones y paradas",
    "q.l34#28.o1" to "Cuanto más rápido, más seguro",
    "q.l34#28.o2" to "Cuanto más lento, más seguro",
    "q.l34#28.o3" to "Que cada uno vaya a su ritmo",
    "q.l34#28.e" to "Alternar ritmos hace que la cuerda se tense y se destense una y otra vez y genera cargas de choque. En glaciar, el ritmo común es seguridad y también eficacia.",
    "q.l34#29.p" to "¿Qué es lo primero que debe practicar alguien que pisa un glaciar por primera vez?",
    "q.l34#29.o0" to "Progresión encordada, control de distancia y posición de frenado, en terreno seguro",
    "q.l34#29.o1" to "Correr más rápido",
    "q.l34#29.o2" to "Cruzar grietas en solitario",
    "q.l34#29.o3" to "Trabajos en altura",
    "q.l34#29.e" to "La posición de frenado y el sentido de la distancia tienen que convertirse en memoria muscular en terreno seguro; si no, al caer de verdad no hay tiempo.",
    // ---------- l35 Enterramiento en alud: ventana de supervivencia y orden en escena ----------
    "q.l35#0.p" to "¿Cuál es la causa principal de muerte en un enterramiento por alud?",
    "q.l35#0.o0" to "Asfixia (65–100 %)",
    "q.l35#0.o1" to "Traumatismo",
    "q.l35#0.o2" to "Hipotermia",
    "q.l35#0.o3" to "Hemorragia",
    "q.l35#0.e" to "Esto decide directamente el orden de actuación: primero la vía aérea y la ventilación, y solo después circulación y recalentamiento.",
    "q.l35#1.p" to "¿Cuáles son aproximadamente las supervivencias de enterramiento completo y parcial según la síntesis de 2023?",
    "q.l35#1.o0" to "Un 48 % y un 96 %",
    "q.l35#1.o1" to "Un 80 % y un 90 %",
    "q.l35#1.o2" to "Un 20 % y un 60 %",
    "q.l35#1.o3" to "Alrededor del 50 % en ambos",
    "q.l35#1.e" to "Los dos valores se diferencian en más del doble: tener la cabeza fuera y estar completamente enterrado son situaciones totalmente distintas.",
    "q.l35#2.p" to "El «periodo de supervivencia» de la curva abarca aproximadamente...",
    "q.l35#2.o0" to "Los primeros 18 minutos",
    "q.l35#2.o1" to "Los primeros 5 minutos",
    "q.l35#2.o2" to "De 18 a 35 minutos",
    "q.l35#2.o3" to "A partir de los 90 minutos",
    "q.l35#2.e" to "En este periodo las muertes se deben sobre todo a traumatismos y la vía aérea suele seguir libre. Por eso se insiste tanto en los 18 minutos.",
    "q.l35#3.p" to "¿Qué caracteriza la curva en la «fase de asfixia»?",
    "q.l35#3.o0" to "La supervivencia cae en picado: es el tramo con la ventana de rescate más ajustada",
    "q.l35#3.o1" to "La curva es plana",
    "q.l35#3.o2" to "La supervivencia vuelve a subir",
    "q.l35#3.o3" to "No tiene relación con el frío",
    "q.l35#3.e" to "La caída brusca entre los 18 y los 35 minutos se debe a la obstrucción de la vía aérea por nieve y al agotamiento del oxígeno de la bolsa de aire. Casi todo el valor del rescate por compañeros está en este tramo.",
    "q.l35#4.p" to "¿Por qué la supervivencia se estabiliza en la «fase de latencia» (35–90 minutos)?",
    "q.l35#4.o0" to "Quien tiene bolsa de aire y vía aérea libre entra en protección por frío y baja el metabolismo",
    "q.l35#4.o1" to "Porque la nieve se derrite",
    "q.l35#4.o2" to "Porque llega el rescate",
    "q.l35#4.o3" to "Porque se recupera el traumatismo",
    "q.l35#4.e" to "Aquí el frío protege en lugar de amenazar. Es la razón de que «mucho tiempo enterrado» no equivalga sin más a «sin oportunidades».",
    "q.l35#5.p" to "¿Qué proporción de las muertes por alud se debe a hipotermia?",
    "q.l35#5.o0" to "0–4 %",
    "q.l35#5.o1" to "20–30 %",
    "q.l35#5.o2" to "50 %",
    "q.l35#5.o3" to "Casi todas",
    "q.l35#5.e" to "Es una proporción baja, pero existen casos. Recuerda que el orden es primero ventilación y después recalentamiento: no se puede invertir.",
    "q.l35#6.p" to "En los primeros 0–2 minutos tras la alud, ¿qué es prioritario?",
    "q.l35#6.o0" to "Confirmar el riesgo de segunda alud, nombrar un vigía y anotar la hora y el último punto donde se le vio",
    "q.l35#6.o1" to "Empezar a palear de inmediato",
    "q.l35#6.o2" to "Hacer fotos",
    "q.l35#6.o3" to "Llamar a la familia",
    "q.l35#6.e" to "Sin vigía, el equipo de rescate puede convertirse en el segundo enterrado; sin registro horario, la regla de los 60 minutos no se puede aplicar.",
    "q.l35#7.p" to "¿Cuál es el objetivo en la fase de 2 a 10 minutos?",
    "q.l35#7.o0" to "Llegar a «tocar a la persona» cuanto antes, no sacar toda la nieve",
    "q.l35#7.o1" to "Abrir un túnel reglamentario",
    "q.l35#7.o2" to "Recoger el material",
    "q.l35#7.o3" to "Esperar al equipo profesional",
    "q.l35#7.e" to "Al tocar la cara ya se puede ventilar, y eso llega varios minutos antes que «sacar del todo». En la fase de asfixia, unos minutos son la diferencia entre vivir y no vivir.",
    "q.l35#8.p" to "En los primeros 60 segundos tras llegar a la cara, ¿cuál es el orden correcto?",
    "q.l35#8.o0" to "Limpiar nieve y hielo de boca y nariz, comprobar signos vitales, y si no respira dar ventilaciones de rescate de inmediato",
    "q.l35#8.o1" to "Sacar el cuerpo primero y limpiar la boca después",
    "q.l35#8.o2" to "Hacer fotos y luego actuar",
    "q.l35#8.o3" to "Dar agua caliente",
    "q.l35#8.e" to "Primero la vía aérea y luego lo demás. Sacar a la persona tirando puede agravar una lesión de columna y además empujar nieve hacia boca y nariz.",
    "q.l35#9.p" to "«25 % de supervivencia a los 45 minutos, por encima del 18 % a los 40», ¿cómo se interpreta?",
    "q.l35#9.o0" to "Es una fluctuación por muestra pequeña y por distinta proporción de casos con bolsa de aire, no un repunte de la curva",
    "q.l35#9.o1" to "Que a los 45 minutos hay más seguridad",
    "q.l35#9.o2" to "Que conviene esperar a los 45 minutos",
    "q.l35#9.o3" to "Que los datos están mal",
    "q.l35#9.e" to "En docencia se enseña la tendencia, no se promete con un punto aislado. Tomar una fluctuación como ley lleva a conclusiones absurdas.",
    "q.l35#10.p" to "Todos los enterrados completos rescatados parecen estar bien. ¿Qué se hace?",
    "q.l35#10.o0" to "Trasladarlos igualmente a un centro sanitario para observación",
    "q.l35#10.o1" to "Volver al campamento",
    "q.l35#10.o2" to "Seguir la actividad del día",
    "q.l35#10.o3" to "Que bajen andando por su cuenta",
    "q.l35#10.e" to "Las consecuencias de la hipoxia y del frío pueden aparecer con retraso. La observación y la valoración necesitan medios y tiempo; en el campamento no se pueden hacer.",
    "q.l35#11.p" to "¿Qué información hay que registrar obligatoriamente en una escena de alud?",
    "q.l35#11.o0" to "Hora del accidente o última hora conocida con certeza",
    "q.l35#11.o1" to "Último punto donde se le vio",
    "q.l35#11.o2" to "Número de personas enterradas",
    "q.l35#11.o3" to "Nombre y apellidos de los rescatadores",
    "q.l35#11.e" to "Los tres primeros determinan la zona de búsqueda y las decisiones médicas. Los nombres son registro posterior y no influyen en la valoración sobre el terreno.",
    "q.l35#12.p" to "Tras el rescate, ¿qué aspectos hay que atender a la vez?",
    "q.l35#12.o0" to "Protección de la columna, evitando movilizaciones bruscas",
    "q.l35#12.o1" to "Calentar todo el cuerpo, retirar ropa mojada y aislar del suelo",
    "q.l35#12.o2" to "Monitorizar de forma continua el ritmo cardíaco y la temperatura central",
    "q.l35#12.o3" to "Pedir a la víctima que se levante y camine",
    "q.l35#12.e" to "Los tres primeros son el tratamiento estándar. Hacer que la víctima se mueva agrava la hipotermia y una posible lesión de columna.",
    "q.l35#13.p" to "¿Qué factores NO deben usarse para decidir si se reanima o no?",
    "q.l35#13.o0" to "La profundidad del enterramiento",
    "q.l35#13.o1" to "La presencia o ausencia de bolsa de aire",
    "q.l35#13.o2" to "La densidad de la nieve",
    "q.l35#13.o3" to "Si la vía aérea está completamente llena",
    "q.l35#13.e" to "Los tres primeros afectan al tiempo de excavación, no a la decisión médica. Solo el estado de la vía aérea, el tiempo y la temperatura entran en el triaje.",
    "q.l35#14.p" to "Ordena los primeros diez minutos en una escena de alud.",
    "q.l35#14.o0" to "Confirmar riesgo de segunda alud y de caída de piedras, y nombrar un vigía",
    "q.l35#14.o1" to "Anotar hora y último punto avistado, y pedir ayuda",
    "q.l35#14.o2" to "Búsqueda con ARVA y localización con sonda",
    "q.l35#14.o3" to "Empezar a palear con el objetivo de llegar a la cara cuanto antes",
    "q.l35#14.e" to "La lógica es «que el rescate no se convierta en un segundo accidente» y después «que las decisiones posteriores tengan base documental».",
    "q.l35#15.p" to "Ordena la actuación después de llegar a la cara.",
    "q.l35#15.o0" to "Limpiar nieve y hielo de boca y nariz y valorar la vía aérea",
    "q.l35#15.o1" to "Comprobar signos vitales en el primer minuto",
    "q.l35#15.o2" to "Si no respira, dar ventilaciones de rescate de inmediato",
    "q.l35#15.o3" to "Aplicar la regla de los 60 minutos y organizar el traslado",
    "q.l35#15.e" to "La ventilación va antes de «sacar del todo» y antes de mover. En la práctica es el punto que más se invierte por error.",
    "q.l35#16.p" to "La causa principal de muerte por alud es la asfixia, con un ______–100 % de los fallecimientos.",
    "q.l35#16.a0" to "65",
    "q.l35#16.e" to "Ese 65–100 % proviene de nueve estudios. Explica por qué «primero ventilar» es una regla de hierro.",
    "q.l35#17.p" to "En la curva de supervivencia se insiste en los «______ minutos de oro», la ventana previa al inicio de la fase de asfixia.",
    "q.l35#17.a0" to "18",
    "q.l35#17.a1" to "dieciocho",
    "q.l35#17.e" to "Los 18 minutos son el punto de caída brusca desde el punto de vista estadístico. No es un número mágico, pero sirve como objetivo de entrenamiento.",
    "q.l35#18.p" to "La hipotermia solo causa el ______–4 % de las muertes por alud.",
    "q.l35#18.a0" to "0",
    "q.l35#18.e" to "0–4 %. Es poco, pero explica los casos aislados de supervivencia tras enterramientos muy prolongados.",
    "q.l35#19.p" to "Relaciona los cuatro tramos de la curva de supervivencia con su característica.",
    "q.l35#19.l0" to "Periodo de supervivencia (0–18 min)",
    "q.l35#19.l1" to "Fase de asfixia (18–35 min)",
    "q.l35#19.l2" to "Fase de latencia (35–90 min)",
    "q.l35#19.l3" to "Fase prolongada (más de 90 min)",
    "q.l35#19.r0" to "Las muertes se deben sobre todo a traumatismos; la vía aérea suele estar libre",
    "q.l35#19.r1" to "La supervivencia cae en picado; ventana de rescate más ajustada",
    "q.l35#19.r2" to "Quien tiene bolsa de aire entra en protección por frío y la curva se aplana",
    "q.l35#19.r3" to "Predomina la hipotermia; hay supervivientes excepcionales tras enterramientos muy largos",
    "q.l35#19.e" to "Cada tramo corresponde a una estructura de causas de muerte. Explicar la curva en cuatro fases es más útil que memorizar porcentajes sueltos.",
    "q.l35#20.p" to "Relaciona cada causa de muerte con su proporción.",
    "q.l35#20.l0" to "Asfixia",
    "q.l35#20.l1" to "Traumatismo",
    "q.l35#20.l2" to "Hipotermia",
    "q.l35#20.r0" to "65–100 %",
    "q.l35#20.r1" to "5–29 %",
    "q.l35#20.r2" to "0–4 %",
    "q.l35#20.e" to "Estas proporciones son el origen de la prioridad de actuación: ventilación, después control de hemorragias e inmovilización, y por último recalentamiento.",
    "q.l35#21.p" to "El equipo empieza a palear sin nombrar vigía. ¿Cuál es el mayor riesgo?",
    "q.l35#21.o0" to "Que una segunda alud entierre también a los rescatadores",
    "q.l35#21.o1" to "Palear despacio",
    "q.l35#21.o2" to "Que falte cuerda",
    "q.l35#21.o3" to "Que no quede registro",
    "q.l35#21.e" to "Rara vez ocurre una sola alud. El vigía es la única persona que puede dar la voz de alto cuando llega la segunda.",
    "q.l35#22.p" to "¿Por qué no se debe «tirar de la persona en cuanto se la toca»?",
    "q.l35#22.o0" to "Puede agravar una lesión de columna y empujar nieve hacia boca y nariz",
    "q.l35#22.o1" to "Se estropea la ropa",
    "q.l35#22.o2" to "Retrasa las fotos",
    "q.l35#22.o3" to "Asusta a la víctima",
    "q.l35#22.e" to "Primero cara y vía aérea, se confirma la posición de cabeza y cuello, y después tórax y cuerpo. Con el orden invertido, se puede rescatar a alguien con una paraplejia.",
    "q.l35#23.p" to "Si estás solo en la escena, ¿paleas o pides ayuda primero?",
    "q.l35#23.o0" to "Palear primero: la ventana de rescate es más corta que cualquier tiempo de respuesta; la señal se intenta después",
    "q.l35#23.o1" to "Llamar por teléfono primero",
    "q.l35#23.o2" to "Volver al campamento a buscar gente",
    "q.l35#23.o3" to "Grabar un vídeo primero",
    "q.l35#23.e" to "Estando solo, esperar al rescate es prácticamente renunciar. El momento de emitir la señal se puede buscar luego; la excavación no espera.",
    "q.l35#24.p" to "¿Por qué el «tiempo de enterramiento» hay que anotarlo con precisión de minutos?",
    "q.l35#24.o0" to "Porque decide qué regla de triaje se aplica en la reanimación",
    "q.l35#24.o1" to "Para el informe",
    "q.l35#24.o2" to "Para el seguro",
    "q.l35#24.o3" to "Para las estadísticas",
    "q.l35#24.e" to "Los 60 minutos son la línea divisoria del triaje, y en la escena a menudo solo se puede deducir de la hora del avistamiento. Perder diez minutos lleva el juicio por otro camino.",
    "q.l35#25.p" to "¿Por qué «estar muy profundo» no equivale a «sin esperanza»?",
    "q.l35#25.o0" to "La profundidad afecta al tiempo de excavación, mientras que la decisión médica mira tiempo, vía aérea y temperatura",
    "q.l35#25.o1" to "Porque la nieve se derrite",
    "q.l35#25.o2" to "Porque hay mucha gente",
    "q.l35#25.o3" to "Porque quien está profundo tiene más frío",
    "q.l35#25.e" to "Usar la profundidad como criterio médico hace que se abandone antes de tiempo. La profundidad solo cambia cuánto tardas en palear, no lo que hay que hacer.",

    // ---------- l36 Reanimación en alud: regla de 60 minutos y vía aérea ----------
    "q.l36#0.p" to "¿Cuál es la línea de decisión temporal del ICAR MedCom en su versión de 2023?",
    "q.l36#0.o0" to "60 minutos",
    "q.l36#0.o1" to "35 minutos",
    "q.l36#0.o2" to "90 minutos",
    "q.l36#0.o3" to "120 minutos",
    "q.l36#0.e" to "La versión de 2013 usaba 35 minutos y en 2023 se actualizó a 60. Al escribir material hay que indicar año y criterio.",
    "q.l36#1.p" to "Enterrado 25 minutos, sin signos vitales y vía aérea parcialmente obstruida por nieve suelta (no llena del todo). ¿Qué se hace?",
    "q.l36#1.o0" to "Tratar como asfixia: limpiar boca y nariz, dar ventilaciones cuanto antes y empezar compresiones",
    "q.l36#1.o1" to "Tratar como obstrucción y no reanimar",
    "q.l36#1.o2" to "Recalentar primero",
    "q.l36#1.o3" to "Esperar al equipo profesional",
    "q.l36#1.e" to "Hasta 60 minutos se trata siempre como asfixia, esté la vía aérea libre o no. Nieve suelta no es obstrucción: la obstrucción exige que esté completamente llena.",
    "q.l36#2.p" to "Enterrado 70 minutos, sin signos vitales, vía aérea libre y sin posibilidad de medir temperatura central. ¿Qué se hace?",
    "q.l36#2.o0" to "Tratar como parada cardíaca por hipotermia: iniciar reanimación y trasladar",
    "q.l36#2.o1" to "Tratar como asfixia y no reanimar",
    "q.l36#2.o2" to "Esperar a medir la temperatura",
    "q.l36#2.o3" to "Solo abrigar",
    "q.l36#2.e" to "Vía aérea libre más más de 60 minutos implica una probabilidad de parada hipotérmica suficientemente alta: hay que reanimar. Con un corazón frío, «no está muerto hasta que no se calienta».",
    "q.l36#3.p" to "Enterrado 70 minutos, sin signos vitales, boca y nariz completamente llenas de nieve compacta y sin termómetro en el lugar. ¿Qué se hace?",
    "q.l36#3.o0" to "Tratar como parada por asfixia: no iniciar reanimación",
    "q.l36#3.o1" to "Empezar compresiones de inmediato",
    "q.l36#3.o2" to "Desenterrar del todo antes de decidir",
    "q.l36#3.o3" to "Dar dos ventilaciones y abandonar",
    "q.l36#3.e" to "Es uno de los supuestos en los que la versión de 2023 permite no iniciar la reanimación. Si se puede medir y la temperatura es inferior a 30 °C, entonces se intenta reanimar.",
    "q.l36#4.p" to "Temperatura central de 28 °C, vía aérea libre, sin signos vitales, 80 minutos enterrado. ¿Qué se hace?",
    "q.l36#4.o0" to "Intentar reanimar y trasladar a un hospital con capacidad de recalentamiento por circulación extracorpórea",
    "q.l36#4.o1" to "Suspender la reanimación",
    "q.l36#4.o2" to "Solo abrigar",
    "q.l36#4.o3" to "Esperar a que suba la temperatura",
    "q.l36#4.e" to "Menos de 30 °C con vía aérea libre exige intentar la reanimación sin importar el tiempo de enterramiento. Estos pacientes necesitan condiciones de recalentamiento de nivel ECLS.",
    "q.l36#5.p" to "¿Cómo se define «obstrucción de la vía aérea» en el rescate de alud?",
    "q.l36#5.o0" to "Boca y nariz completamente llenas de nieve compacta o de detritos",
    "q.l36#5.o1" to "Tener algo de nieve en la boca",
    "q.l36#5.o2" to "Tener flemas",
    "q.l36#5.o3" to "Sangrar por la nariz",
    "q.l36#5.e" to "La definición tiene que ser estricta porque decide si se inicia la reanimación. En caso de duda se considera libre: es el valor por defecto que favorece salvar a la persona.",
    "q.l36#6.p" to "Sobre la bolsa de aire, ¿qué afirmación es correcta?",
    "q.l36#6.o0" to "Con bolsa de aire la supervivencia es mayor, pero no es un criterio para decidir si se reanima",
    "q.l36#6.o1" to "Sin bolsa de aire no se reanima",
    "q.l36#6.o2" to "Con bolsa de aire siempre se sobrevive",
    "q.l36#6.o3" to "La bolsa de aire define si hay obstrucción",
    "q.l36#6.e" to "La versión de 2023 lo deja claro: ni la bolsa de aire, ni la densidad de la nieve, ni la profundidad cambian la actuación. Influyen en el tiempo, no en la decisión.",
    "q.l36#7.p" to "¿Cuándo se pueden empezar las compresiones torácicas?",
    "q.l36#7.o0" to "Sin esperar a desenterrar del todo: basta con tener el tórax libre",
    "q.l36#7.o1" to "Solo cuando el cuerpo esté completamente fuera",
    "q.l36#7.o2" to "Solo al llegar al hospital",
    "q.l36#7.o3" to "Solo tras medir la temperatura",
    "q.l36#7.e" to "«Esperar a sacarlo del todo para comprimir» pierde minutos valiosos. La versión de 2023 confirma que también son eficaces con posturas anómalas y con el cuerpo aún en la nieve.",
    "q.l36#8.p" to "¿Por qué hay que dar ventilaciones de rescate cuanto antes?",
    "q.l36#8.o0" to "Porque la mayoría de estas víctimas muere por asfixia y la hipoxia es el primer problema",
    "q.l36#8.o1" to "Porque resulta más cómodo",
    "q.l36#8.o2" to "Para tranquilizar a la familia",
    "q.l36#8.o3" to "Para ahorrar oxígeno",
    "q.l36#8.e" to "Primero ventilar y después hablar de circulación. Es la base fisiológica de la regla «hasta 60 minutos, sin importar la vía aérea».",
    "q.l36#9.p" to "¿Qué criterios suelen indicar el cese de la reanimación?",
    "q.l36#9.o0" to "Lesión mortal, congelación completa, obstrucción de la vía aérea con más de 60 minutos y potasio muy elevado",
    "q.l36#9.o1" to "Que la familia lo pida",
    "q.l36#9.o2" to "Que anochezca",
    "q.l36#9.o3" to "Que falte material",
    "q.l36#9.e" to "Provienen de la versión de 2023 y de las recomendaciones del ICAR sobre terminación de la reanimación. Decide personal entrenado, no quien palea.",
    "q.l36#10.p" to "¿Dónde falla la frase «primero mira cuánto está enterrado y luego decide si se rescata»?",
    "q.l36#10.o0" to "La profundidad afecta al tiempo de excavación, no entra en la decisión médica",
    "q.l36#10.o1" to "La profundidad no se puede medir",
    "q.l36#10.o2" to "La profundidad siempre es poca",
    "q.l36#10.o3" to "La profundidad determina la supervivencia",
    "q.l36#10.e" to "Convertir un problema de ingeniería en criterio médico hace que se abandone antes de tiempo. La decisión solo mira tiempo, vía aérea y temperatura.",
    "q.l36#11.p" to "Según la versión de 2023, ¿qué factores entran en el triaje?",
    "q.l36#11.o0" to "El tiempo de enterramiento",
    "q.l36#11.o1" to "Si la vía aérea está libre",
    "q.l36#11.o2" to "Si se puede medir la temperatura central y su valor",
    "q.l36#11.o3" to "La profundidad del enterramiento",
    "q.l36#11.e" to "Los tres primeros forman el árbol de decisión. El cuarto solo dice cuánto hay que palear y no cambia el triaje.",
    "q.l36#12.p" to "¿Qué incluye el manejo de una parada cardíaca por hipotermia?",
    "q.l36#12.o0" to "Movilización suave, evitando sacudidas bruscas",
    "q.l36#12.o1" to "Aislamiento y calentamiento de todo el cuerpo",
    "q.l36#12.o2" to "Monitorización continua del ritmo y de la temperatura central",
    "q.l36#12.o3" to "Recalentar en el lugar hasta 35 °C antes de trasladar",
    "q.l36#12.e" to "En el lugar no se consigue un recalentamiento eficaz, y empeñarse en «calentar antes de mover» retrasa lo importante. El objetivo es llegar cuanto antes a un centro con ECLS.",
    "q.l36#13.p" to "Sobre la vía aérea y la ventilación, ¿qué actuaciones son correctas?",
    "q.l36#13.o0" to "Limpiar la nieve y el hielo de boca y nariz",
    "q.l36#13.o1" to "Si hay duda sobre la obstrucción, considerarla libre",
    "q.l36#13.o2" to "Ventilar antes de plantear las compresiones",
    "q.l36#13.o3" to "Evaluar la vía aérea cuando esté completamente desenterrado",
    "q.l36#13.e" to "Las tres primeras apuntan a «ventilar cuanto antes». La última retrasa los minutos más críticos.",
    "q.l36#14.p" to "Ordena la actuación en el caso «hasta 60 minutos, sin signos vitales».",
    "q.l36#14.o0" to "Limpiar boca y nariz y valorar la vía aérea",
    "q.l36#14.o1" to "Dar ventilaciones de rescate de inmediato",
    "q.l36#14.o2" to "Iniciar compresiones torácicas",
    "q.l36#14.o3" to "Abrigar, proteger la columna y organizar el traslado",
    "q.l36#14.e" to "La ventilación va antes que la compresión: es la gran diferencia entre una parada por asfixia en alud y una parada cardíaca habitual.",
    "q.l36#15.p" to "Ordena el proceso de triaje en el caso «más de 60 minutos».",
    "q.l36#15.o0" to "Confirmar que el tiempo de enterramiento supera realmente los 60 minutos",
    "q.l36#15.o1" to "Valorar si la vía aérea está completamente llena",
    "q.l36#15.o2" to "Intentar medir la temperatura central",
    "q.l36#15.o3" to "Decidir si se inicia la reanimación según la rama correspondiente",
    "q.l36#15.e" to "El orden refleja «primero tiempo, luego vía aérea, por último temperatura». Si falta información en cualquiera de los tres pasos, se aplica la rama que más favorece salvar a la persona.",
    "q.l36#16.p" to "La línea de decisión de reanimación del ICAR MedCom 2023 es de ______ minutos de enterramiento.",
    "q.l36#16.a0" to "60",
    "q.l36#16.e" to "Los 35 minutos de la versión anterior están derogados. Materiales y banco de preguntas deben unificarse en 60 minutos.",
    "q.l36#17.p" to "Con temperatura central por debajo de ______ °C y vía aérea libre, hay que intentar reanimar sin importar el tiempo de enterramiento.",
    "q.l36#17.a0" to "30",
    "q.l36#17.e" to "30 °C es un criterio paralelo: incorpora a la decisión la ventana de protección por frío.",
    "q.l36#18.p" to "La hipotermia solo causa el 0–4 % de las muertes por alud, así que el orden es primero ______ y después recalentar.",
    "q.l36#18.a0" to "ventilar",
    "q.l36#18.a1" to "la vía aérea",
    "q.l36#18.a2" to "asegurar la vía aérea",
    "q.l36#18.e" to "Primero ventilar y después recalentar: en el rescate de alud este orden es aún más estricto que en la hipotermia convencional.",
    "q.l36#19.p" to "Relaciona cada situación de enterramiento con su actuación (versión 2023).",
    "q.l36#19.l0" to "Hasta 60 minutos, sin signos vitales",
    "q.l36#19.l1" to "Más de 60 minutos, vía aérea libre, sin termómetro",
    "q.l36#19.l2" to "Más de 60 minutos, vía aérea obstruida, sin termómetro",
    "q.l36#19.l3" to "Temperatura medible inferior a 30 °C, vía aérea libre",
    "q.l36#19.r0" to "Tratar como asfixia y dar ventilaciones cuanto antes",
    "q.l36#19.r1" to "Tratar como parada hipotérmica e iniciar reanimación",
    "q.l36#19.r2" to "Tratar como parada por asfixia y no iniciar reanimación",
    "q.l36#19.r3" to "Intentar reanimar sin importar el tiempo y trasladar a ECLS",
    "q.l36#19.e" to "Estas cuatro ramas cubren la gran mayoría de las situaciones reales. Recordar las condiciones de cada rama es más fiable que memorizar la conclusión.",
    "q.l36#20.p" to "Relaciona cada criterio de «se puede suspender la reanimación» con su significado.",
    "q.l36#20.l0" to "Lesión mortal",
    "q.l36#20.l1" to "Congelación completa",
    "q.l36#20.l2" to "Vía aérea obstruida y más de 60 minutos",
    "q.l36#20.l3" to "Potasio muy elevado",
    "q.l36#20.r0" to "La lesión en sí es irreversible",
    "q.l36#20.r1" to "El cuerpo está congelado y recalentar no tiene sentido",
    "q.l36#20.r2" to "Se trata como parada por asfixia y no se inicia reanimación",
    "q.l36#20.r3" to "Indica hipoxia prolongada y pronóstico muy desfavorable",
    "q.l36#20.e" to "Los cuatro son evidencias de que ya no hay posibilidad de revertir la situación. La decisión corresponde a personal entrenado y debe quedar registrada con su fundamento.",
    "q.l36#21.p" to "Alguien sostiene que «pasados 35 minutos ya no se reanima». ¿Qué le respondes?",
    "q.l36#21.o0" to "Ese es el criterio de 2013; en 2023 pasó a 60 minutos y se añadió la temperatura",
    "q.l36#21.o1" to "Tiene razón",
    "q.l36#21.o2" to "Depende",
    "q.l36#21.o3" to "Que lo decida él",
    "q.l36#21.e" to "En materiales en castellano los 35 minutos siguen apareciendo mucho. Actualizar el criterio es uno de los valores más prácticos de este tipo de formación.",
    "q.l36#22.p" to "Caso: 20 minutos enterrado, sin respiración al desenterrarlo, nieve suelta en boca y nariz pero sin llenarla del todo. ¿Qué se hace?",
    "q.l36#22.o0" to "Limpiar boca y nariz, dar ventilaciones, iniciar compresiones y trasladar cuanto antes",
    "q.l36#22.o1" to "Considerarlo obstrucción y no reanimar",
    "q.l36#22.o2" to "Recalentar primero",
    "q.l36#22.o3" to "Esperar a que lo valore el equipo profesional",
    "q.l36#22.e" to "Hasta 60 minutos más obstrucción no completa equivale a asfixia: reanimación a fondo. La nieve suelta no constituye obstrucción.",
    "q.l36#23.p" to "Caso: 70 minutos enterrado, vía aérea libre, temperatura central 28 °C, sin signos vitales. ¿Qué se hace?",
    "q.l36#23.o0" to "Reanimación continua, movilización suave, abrigar todo el cuerpo y trasladar a un hospital con capacidad de ECLS",
    "q.l36#23.o1" to "Suspender la reanimación",
    "q.l36#23.o2" to "Solo abrigar y observar",
    "q.l36#23.o3" to "Recalentar hasta 35 °C antes de trasladar",
    "q.l36#23.e" to "En una parada hipotérmica lo esencial es «llegar a un lugar donde puedan recalentar», y la reanimación no se interrumpe durante el traslado.",
    "q.l36#24.p" to "¿Por qué se dice que «el corazón frío es muy sensible»?",
    "q.l36#24.o0" to "Una movilización brusca puede desencadenar fibrilación ventricular, así que hay que mover suave y en horizontal",
    "q.l36#24.o1" to "Porque tiene frío",
    "q.l36#24.o2" to "Porque la frecuencia cardíaca es baja",
    "q.l36#24.o3" to "Porque la tensión es baja",
    "q.l36#24.e" to "Es la razón de mover «plano, estable y suave» a un paciente hipotérmico, y una segunda razón, además de la protección de la columna, que se repite en el rescate de alud.",
    "q.l36#25.p" to "Un miembro del equipo se derrumba emocionalmente durante el rescate y exige suspender la reanimación. ¿Qué hace el jefe de cordada?",
    "q.l36#25.o0" to "Retirarlo de la maniobra pero continuar la reanimación: decide personal entrenado según los criterios",
    "q.l36#25.o1" to "Suspender de inmediato",
    "q.l36#25.o2" to "Reprenderlo",
    "q.l36#25.o3" to "Dejarlo comprimiendo",
    "q.l36#25.e" to "La emoción hay que atenderla, pero la decisión médica no puede depender de ella. Cambiar a la persona en lugar de parar es lo más responsable.",
    // ---------- l37 El trío: búsqueda con ARVA y sondeo puntual ----------
    "q.l37#0.p" to "¿Cuál es el orden de las cuatro fases de una búsqueda en alud?",
    "q.l37#0.o0" to "Búsqueda de señal e indicios, búsqueda gruesa, búsqueda fina, sondeo puntual",
    "q.l37#0.o1" to "Búsqueda gruesa, búsqueda fina, sondeo puntual, búsqueda de señal",
    "q.l37#0.o2" to "Sondeo puntual, búsqueda fina, búsqueda gruesa",
    "q.l37#0.o3" to "Búsqueda, excavación, sondeo",
    "q.l37#0.e" to "Las cuatro fases son un proceso de convergencia: de toda la ladera, a unos metros, a un punto de la superficie, a una profundidad concreta. Saltarse una hace perder tiempo.",
    "q.l37#1.p" to "¿Qué separación se deja normalmente entre bandas de búsqueda con ARVA?",
    "q.l37#1.o0" to "Unos 40 m, y unos 20 m hasta el borde del depósito",
    "q.l37#1.o1" to "10 m",
    "q.l37#1.o2" to "80 m",
    "q.l37#1.o3" to "Cuanto más ancha, mejor",
    "q.l37#1.e" to "40 m es el valor por defecto en docencia, no el límite del equipo. Si el nivel de entrenamiento es dudoso, se baja a 30 m: mejor dar más pasadas.",
    "q.l37#2.p" to "Antes de empezar la búsqueda, ¿qué es lo más importante para todo el equipo?",
    "q.l37#2.o0" to "Poner todos los ARVA en modo recepción y apagar móviles y cámaras",
    "q.l37#2.o1" to "Abrir una calicata de prueba",
    "q.l37#2.o2" to "Hacer fotos",
    "q.l37#2.o3" to "Recoger las cuerdas",
    "q.l37#2.e" to "Si alguien sigue en modo emisión, la búsqueda no funciona; y la interferencia de aparatos electrónicos reduce la distancia eficaz. Ambas cosas se resuelven en el primer paso.",
    "q.l37#3.p" to "En la fase de búsqueda de señal, ¿qué se mira primero?",
    "q.l37#3.o0" to "Los indicios visibles en la superficie (guantes, puntas de bastón, cintas de mochila)",
    "q.l37#3.o1" to "La lectura del ARVA",
    "q.l37#3.o2" to "La estructura del manto",
    "q.l37#3.o3" to "La dirección del viento",
    "q.l37#3.e" to "Un indicio en superficie puede reducir la zona a unas decenas de metros. Bajar la cabeza al ARVA hace que se pasen por alto.",
    "q.l37#4.p" to "¿A qué distancia hay que reducir en la fase de búsqueda gruesa?",
    "q.l37#4.o0" to "3–5 m",
    "q.l37#4.o1" to "20 m",
    "q.l37#4.o2" to "0,5 m",
    "q.l37#4.o3" to "10–15 m",
    "q.l37#4.e" to "Solo por debajo de 3–5 m se pasa a la búsqueda fina. Es el punto en el que se pasa de correr a caminar y empieza a importar la precisión.",
    "q.l37#5.p" to "En la búsqueda gruesa, la lectura de distancia aumenta. ¿Qué significa?",
    "q.l37#5.o0" to "Que se va en dirección contraria: hay que volver por donde se vino",
    "q.l37#5.o1" to "Que la señal es muy fuerte",
    "q.l37#5.o2" to "Que el aparato está averiado",
    "q.l37#5.o3" to "Que la persona enterrada se ha movido",
    "q.l37#5.e" to "La lectura del ARVA es distancia: si sube, el rumbo es erróneo. Esta decisión hay que tomarla rápido, sin quedarse confirmando en el sitio.",
    "q.l37#6.p" to "¿Cuál es la maniobra correcta en la fase de búsqueda fina?",
    "q.l37#6.o0" to "Pegar el ARVA a la superficie, hacer cruces y buscar el punto de lectura mínima, marcándolo",
    "q.l37#6.o1" to "Girar de pie sobre uno mismo",
    "q.l37#6.o2" to "Bajar en línea recta pendiente abajo",
    "q.l37#6.o3" to "Clavar la sonda al azar",
    "q.l37#6.e" to "Acercar el aparato al suelo reduce el error por refracción en la nieve. Marcar el mínimo da a la sonda un punto de partida claro.",
    "q.l37#7.p" to "En el sondeo puntual, ¿respecto a qué hay que mantener 90 grados?",
    "q.l37#7.o0" to "Respecto a la superficie de la nieve (la pendiente)",
    "q.l37#7.o1" to "Respecto a la horizontal",
    "q.l37#7.o2" to "Respecto a la pendiente, 45 grados",
    "q.l37#7.o3" to "Da igual el ángulo",
    "q.l37#7.e" to "«Vertical hacia abajo» en una pendiente hace que la sonda atraviese el manto en diagonal y que la profundidad se amplifique por el ángulo. En rescate por compañeros se sondea a 90 grados de la superficie.",
    "q.l37#8.p" to "Si no se toca nada en el primer intento, ¿qué se hace?",
    "q.l37#8.o0" to "Ampliar hacia fuera con una cuadrícula de 25 cm de lado",
    "q.l37#8.o1" to "Cambiar a una sonda más larga",
    "q.l37#8.o2" to "Empezar a palear directamente",
    "q.l37#8.o3" to "Abandonar ese punto",
    "q.l37#8.e" to "25 cm (unas 10 pulgadas) es la cuadrícula estándar. Demasiado grande deja huecos; demasiado pequeña pierde tiempo.",
    "q.l37#9.p" to "Tras notar un objeto duro, ¿cómo se distingue si es una persona?",
    "q.l37#9.o0" to "Buscando una resistencia blanda y elástica, como un cuerpo, y comparando la profundidad con el terreno alrededor",
    "q.l37#9.o1" to "Si está duro, se palea",
    "q.l37#9.o2" to "Mirando si la sonda trae sangre",
    "q.l37#9.o3" to "Escuchando",
    "q.l37#9.e" to "La roca y el hielo dan una resistencia dura y quebradiza; un cuerpo es elástico. Además, la persona enterrada no suele estar más profunda que el terreno que la rodea.",
    "q.l37#10.p" to "Cuando se ha localizado, ¿qué se hace con la sonda?",
    "q.l37#10.o0" to "Dejarla clavada como marca de posición y profundidad",
    "q.l37#10.o1" to "Sacarla de inmediato",
    "q.l37#10.o2" to "Clavarla más",
    "q.l37#10.o3" to "Pasársela a un compañero",
    "q.l37#10.e" to "La sonda que queda clavada es la diana para quien palea y la referencia para saber si se está excavando en el sitio correcto.",
    "q.l37#11.p" to "Si la profundidad supera la longitud de la sonda, ¿qué se hace?",
    "q.l37#11.o0" to "Quitar primero alrededor de 1 m, volver a localizar con el ARVA y sondear de nuevo",
    "q.l37#11.o1" to "Seguir empujando con fuerza",
    "q.l37#11.o2" to "Abandonar",
    "q.l37#11.o3" to "Cambiar de persona",
    "q.l37#11.e" to "Empujar no sirve si no se llega al fondo. Acortar la distancia y volver a localizar es el único procedimiento eficaz.",
    "q.l37#12.p" to "¿Por qué en el rescate organizado la sonda se mantiene vertical y no perpendicular a la superficie?",
    "q.l37#12.o0" to "Para que las lecturas de profundidad de todos los rescatadores sean comparables y se forme un plano de sondeo coherente",
    "q.l37#12.o1" to "Porque cansa menos",
    "q.l37#12.o2" to "Porque es más rápido",
    "q.l37#12.o3" to "Porque la norma lo exige",
    "q.l37#12.e" to "Una línea de sondeo organizada es un «plano» y necesita datos de profundidad comparables. El rescate por compañeros apunta a un solo punto, así que la perpendicular a la nieve es más precisa.",
    "q.l37#13.p" to "¿Qué incluye la revisión del ARVA antes de salir?",
    "q.l37#13.o0" to "Batería suficiente",
    "q.l37#13.o1" to "Hacer una prueba de emisión",
    "q.l37#13.o2" to "Saber pasar a recepción, marcar y silenciar",
    "q.l37#13.o3" to "Llevarlo pegado al cuerpo, no en el fondo de la mochila",
    "q.l37#13.e" to "Si falta uno de los cuatro, fallará en el momento crítico. El error más común es llevarlo en el fondo: si la mochila se entierra o se suelta, el ARVA se va con ella.",
    "q.l37#14.p" to "¿Qué hay que revisar en la sonda?",
    "q.l37#14.o0" to "Longitud adecuada al espesor de nieve local",
    "q.l37#14.o1" to "Cordino y cierre en buen estado",
    "q.l37#14.o2" to "Que se despliegue y bloquee con una mano",
    "q.l37#14.o3" to "Que pese lo mínimo",
    "q.l37#14.e" to "Para equipos de rescate se recomienda al menos 3 m (UIAA 157); en uso personal lo habitual es 240–320 cm. Ligera está bien, pero mandan la resistencia y la fiabilidad del bloqueo.",
    "q.l37#15.p" to "Cuando hay varias personas enterradas, ¿qué actuaciones son correctas?",
    "q.l37#15.o0" to "Marcar o silenciar la primera señal",
    "q.l37#15.o1" to "Buscar después la segunda señal",
    "q.l37#15.o2" to "No quedarse confirmando una señal abandonando el resto de la zona",
    "q.l37#15.o3" to "Rescatar solo al más cercano",
    "q.l37#15.e" to "Con varios enterrados, el mayor riesgo es «encontrar solo a uno». Las funciones de marcado y silenciado existen precisamente para esto.",
    "q.l37#16.p" to "Ordena una búsqueda completa.",
    "q.l37#16.o0" to "Todo el equipo a recepción y apagar fuentes de interferencia",
    "q.l37#16.o1" to "Recorrer las bandas buscando señal",
    "q.l37#16.o2" to "Búsqueda gruesa hasta 3–5 m",
    "q.l37#16.o3" to "Búsqueda fina para hallar el punto de lectura mínima y marcarlo",
    "q.l37#16.o4" to "Sondeo puntual y dejar la sonda clavada",
    "q.l37#16.e" to "Los cinco pasos van de la «superficie» al «punto». Cualquier paso que se quiera ahorrar se paga doble en el siguiente.",
    "q.l37#17.p" to "Ordena el sondeo puntual.",
    "q.l37#17.o0" to "Empezar en el punto de lectura mínima, con la sonda a 90 grados de la superficie",
    "q.l37#17.o1" to "Si no se toca, ampliar con cuadrícula de 25 cm",
    "q.l37#17.o2" to "Parar al notar una resistencia elástica",
    "q.l37#17.o3" to "Dejar la sonda clavada y empezar a palear",
    "q.l37#17.e" to "El error más habitual está en el último paso: muchos sacan la sonda al tocar y la excavación se queda sin referencia.",
    "q.l37#18.p" to "La separación entre bandas de búsqueda con ARVA es de unos ______ m.",
    "q.l37#18.a0" to "40",
    "q.l37#18.e" to "En caso de duda se baja a 30 m. Una banda demasiado ancha deja escapar la señal, y es la causa más frecuente de búsqueda fallida.",
    "q.l37#19.p" to "El lado de la cuadrícula en el sondeo puntual es de ______ cm.",
    "q.l37#19.a0" to "25",
    "q.l37#19.e" to "Unas 10 pulgadas. Una cuadrícula grande deja pasar el cuerpo; una muy pequeña hace perder tiempo.",
    "q.l37#20.p" to "En el rescate por compañeros, la sonda se clava a 90 grados respecto a la ______.",
    "q.l37#20.a0" to "superficie de la nieve",
    "q.l37#20.a1" to "pendiente",
    "q.l37#20.e" to "Perpendicular a la horizontal, la lectura de profundidad se amplifica por el ángulo de la pendiente: es el error geométrico más habitual en principiantes.",
    "q.l37#21.p" to "Relaciona cada fase de la búsqueda con su objetivo.",
    "q.l37#21.l0" to "Búsqueda de señal e indicios",
    "q.l37#21.l1" to "Búsqueda gruesa",
    "q.l37#21.l2" to "Búsqueda fina",
    "q.l37#21.l3" to "Sondeo puntual",
    "q.l37#21.r0" to "Encontrar la primera señal",
    "q.l37#21.r1" to "Reducir la distancia a 3–5 m",
    "q.l37#21.r2" to "Encontrar en la superficie el punto más cercano a la persona enterrada",
    "q.l37#21.r3" to "Confirmar posición y profundidad con la sonda",
    "q.l37#21.e" to "Los cuatro objetivos convergen paso a paso. Recordar el objetivo se adapta mejor a terrenos distintos que recordar la maniobra.",
    "q.l37#22.p" to "Relaciona cada equipo con su requisito clave.",
    "q.l37#22.l0" to "ARVA",
    "q.l37#22.l1" to "Sonda",
    "q.l37#22.l2" to "Pala",
    "q.l37#22.l3" to "Casco",
    "q.l37#22.r0" to "Digital de tres antenas, pegado al cuerpo, con marcado y silenciado",
    "q.l37#22.r1" to "Longitud acorde al espesor de nieve, bloqueo con una mano",
    "q.l37#22.r2" to "Hoja metálica, mango fiable, extracción rápida",
    "q.l37#22.r3" to "Puesto durante toda la búsqueda y la excavación",
    "q.l37#22.e" to "De los cuatro, el que más se olvida es el casco: durante la excavación siguen cayendo bloques de nieve y trozos de hielo desde arriba.",
    "q.l37#23.p" to "Durante la búsqueda, alguien se queda confirmando una y otra vez la primera señal. ¿Qué haces?",
    "q.l37#23.o0" to "Recordarle que marque o silencie y siga cubriendo el resto de la zona",
    "q.l37#23.o1" to "Dejarle",
    "q.l37#23.o2" to "Pararse todos con él",
    "q.l37#23.o3" to "Abandonar la búsqueda",
    "q.l37#23.e" to "Con varios enterrados, «encontrar todas las señales primero» importa más que «confirmar un punto hasta el extremo».",
    "q.l37#24.p" to "¿Por qué se pide apagar móviles y cámaras durante la búsqueda?",
    "q.l37#24.o0" to "Los aparatos electrónicos interfieren en la señal del ARVA y reducen la distancia eficaz",
    "q.l37#24.o1" to "Para ahorrar batería",
    "q.l37#24.o2" to "Para hacer silencio",
    "q.l37#24.o3" to "Para evitar fotos",
    "q.l37#24.e" to "La interferencia reduce el ancho eficaz de la banda y provoca búsquedas incompletas sin que nadie lo note. Es lo que más se descuida en la práctica.",
    "q.l37#25.p" to "Sois solo dos: uno busca y otro palea. ¿Es un reparto razonable?",
    "q.l37#25.o0" to "Sí, pero al localizar deben relevarse en la excavación en lugar de que uno cave solo",
    "q.l37#25.o1" to "No: deben buscar los dos juntos",
    "q.l37#25.o2" to "No: deben esperar al rescate",
    "q.l37#25.o3" to "Sí, y no hace falta relevarse",
    "q.l37#25.e" to "La clave en una pareja es «localizar y relevarse». Una sola persona cavando se agota en pocos minutos y el rendimiento cae.",
    "q.l37#26.p" to "Antes de buscar se ve nieve suspendida sobre la zona del depósito. ¿Qué se hace?",
    "q.l37#26.o0" to "Nombrar primero un vigía y elegir una vía de aproximación segura, y después empezar",
    "q.l37#26.o1" to "Entrar corriendo",
    "q.l37#26.o2" to "Esperar a que deje de nevar",
    "q.l37#26.o3" to "Abandonar la búsqueda",
    "q.l37#26.e" to "Que una segunda alud entierre a los rescatadores es un tipo de accidente real. El vigía y la vía de aproximación forman parte de la búsqueda, no son un extra.",
    "q.l37#27.p" to "¿Qué sentido tienen los objetivos «contacto en 10 minutos, desenterrado en 18»?",
    "q.l37#27.o0" to "Son indicadores internos del equipo para entrenar y revisar, no una garantía",
    "q.l37#27.o1" to "Son un compromiso médico",
    "q.l37#27.o2" to "Son una exigencia normativa",
    "q.l37#27.o3" to "Son una prestación del equipo",
    "q.l37#27.e" to "Su función es que el equipo sepa en qué paso va lento. Tomarlos como promesa hace perder criterio cuando no se cumplen.",

    // ---------- l38 Excavación y cinta transportadora de nieve ----------
    "q.l38#0.p" to "¿Cuál es el primer principio de la excavación?",
    "q.l38#0.o0" to "Trabajar siempre desde el lado de abajo",
    "q.l38#0.o1" to "Cavar desde arriba, en vertical",
    "q.l38#0.o2" to "Cavar desde el lado de arriba hacia abajo",
    "q.l38#0.o3" to "Cavar en horizontal desde el costado",
    "q.l38#0.e" to "Trabajar desde abajo tiene tres ventajas: la nieve se puede lanzar hacia abajo, el canal tiene pendiente y quien palea no está encima de la víctima.",
    "q.l38#1.p" to "La regla tradicional de «1,5 veces la profundidad» describe...",
    "q.l38#1.o0" to "La distancia a la que se retrocede pendiente abajo desde la sonda",
    "q.l38#1.o1" to "El ancho del canal",
    "q.l38#1.o2" to "La longitud de la sonda",
    "q.l38#1.o3" to "El tiempo de excavación",
    "q.l38#1.e" to "Retroceder sirve para dejar espacio donde evacuar la nieve. Es una regla empírica y la investigación reciente ofrece una alternativa.",
    "q.l38#2.p" to "¿Qué propone el estudio de 2023 sobre la cinta transportadora de nieve respecto al punto de inicio?",
    "q.l38#2.o0" to "Con tres o más personas y espacio suficiente, cavar directamente desde la sonda siguiendo la línea de máxima pendiente",
    "q.l38#2.o1" to "Retroceder siempre 1,5 veces la profundidad",
    "q.l38#2.o2" to "Cavar desde arriba en vertical",
    "q.l38#2.o3" to "Cavar en horizontal desde el costado",
    "q.l38#2.e" to "Desplazar el inicio retrasa la llegada a la cabeza. La conclusión del estudio presupone «manos suficientes» y no se aplica sin condiciones.",
    "q.l38#3.p" to "¿En qué casos se recomienda desplazar el punto de inicio?",
    "q.l38#3.o0" to "Cuando el enterramiento es muy somero y los pies están casi a esa misma profundidad, o cuando falta gente y hay que usar un plan individual",
    "q.l38#3.o1" to "En cualquier caso",
    "q.l38#3.o2" to "Cuando la nieve está muy dura",
    "q.l38#3.o3" to "Cuando ya es de noche",
    "q.l38#3.e" to "En esos dos supuestos, desplazarse reduce el transporte inútil. En los demás, empezar en la sonda es más rápido.",
    "q.l38#4.p" to "¿Qué anchura tiene normalmente el canal de la cinta transportadora?",
    "q.l38#4.o0" to "1–2 m",
    "q.l38#4.o1" to "0,3 m",
    "q.l38#4.o2" to "3–4 m",
    "q.l38#4.o3" to "Cuanto más estrecho, mejor",
    "q.l38#4.e" to "Demasiado estrecho reduce el rendimiento de evacuación; demasiado ancho multiplica el volumen a mover. 1–2 m es el equilibrio.",
    "q.l38#5.p" to "Por debajo de qué pendiente aproximada la nieve vuelve rodando hasta la sonda?",
    "q.l38#5.o0" to "26 grados",
    "q.l38#5.o1" to "10 grados",
    "q.l38#5.o2" to "45 grados",
    "q.l38#5.o3" to "60 grados",
    "q.l38#5.e" to "26 grados es el valor crítico del estudio. Si la pendiente no basta, la nieve evacuada vuelve y el trabajo se pierde.",
    "q.l38#6.p" to "¿Cuál de las tres técnicas de evacuación es la más eficaz?",
    "q.l38#6.o0" to "Palear barriendo (paddling)",
    "q.l38#6.o1" to "Cucharear (scooping)",
    "q.l38#6.o2" to "Cortar bloques (cutting blocks)",
    "q.l38#6.o3" to "Las tres igual",
    "q.l38#6.e" to "Barrer es «empujar» la nieve fuera con un gesto continuo y frecuente. Cortar bloques solo vale para nieve dura, porque primero hay que cortarla.",
    "q.l38#7.p" to "¿Para qué sirve nombrar a un director de excavación?",
    "q.l38#7.o0" to "Para vigilar la dirección, el estado de la nieve arriba y la posición de la víctima, y evitar que todos trabajen con la cabeza baja",
    "q.l38#7.o1" to "Para supervisar el trabajo",
    "q.l38#7.o2" to "Para hacer fotos",
    "q.l38#7.o3" to "Para ahorrar personal",
    "q.l38#7.e" to "Si todo el grupo mira hacia abajo, se excava desviado y se ignora una segunda alud. El director es la única persona que «mira hacia arriba».",
    "q.l38#8.p" to "Tras llegar a la cara, ¿cómo cambia el orden de las maniobras?",
    "q.l38#8.o0" to "Primero limpiar boca y nariz y confirmar la vía aérea, después tórax y brazos, y por último piernas y cuerpo",
    "q.l38#8.o1" to "Primero las piernas",
    "q.l38#8.o2" to "Primero tirar de los hombros",
    "q.l38#8.o3" to "Primero la mochila",
    "q.l38#8.e" to "El tórax tiene que poder expandirse para ventilar. Empezar por las piernas retrasa la ventilación, y tirar de los hombros puede causar una lesión de columna.",
    "q.l38#9.p" to "¿En qué se basa la frase «una sola persona también puede rescatar»?",
    "q.l38#9.o0" to "En que en condiciones de estudio, un solo rescatador con un plan de cinta transportadora de recursos limitados llega a 1,5 m de profundidad en menos de 18 minutos",
    "q.l38#9.o1" to "En que las personas tienen potencial",
    "q.l38#9.o2" to "En que la nieve pesa poco",
    "q.l38#9.o3" to "En que la víctima se autosocorre",
    "q.l38#9.e" to "Los ritmos de excavación de unos 13,2 cm/min en nieve dura y 25,3 cm/min en nieve blanda son datos de estudio, y justifican entrenar el plan individual.",
    "q.l38#10.p" to "¿Cuáles son aproximadamente los ritmos de excavación en nieve dura y blanda?",
    "q.l38#10.o0" to "Unos 13 cm/min en dura y unos 25 cm/min en blanda",
    "q.l38#10.o1" to "5 cm/min en ambas",
    "q.l38#10.o2" to "50 cm/min en ambas",
    "q.l38#10.o3" to "En dura es más rápido",
    "q.l38#10.e" to "Esa diferencia explica por qué el estado de la nieve cambia la previsión de tiempo de rescate, y por qué cortar bloques solo se usa en nieve dura.",
    "q.l38#11.p" to "¿Cuál es el error más frecuente al excavar entre varios?",
    "q.l38#11.o0" to "Que todos se apelotonan en el mismo punto, sin relevos ni cadena de evacuación",
    "q.l38#11.o1" to "Cavar demasiado ancho",
    "q.l38#11.o2" to "Cavar demasiado rápido",
    "q.l38#11.o3" to "Usar la pala",
    "q.l38#11.e" to "Apiñados se estorban y no se puede mantener el ritmo. Relevarse es mucho más rápido que «aguantar uno solo».",
    "q.l38#12.p" to "¿Qué roles hay que asignar al organizar una excavación?",
    "q.l38#12.o0" to "Director",
    "q.l38#12.o1" to "Excavación y evacuación de nieve",
    "q.l38#12.o2" to "Vigía de seguridad",
    "q.l38#12.o3" to "Persona que anota hora y posición",
    "q.l38#12.e" to "Los cuatro roles asignan responsables de dirección, esfuerzo físico, seguridad y tiempo. Si falta uno, algo se descontrola.",
    "q.l38#13.p" to "¿Qué prácticas hacen que la nieve evacuada vuelva al agujero?",
    "q.l38#13.o0" to "Cavar desde arriba o desde el lado de arriba",
    "q.l38#13.o1" to "Canal con pendiente demasiado suave (menos de unos 26 grados)",
    "q.l38#13.o2" to "Amontonar la nieve por encima de la sonda",
    "q.l38#13.o3" to "Colocar el canal siguiendo la línea de máxima pendiente",
    "q.l38#13.e" to "Las tres primeras hacen que la nieve retorne. La cuarta es justamente lo correcto.",
    "q.l38#14.p" to "Sobre el «punto de inicio de la excavación», ¿qué afirmaciones son correctas?",
    "q.l38#14.o0" to "La regla tradicional es retroceder 1,5 veces la profundidad y entrar en diagonal desde aguas abajo",
    "q.l38#14.o1" to "La simplificación de Avalanche.org es un paso atrás si la profundidad es menor de 1 m y dos si es mayor",
    "q.l38#14.o2" to "El ISSW 2023 propone cavar desde la sonda siguiendo la línea de máxima pendiente cuando hay gente suficiente",
    "q.l38#14.o3" to "La regla y las conclusiones del estudio se contradicen del todo: hay que elegir una",
    "q.l38#14.e" to "Las tres formulaciones son «principio más dos generaciones de experiencia». Se enseñan en ese orden: principio, regla, actualización. Así nadie convierte la regla en superstición.",
    "q.l38#15.p" to "Ordena una excavación estándar.",
    "q.l38#15.o0" to "Confirmar la zona de trabajo del lado de abajo y el riesgo de segunda alud",
    "q.l38#15.o1" to "Abrir un canal en V desde el punto de inicio hacia la sonda",
    "q.l38#15.o2" to "Organizar la cadena de evacuación y los relevos",
    "q.l38#15.o3" to "Al llegar a la cara, limpiar primero boca y nariz",
    "q.l38#15.e" to "El orden es «primero seguridad, después eficacia y al final prioridad de la vía aérea».",
    "q.l38#16.p" to "Ordena lo que se hace «después de llegar a la cara».",
    "q.l38#16.o0" to "Limpiar nieve y hielo de boca y nariz y confirmar la vía aérea",
    "q.l38#16.o1" to "Limpiar la nieve del tórax y los brazos para que el tórax pueda expandirse",
    "q.l38#16.o2" to "Limpiar las piernas y el resto del cuerpo",
    "q.l38#16.o3" to "Aplicar las reglas de reanimación y organizar el traslado",
    "q.l38#16.e" to "Este orden es lo contrario de «desenterrar del todo y luego atender», pero es el correcto: la ventana de ventilación es de minutos.",
    "q.l38#17.p" to "La pendiente crítica del canal de la cinta transportadora es de unos ______ grados.",
    "q.l38#17.a0" to "26",
    "q.l38#17.e" to "Por debajo de ese ángulo, los bloques de nieve vuelven rodando hasta la sonda y el rendimiento de evacuación cae mucho.",
    "q.l38#18.p" to "La regla tradicional recomienda retroceder desde la sonda unos ______ veces la profundidad de enterramiento.",
    "q.l38#18.a0" to "1,5",
    "q.l38#18.a1" to "1.5",
    "q.l38#18.e" to "1,5 veces es una regla empírica. Con gente suficiente, conviene valorar primero cavar desde la sonda siguiendo la línea de máxima pendiente.",
    "q.l38#19.p" to "El objetivo del rescate por compañeros es tocar a la persona en ______ minutos y desenterrarla en 18.",
    "q.l38#19.a0" to "10",
    "q.l38#19.e" to "10 y 18 son indicadores internos de entrenamiento y revisión, que sirven para localizar en qué paso se va lento.",
    "q.l38#20.p" to "Relaciona cada técnica de evacuación con su condición de uso.",
    "q.l38#20.l0" to "Palear barriendo (paddling)",
    "q.l38#20.l1" to "Cucharear (scooping)",
    "q.l38#20.l2" to "Cortar bloques (cutting blocks)",
    "q.l38#20.l3" to "Cadena de relevos (conveyor)",
    "q.l38#20.r0" to "La más eficaz, válida para casi cualquier nieve suelta",
    "q.l38#20.r1" to "Segunda en eficacia, sirve para sacar la nieve del canal",
    "q.l38#20.r2" to "La más lenta, solo en nieve dura",
    "q.l38#20.r3" to "Forma de organización del grupo, no una técnica manual",
    "q.l38#20.e" to "El orden de eficacia decide «barrer primero, cucharear después, cortar solo en dura». La cadena no es una técnica, es la organización.",
    "q.l38#21.p" to "Relaciona cada error frecuente con su consecuencia.",
    "q.l38#21.l0" to "Cavar desde el lado de arriba",
    "q.l38#21.l1" to "Canal con pendiente demasiado suave",
    "q.l38#21.l2" to "Tirar del cuerpo al tocar a la persona",
    "q.l38#21.l3" to "Sacar la sonda tras localizar",
    "q.l38#21.r0" to "La nieve vuelve a la cara: lento y peligroso",
    "q.l38#21.r1" to "La nieve retorna y hay que evacuarla varias veces",
    "q.l38#21.r2" to "Puede agravar una lesión de columna y meter nieve en boca y nariz",
    "q.l38#21.r3" to "Se pierde la referencia de posición y profundidad",
    "q.l38#21.e" to "Los cuatro errores son habituales y todos se evitan con práctica previa.",
    "q.l38#22.p" to "Nieve dura y solo tres personas. ¿Cómo se fija el punto de inicio?",
    "q.l38#22.o0" to "Cavar desde la sonda siguiendo la línea de máxima pendiente y abrir con cortes de bloque en el tramo duro",
    "q.l38#22.o1" to "Retroceder 3 veces la profundidad",
    "q.l38#22.o2" to "Cavar desde arriba en vertical",
    "q.l38#22.o3" to "Esperar al equipo adecuado",
    "q.l38#22.e" to "Con gente suficiente se va por la línea de máxima pendiente; la nieve dura solo cambia la técnica (cortar bloques), no el principio.",
    "q.l38#23.p" to "¿Por qué «todos a cavar a la vez con fuerza» no es más rápido?",
    "q.l38#23.o0" to "Se estorban, no se puede mantener el ritmo y nadie vigila la nieve de arriba",
    "q.l38#23.o1" to "Porque con tanta gente hace calor",
    "q.l38#23.o2" to "Porque faltan palas",
    "q.l38#23.o3" to "Porque no hay director",
    "q.l38#23.e" to "Excavar es un esfuerzo muy intenso y agota en minutos. Relevos, dirección y cadena de evacuación son lo que convierte el esfuerzo en velocidad.",
    "q.l38#24.p" to "Durante el rescate aparece un bloque grande de nieve dura junto a la víctima. ¿Qué se hace?",
    "q.l38#24.o0" to "Abrir primero el paso a la vía aérea y no retrasar la ventilación por mover el bloque",
    "q.l38#24.o1" to "Quitar el bloque primero",
    "q.l38#24.o2" to "Romperlo con el piolet",
    "q.l38#24.o3" to "Rodearlo",
    "q.l38#24.e" to "El bloque se puede tratar después. La ventana de la vía aérea es de minutos y tiene prioridad sobre «dejar limpio el sitio».",
    "q.l38#25.p" to "Solo hay una pala en la escena. ¿Qué se hace?",
    "q.l38#25.o0" to "Que cave la persona con mejor forma física y el resto empuje nieve con manos y esquís, por relevos",
    "q.l38#25.o1" to "Que uno cave solo hasta el final",
    "q.l38#25.o2" to "Esperar a una segunda pala",
    "q.l38#25.o3" to "Usar la mochila en lugar de la pala",
    "q.l38#25.e" to "La forma correcta con un solo recurso es la «cinta transportadora de recursos limitados»: uno cava y los demás sacan la nieve.",
    "q.l38#26.p" to "En la revisión se ve que «el contacto tardó 14 minutos». ¿Qué paso hay que revisar?",
    "q.l38#26.o0" to "La búsqueda y la localización: cuál de las cuatro fases fue lenta",
    "q.l38#26.o1" to "La excavación",
    "q.l38#26.o2" to "El momento de pedir ayuda",
    "q.l38#26.o3" to "La compra del material",
    "q.l38#26.e" to "El tiempo de contacto lo determinan la búsqueda y la localización; la excavación determina el tiempo de desenterramiento. Los dos indicadores se miran por separado.",
    // ---------- l42 Principios de seguridad y gestión del riesgo ----------
    "q.l42#0.p" to "¿A qué se refiere el principio «cuatro, tres, tres»?",
    "q.l42#0.o0" to "Reservar un tercio de margen en fuerzas, tiempo y material",
    "q.l42#0.o1" to "Tres personas, tres horas, tres itinerarios",
    "q.l42#0.o2" to "Tres tipos de material, tres tipos de tiempo",
    "q.l42#0.o3" to "Tres revisiones, tres confirmaciones",
    "q.l42#0.e" to "Reservar margen no es conservadurismo: es meter el imprevisto en el presupuesto desde el principio. Si se gasta todo, cualquier cambio depende de la suerte.",
    "q.l42#1.p" to "¿Cuáles son las «tres novedades» de la regla «tres novedades, no salgas»?",
    "q.l42#1.o0" to "Itinerario nuevo, compañeros nuevos, material nuevo",
    "q.l42#1.o1" to "Estación nueva, tiempo nuevo, altitud nueva",
    "q.l42#1.o2" to "Plan nuevo, presupuesto nuevo, objetivo nuevo",
    "q.l42#1.o3" to "Guía nuevo, coche nuevo, botas nuevas",
    "q.l42#1.e" to "Cada «nuevo» representa una incógnita. Juntar tres a la vez es llevar la incertidumbre al máximo en una sola salida.",
    "q.l42#2.p" to "¿Por qué «primero reducir consecuencias y luego probabilidad»?",
    "q.l42#2.o0" to "Porque una consecuencia, una vez ocurre, no se puede revertir, mientras que la probabilidad solo se puede reducir, no eliminar",
    "q.l42#2.o1" to "Porque reducir consecuencias es más barato",
    "q.l42#2.o2" to "Porque la probabilidad no se puede calcular",
    "q.l42#2.o3" to "El orden es indiferente",
    "q.l42#2.e" to "Encordarse, llevar casco o reservar una vía de escape son medidas del tipo «aunque ocurra, no será mortal». Funcionan mucho mejor que «tener cuidado».",
    "q.l42#3.p" to "¿Cuál es el orden correcto del principio STOP?",
    "q.l42#3.o0" to "Parar, pensar, observar, planificar",
    "q.l42#3.o1" to "Observar, parar, pensar, planificar",
    "q.l42#3.o2" to "Pensar, observar, parar, planificar",
    "q.l42#3.o3" to "Parar, observar, pensar, planificar",
    "q.l42#3.e" to "Primero hay que parar para poder pensar y observar. Bajo presión, la primera reacción suele ser seguir caminando, y ese es el reflejo más peligroso.",
    "q.l42#4.p" to "¿Para qué sirve el apartado «en qué casos se abandona» dentro de un plan?",
    "q.l42#4.o0" to "Para llevar la decisión fuera de la emoción y de la presión del objetivo",
    "q.l42#4.o1" to "Para que el plan quede completo",
    "q.l42#4.o2" to "Para pasar una inspección",
    "q.l42#4.o3" to "No sirve de nada",
    "q.l42#4.e" to "En la montaña, con cansancio y con un objetivo en la cabeza, decidir abandonar sobre la marcha es casi imposible. Solo lo escrito de antemano obliga.",
    "q.l42#5.p" to "¿Qué NO forma parte de las «tres claves para montar un campamento seguro»?",
    "q.l42#5.o0" to "Acampar lo más cerca posible del agua",
    "q.l42#5.o1" to "Evitar las trampas del terreno",
    "q.l42#5.o2" to "Dejar libre una vía de evacuación",
    "q.l42#5.o3" to "Concentrar el material crítico",
    "q.l42#5.e" to "Acampar pegado al agua es el escenario típico de una riada. El núcleo de las tres claves es «primero garantizar que se puede salir»; el paisaje y la comodidad van después.",
    "q.l42#6.p" to "El equipo estrena material y además va por un itinerario nuevo. Según la regla de las tres novedades, ¿qué se hace?",
    "q.l42#6.o0" to "Quitar al menos una de las dos, o bajar la dificultad hasta poder validar el material",
    "q.l42#6.o1" to "No pasa nada: el material nuevo es más seguro",
    "q.l42#6.o2" to "Acelerar el ritmo",
    "q.l42#6.o3" to "Ir separados",
    "q.l42#6.e" to "El material nuevo necesita validación y el itinerario nuevo necesita adaptación. Con las dos cosas a la vez, si algo falla no se sabe por qué.",
    "q.l42#7.p" to "Sobre «riesgo = consecuencia × probabilidad», ¿qué afirmación es correcta?",
    "q.l42#7.o0" to "Si la consecuencia es muy grave, hay que atenderla aunque la probabilidad sea baja",
    "q.l42#7.o1" to "Con probabilidad baja se puede ignorar",
    "q.l42#7.o2" to "Basta con mirar la probabilidad",
    "q.l42#7.o3" to "Basta con mirar la consecuencia",
    "q.l42#7.e" to "El sentido del producto es que, con una consecuencia suficientemente grave, un suceso muy improbable sigue teniendo que estar cubierto por el plan.",
    "q.l42#8.p" to "¿Qué medidas reducen la consecuencia?",
    "q.l42#8.o0" to "Ir encordados y montar puntos de protección",
    "q.l42#8.o1" to "Llevar casco",
    "q.l42#8.o2" to "Dejar libre una vía de evacuación",
    "q.l42#8.o3" to "Mejorar la forma física",
    "q.l42#8.e" to "Las tres primeras reducen el daño «cuando ya ha pasado algo». Mejorar la forma física reduce la probabilidad de que ocurra, no la consecuencia.",
    "q.l42#9.p" to "¿Qué medidas reducen la probabilidad?",
    "q.l42#9.o0" to "Consultar el parte meteorológico y el boletín de aludes",
    "q.l42#9.o1" to "Aclimatarse con antelación",
    "q.l42#9.o2" to "Elegir un itinerario consolidado",
    "q.l42#9.o3" to "Llevar un solo walkie",
    "q.l42#9.e" to "Las tres primeras reducen las ocasiones de encontrarse con el peligro. La última no tiene relación con el riesgo y además debilita la redundancia.",
    "q.l42#10.p" to "¿En qué situaciones hay que activar el STOP?",
    "q.l42#10.o0" to "El itinerario no coincide con el mapa",
    "q.l42#10.o1" to "El tiempo cambia de forma clara en poco rato",
    "q.l42#10.o2" to "Alguien del grupo está raro y no sabe explicar por qué",
    "q.l42#10.o3" to "El plan va media hora retrasado",
    "q.l42#10.e" to "Las tres primeras son señales de que la información no cuadra con lo esperado. Ir media hora tarde es una fluctuación normal: primero se revisa el horario y luego se decide.",
    "q.l42#11.p" to "Ordena el tratamiento de un riesgo.",
    "q.l42#11.o0" to "Identificar los factores peligrosos (terreno, tiempo, estado de las personas)",
    "q.l42#11.o1" to "Valorar consecuencia y probabilidad",
    "q.l42#11.o2" to "Elegir primero medidas que reduzcan la consecuencia",
    "q.l42#11.o3" to "Ejecutar y fijar un momento de revisión",
    "q.l42#11.e" to "El último paso es el que más se olvida: sin un punto de revisión, las medidas dejan de funcionar sin que nadie lo note.",
    "q.l42#12.p" to "Ordena la revisión de las tres novedades antes de salir.",
    "q.l42#12.o0" to "Enumerar el itinerario, los compañeros y el material nuevos de esta salida",
    "q.l42#12.o1" to "Valorar la incógnita que aporta cada uno",
    "q.l42#12.o2" to "Decidir cuál se elimina o cuánto se baja la dificultad",
    "q.l42#12.o3" to "Escribir la decisión en el plan y comunicarla al grupo",
    "q.l42#12.e" to "La clave está en el tercer paso: quitar algo es una decisión activa, no un «ya tendremos cuidado».",
    "q.l42#13.p" to "El principio «cuatro, tres, tres» reserva ______ de margen en fuerzas, tiempo y material.",
    "q.l42#13.a0" to "un tercio",
    "q.l42#13.a1" to "1/3",
    "q.l42#13.a2" to "la tercera parte",
    "q.l42#13.e" to "Un tercio es un valor empírico. Cuanto más se gasta, menos margen queda para maniobrar ante un cambio.",
    "q.l42#14.p" to "El riesgo es igual a la consecuencia multiplicada por la ______.",
    "q.l42#14.a0" to "probabilidad",
    "q.l42#14.a1" to "posibilidad",
    "q.l42#14.e" to "Separar el riesgo en dos factores permite decidir cuál bajar; por norma general, primero la consecuencia.",
    "q.l42#15.p" to "En la regla «tres novedades, no salgas» se recomienda no acumular más de ______ novedad(es) en una misma salida.",
    "q.l42#15.a0" to "1",
    "q.l42#15.a1" to "una",
    "q.l42#15.a2" to "2",
    "q.l42#15.a3" to "dos",
    "q.l42#15.e" to "Una como máximo; dos ya es el techo. Con las tres a la vez, el plan se construye sobre tres incógnitas.",
    "q.l42#16.p" to "Relaciona cada medida con su efecto.",
    "q.l42#16.l0" to "Ir encordados",
    "q.l42#16.l1" to "Consultar el boletín de aludes",
    "q.l42#16.l2" to "Dejar una vía de evacuación",
    "q.l42#16.l3" to "Aclimatarse con antelación",
    "q.l42#16.r0" to "Reduce la consecuencia (la caída no la sostiene uno solo)",
    "q.l42#16.r1" to "Reduce la probabilidad (evitar los días de mayor riesgo)",
    "q.l42#16.r2" to "Reduce la consecuencia (si la cosa empeora, se puede salir)",
    "q.l42#16.r3" to "Reduce la probabilidad (menos mal de altura)",
    "q.l42#16.e" to "La diferencia entre las cuatro es si cambian el resultado o la probabilidad. Tenerlo claro indica dónde invertir el esfuerzo.",
    "q.l42#17.p" to "Relaciona cada principio con su ámbito de aplicación.",
    "q.l42#17.l0" to "Cuatro, tres, tres",
    "q.l42#17.l1" to "Tres novedades, no salgas",
    "q.l42#17.l2" to "STOP",
    "q.l42#17.l3" to "Consecuencia × probabilidad",
    "q.l42#17.r0" to "Reparto de tiempo y recursos en la actividad",
    "q.l42#17.r1" to "Decisiones y recortes antes de salir",
    "q.l42#17.r2" to "Cuando en el terreno se descubre de golpe que algo no cuadra",
    "q.l42#17.r3" to "Elegir entre varias alternativas",
    "q.l42#17.e" to "Las cuatro herramientas sirven para «planificar, preparar la salida, actuar en el terreno y elegir». No se sustituyen: van por fases.",

    // ---------- l26 Mapas, brújula y orientación en el medio natural ----------
    "q.l26#0.p" to "En un mapa 1:50.000, ¿a cuántos metros equivale 1 cm?",
    "q.l26#0.o0" to "500 m",
    "q.l26#0.o1" to "50 m",
    "q.l26#0.o2" to "5.000 m",
    "q.l26#0.o3" to "5 m",
    "q.l26#0.e" to "Del denominador de la escala se quitan dos ceros y queda «cuántos metros son 1 cm»: 50.000 → 500 m. Es el punto de partida de todos los cálculos de lectura de mapa.",
    "q.l26#1.p" to "¿Qué es la equidistancia?",
    "q.l26#1.o0" to "La diferencia de altura entre dos curvas de nivel contiguas",
    "q.l26#1.o1" to "La distancia horizontal entre curvas de nivel",
    "q.l26#1.o2" to "La diferencia de altura entre dos puntos del mapa",
    "q.l26#1.o3" to "La altura relativa de un pico",
    "q.l26#1.e" to "Cuanto mayor es la equidistancia, más esquemático es el mapa. La pendiente se juzga por la separación de las curvas y el desnivel, por la equidistancia.",
    "q.l26#2.p" to "¿Cómo se define la declinación magnética?",
    "q.l26#2.o0" to "El ángulo entre el norte magnético y el norte verdadero",
    "q.l26#2.o1" to "El ángulo entre el mapa y el terreno",
    "q.l26#2.o2" to "La inclinación de la ladera",
    "q.l26#2.o3" to "El error de la aguja",
    "q.l26#2.e" to "La declinación cambia según la zona y varía año a año. Los mapas suelen indicar el valor del año de edición y la variación anual, y hay que corregirla antes de usar la brújula.",
    "q.l26#3.p" to "Después de trazar en el mapa el rumbo hacia el objetivo, ¿cómo se avanza?",
    "q.l26#3.o0" to "Avanzar en ese rumbo corrigiendo continuamente con las curvas de nivel y los detalles del terreno",
    "q.l26#3.o1" to "Caminar recto con la vista clavada en la brújula",
    "q.l26#3.o2" to "Seguir solo la flecha del GPS",
    "q.l26#3.o3" to "Ir por el sendero más evidente, sea cual sea el rumbo",
    "q.l26#3.e" to "El rumbo da la dirección general y el terreno da la posición concreta. Mirando solo la aguja se puede acabar en la cresta de al lado, y eso cuesta horas.",
    "q.l26#4.p" to "¿Qué indica que las curvas de nivel estén más juntas?",
    "q.l26#4.o0" to "Que la pendiente es más fuerte",
    "q.l26#4.o1" to "Que la pendiente es más suave",
    "q.l26#4.o2" to "Que la altitud es mayor",
    "q.l26#4.o3" to "Que el terreno es más llano",
    "q.l26#4.e" to "Curvas juntas significa más desnivel en la misma distancia horizontal, es decir, más pendiente. Es lo más útil para ver «qué subida cansa menos».",
    "q.l26#5.p" to "¿Cómo debe tratarse el GPS en el medio natural?",
    "q.l26#5.o0" to "Como un acelerador y un respaldo, nunca como el único medio de navegación",
    "q.l26#5.o1" to "Como el único medio de navegación",
    "q.l26#5.o2" to "Como un aparato de ocio",
    "q.l26#5.o3" to "Como un dispositivo de socorro",
    "q.l26#5.e" to "La batería se agota, el frío afecta, entra agua y se puede caer. El mapa de papel y la brújula son la única opción que no depende de una pila.",
    "q.l26#6.p" to "¿Qué significa orientar el mapa?",
    "q.l26#6.o0" to "Hacer coincidir el norte del mapa con el norte real",
    "q.l26#6.o1" to "Doblar el mapa por la zona actual",
    "q.l26#6.o2" to "Meter el mapa en una funda estanca",
    "q.l26#6.o3" to "Marcar la ruta con rotulador grueso",
    "q.l26#6.e" to "Solo con el mapa orientado coinciden las crestas y los valles del dibujo con lo que se tiene delante. Mucha gente no entiende el mapa porque falla en este primer paso.",
    "q.l26#7.p" to "Sin visibilidad, en una ladera de nieve o con niebla, ¿cuál es el método de orientación más fiable?",
    "q.l26#7.o0" to "Rumbo con brújula más estimación de distancia por tiempo o por pasos",
    "q.l26#7.o1" to "La intuición",
    "q.l26#7.o2" to "Esperar a que se abra el cielo",
    "q.l26#7.o3" to "Seguir las huellas de otro",
    "q.l26#7.e" to "Con mala visibilidad desaparecen las referencias del terreno y solo queda «ángulo más distancia». Contar pasos exige haber calibrado antes la longitud del paso, o el error será enorme.",
    "q.l26#8.p" to "¿Qué incluye como mínimo un equipo de navegación que no dependa de la electrónica?",
    "q.l26#8.o0" to "Mapa topográfico de papel de la zona",
    "q.l26#8.o1" to "Brújula",
    "q.l26#8.o2" to "Altímetro o reloj",
    "q.l26#8.o3" to "Pilas de repuesto",
    "q.l26#8.e" to "El cuarto sirve a los aparatos electrónicos y no pertenece al conjunto «sin electrónica». Mapa, brújula y altímetro bastan para orientarse y avanzar.",
    "q.l26#9.p" to "¿Qué situaciones hacen poco fiable el track del GPS?",
    "q.l26#9.o0" to "Barrancos y paredes que bloquean la señal",
    "q.l26#9.o1" to "El frío, que hace caer la batería de golpe",
    "q.l26#9.o2" to "Pararse bajo una cornisa",
    "q.l26#9.o3" to "Que el itinerario sea muy recto",
    "q.l26#9.e" to "Las tres primeras provocan deriva en la posición o cortes de alimentación. Que la ruta sea recta no afecta a la señal, aunque una ruta recta suele hacer que se dependa más del aparato y se mire menos el terreno.",
    "q.l26#10.p" to "¿Qué pistas se usan al leer el mapa para confirmar la propia posición?",
    "q.l26#10.o0" to "La orientación de la ladera en la que se está",
    "q.l26#10.o1" to "La forma de las curvas de nivel bajo los pies (cresta, valle, collado)",
    "q.l26#10.o2" to "La relación de rumbo con elementos evidentes del terreno",
    "q.l26#10.o3" to "La forma de las nubes",
    "q.l26#10.e" to "Orientación de la ladera, forma de las curvas y rumbo respecto a referencias claras: cruzando las tres se sitúa uno. La forma de las nubes sirve para el tiempo, no para orientarse.",
    "q.l26#11.p" to "Ordena una orientación completa con rumbo.",
    "q.l26#11.o0" to "Orientar el mapa, alineando su norte con el norte real",
    "q.l26#11.o1" to "Confirmar la posición actual",
    "q.l26#11.o2" to "Medir el rumbo al punto de destino",
    "q.l26#11.o3" to "Avanzar en ese rumbo comprobando el terreno",
    "q.l26#11.e" to "El orden no se puede saltar: con la posición dudosa, el rumbo medido no significa nada; sin comprobar el terreno, se camina por una «recta teórica».",
    "q.l26#12.p" to "En un terreno sin referencias claras, ¿cuál es el orden para seguir un rumbo?",
    "q.l26#12.o0" to "Elegir un punto intermedio lejano",
    "q.l26#12.o1" to "Ir hasta ese punto y volver a confirmar la posición",
    "q.l26#12.o2" to "Elegir el siguiente punto intermedio",
    "q.l26#12.o3" to "Al acercarse al objetivo, confirmarlo con detalles del terreno",
    "q.l26#12.e" to "Una línea recta larga casi nunca se puede mantener en terreno ondulado. Ir por tramos con puntos intermedios es la única forma de llevar el «ángulo» al terreno real.",
    "q.l26#13.p" to "El ángulo entre el norte magnético y el norte verdadero se llama ______ magnética.",
    "q.l26#13.a0" to "declinación",
    "q.l26#13.a1" to "declinacion",
    "q.l26#13.a2" to "declination",
    "q.l26#13.e" to "La declinación hay que corregirla con el valor del año que indica el mapa; si no, se puede desviar decenas de metros por kilómetro.",
    "q.l26#14.p" to "En un mapa 1:25.000, 1 cm representa ______ m sobre el terreno.",
    "q.l26#14.a0" to "250",
    "q.l26#14.e" to "Al denominador se le quitan dos ceros: 25.000 → 250 m. A mayor escala, más detalle y menos superficie en cada hoja.",
    "q.l26#15.p" to "Con una equidistancia de 10 m, para ir de la curva de 3.200 m a la de 3.280 m hay que cruzar ______ curvas de nivel (sin contar la de salida).",
    "q.l26#15.a0" to "8",
    "q.l26#15.e" to "(3.280 − 3.200) ÷ 10 = 8. Este cálculo se usa a diario para estimar desnivel y tiempo.",
    "q.l26#16.p" to "Relaciona cada forma del terreno con su representación en el mapa.",
    "q.l26#16.l0" to "Cresta",
    "q.l26#16.l1" to "Valle",
    "q.l26#16.l2" to "Collado",
    "q.l26#16.l3" to "Pared",
    "q.l26#16.r0" to "Las curvas de nivel apuntan hacia abajo",
    "q.l26#16.r1" to "Las curvas de nivel apuntan hacia arriba",
    "q.l26#16.r2" to "Punto bajo entre dos conjuntos de curvas, con altura a ambos lados",
    "q.l26#16.r3" to "Varias curvas de nivel superpuestas o muy juntas",
    "q.l26#16.e" to "«Apuntan hacia abajo, es cresta; apuntan hacia arriba, es valle» es la regla más práctica de lectura. El collado es clave al elegir itinerario: suele ser el paso más bajo.",
    "q.l26#17.p" to "Relaciona cada herramienta de navegación con su limitación.",
    "q.l26#17.l0" to "GPS",
    "q.l26#17.l1" to "Brújula",
    "q.l26#17.l2" to "Altímetro",
    "q.l26#17.l3" to "Mapa de papel",
    "q.l26#17.r0" to "Depende de batería y de señal; falla en barrancos y con frío",
    "q.l26#17.r1" to "Le afectan objetos ferromagnéticos cercanos y exige corregir la declinación",
    "q.l26#17.r2" to "Solo da altura, no posición en el plano",
    "q.l26#17.r3" to "Necesita actualización y puede no recoger itinerarios nuevos",
    "q.l26#17.e" to "Cada herramienta tiene su modo de fallo, así que la navegación se hace combinando: cuando una falla, la otra sigue dando una condición que acota.",
    // ---------- l27 Elección y construcción del campamento ----------
    "q.l27#0.p" to "Al elegir el sitio del campamento, ¿qué tiene la máxima prioridad?",
    "q.l27#0.o0" to "Evitar caída de piedras, canales de alud y la línea de inundación",
    "q.l27#0.o1" to "Que haya buenas vistas",
    "q.l27#0.o2" to "Estar lo más cerca posible del itinerario",
    "q.l27#0.o3" to "Que el suelo sea lo más llano posible",
    "q.l27#0.e" to "Seguridad, agua, llano y comodidad, en ese orden. Invertirlo lleva a accidentes del tipo «tienda montada en la zona de depósito de un alud».",
    "q.l27#1.p" to "Al acampar en una ladera de nieve, ¿qué se hace primero?",
    "q.l27#1.o0" to "Pisar y compactar la nieve y excavar una plataforma horizontal",
    "q.l27#1.o1" to "Extender la tienda directamente",
    "q.l27#1.o2" to "Poner el agua a hervir",
    "q.l27#1.o3" to "Tensar primero los vientos",
    "q.l27#1.e" to "Con la nieve irregular se resbala toda la noche; sin plataforma, la tienda recibe cargas desiguales y el viento la deforma.",
    "q.l27#2.p" to "Sobre la distancia entre el campamento y el punto de agua, ¿qué es razonable?",
    "q.l27#2.o0" to "Que sea cómodo de alcanzar, pero acampando a más de 60 m del agua",
    "q.l27#2.o1" to "Pegado a la orilla",
    "q.l27#2.o2" to "Dentro del agua",
    "q.l27#2.o3" to "Cuanto más lejos mejor, dos kilómetros",
    "q.l27#2.e" to "60 m es la distancia sanitaria habitual: reduce la contaminación del agua y evita las crecidas nocturnas. Acampar pegado al agua es el escenario típico de una riada.",
    "q.l27#3.p" to "En un campamento base, ¿cómo se organizan la zona de cocina y la de dormir?",
    "q.l27#3.o0" to "Separadas, con la cocina lejos de la zona de dormir",
    "q.l27#3.o1" to "Juntas, que es más cómodo",
    "q.l27#3.o2" to "La cocina dentro de la tienda",
    "q.l27#3.o3" to "Da igual",
    "q.l27#3.e" to "Separarlas tiene tres razones: riesgo de llama, monóxido de carbono y olores que atraen animales. Juntarlas ahorra diez metros de camino y puede costar la tienda entera.",
    "q.l27#4.p" to "Para fijar la tienda sobre hielo o nieve dura, ¿qué es correcto?",
    "q.l27#4.o0" to "Usar tornillos de hielo, anclajes de nieve o sacos enterrados; no basta con piedras encima",
    "q.l27#4.o1" to "Con piedras encima es suficiente",
    "q.l27#4.o2" to "Atar los vientos a los bastones",
    "q.l27#4.o3" to "No hace falta fijarla",
    "q.l27#4.e" to "En el hielo no hay material suelto que poner encima y el viento arranca la tienda con estacas incluidas. Los tornillos y los anclajes de nieve son los puntos eficaces.",
    "q.l27#5.p" to "Al desmontar el campamento, ¿qué se hace con el rastro del fuego?",
    "q.l27#5.o0" to "Empaparlo bien, dispersar las cenizas y dejar el sitio como estaba",
    "q.l27#5.o1" to "Tapar con tierra",
    "q.l27#5.o2" to "Dejarlo para la próxima vez",
    "q.l27#5.o3" to "No hace falta hacer nada",
    "q.l27#5.e" to "Dispersar las cenizas ayuda a que el sitio recupere su aspecto natural. Un círculo de fuego permanece mucho tiempo y además invita a que otros hagan fuego en el mismo punto.",
    "q.l27#6.p" to "Con viento fuerte, ¿por dónde falla primero una tienda?",
    "q.l27#6.o0" to "Por los vientos y los puntos de fijación: la carga desigual levanta un lado",
    "q.l27#6.o1" to "Por la tela",
    "q.l27#6.o2" to "Por la cremallera",
    "q.l27#6.o3" to "Por el suelo",
    "q.l27#6.e" to "El ángulo de los vientos y la calidad de los anclajes definen la resistencia. La mayoría de las tiendas destrozadas no rompen la tela: falla antes un punto de fijación.",
    "q.l27#7.p" to "Nevó de noche y por la mañana la tienda está medio enterrada. ¿Qué se hace?",
    "q.l27#7.o0" to "Abrir primero la ventilación y la puerta, y después limpiar la nieve alrededor",
    "q.l27#7.o1" to "Hacer fotos primero",
    "q.l27#7.o2" to "Recoger la tienda directamente",
    "q.l27#7.o3" to "Esperar a que deje de nevar",
    "q.l27#7.e" to "Una ventilación tapada significa riesgo de monóxido de carbono y de hipoxia. Primero se garantiza la ventilación y luego se habla del resto.",
    "q.l27#8.p" to "¿Cuáles de estos son «trampas del terreno» donde no conviene acampar?",
    "q.l27#8.o0" to "El pie de una zona de depósito de alud",
    "q.l27#8.o1" to "Cauces secos y barrancos de escorrentía",
    "q.l27#8.o2" to "Los collados y puntos expuestos de una cresta",
    "q.l27#8.o3" to "Un claro llano dentro del bosque",
    "q.l27#8.e" to "Los tres primeros son posiciones típicamente peligrosas por alud, riada y viento fuerte. Un claro en el bosque es relativamente seguro, aunque hay que revisar ramas secas y árboles caídos.",
    "q.l27#9.p" to "¿Qué condiciones debe cumplir un campamento aceptable?",
    "q.l27#9.o0" to "Suelo llano y con buen drenaje",
    "q.l27#9.o1" to "Resguardado del viento pero no cerrado",
    "q.l27#9.o2" to "Disponibilidad de agua",
    "q.l27#9.o3" to "Cobertura de móvil a tope",
    "q.l27#9.e" to "Las tres primeras determinan si se duerme bien y si se pasa frío. La cobertura es un extra: no se mueve el campamento a una cresta expuesta por tener señal.",
    "q.l27#10.p" to "Sobre las necesidades fisiológicas y la higiene en el medio natural, ¿qué es correcto?",
    "q.l27#10.o0" to "Hacer un cat hole de 15–20 cm de profundidad y a más de 60 m del agua",
    "q.l27#10.o1" to "Llevarse el papel higiénico en lugar de quemarlo",
    "q.l27#10.o2" to "Concentrarlo todo en el mismo punto",
    "q.l27#10.o3" to "Enterrarlo en la nieve",
    "q.l27#10.e" to "Concentrar intensifica la contaminación local y enterrar en nieve significa que todo quedará al descubierto con el deshielo. Cat hole más papel retirado es la práctica de bajo impacto habitual.",
    "q.l27#11.p" to "Ordena la construcción de un campamento.",
    "q.l27#11.o0" to "Evaluar el riesgo de caída de piedras, aludes e inundación",
    "q.l27#11.o1" to "Elegir el emplazamiento de la tienda y allanar el suelo",
    "q.l27#11.o2" to "Montar la tienda y colocar vientos y anclajes",
    "q.l27#11.o3" to "Delimitar la zona de cocina, la de almacenaje y la de letrina",
    "q.l27#11.e" to "Primero se evalúa el riesgo y luego se trabaja. Muchos montan la tienda antes de levantar la vista para ver si hay grietas o hielo colgando arriba.",
    "q.l27#12.p" to "La profundidad habitual de un cat hole en el medio natural es de unos ______ cm.",
    "q.l27#12.a0" to "15–20",
    "q.l27#12.a1" to "15-20",
    "q.l27#12.a2" to "15",
    "q.l27#12.a3" to "20",
    "q.l27#12.a4" to "15~20",
    "q.l27#12.e" to "15–20 cm es la profundidad que más se cita: suficiente para la descomposición y sin llegar a atravesar la capa superficial del suelo.",
    "q.l27#13.p" to "La distancia sanitaria mínima entre el campamento y el agua o los caminos suele ser de ______ m.",
    "q.l27#13.a0" to "60",
    "q.l27#13.e" to "60 m (unos 70 pasos) es la distancia LNT habitual para las necesidades, el lavado de platos y la higiene personal.",
    "q.l27#14.p" to "Relaciona cada zona del campamento con su requisito.",
    "q.l27#14.l0" to "Zona de dormir",
    "q.l27#14.l1" to "Zona de cocina",
    "q.l27#14.l2" to "Zona de almacenaje",
    "q.l27#14.l3" to "Zona de letrina",
    "q.l27#14.r0" to "Llana, resguardada y lejos de llamas y olores",
    "q.l27#14.r1" to "Ventilada, lejos de las tiendas y con cuidado con el fuego",
    "q.l27#14.r2" to "Protegida de humedad y animales, cerca pero sin ocupar el paso",
    "q.l27#14.r3" to "A más de 60 m del agua y evitando la escorrentía de la ladera",
    "q.l27#14.e" to "Dividir por zonas pone cada actividad en sus condiciones adecuadas. El resultado más directo de una mala división es olor a comida dentro de la tienda y una llama junto al sitio donde se duerme.",
    "q.l27#15.p" to "Junto al campamento hay un arroyo precioso, pero a dos kilómetros río arriba está lloviendo con fuerza. ¿Cómo se valora?",
    "q.l27#15.o0" to "No acampar en el cauce: el riesgo de crecida nocturna es alto",
    "q.l27#15.o1" to "No pasa nada, el arroyo es pequeño",
    "q.l27#15.o2" to "Acercar un poco la tienda al agua",
    "q.l27#15.o3" to "Poner piedras en el cauce para frenar el agua",
    "q.l27#15.e" to "En montaña una crecida puede llegar en minutos, y el ruido llega antes que el agua. No acampar en cauces, barrancos ni abanicos aluviales es una regla rígida.",
    "q.l27#16.p" to "¿Por qué no conviene poner el campamento bajo un árbol grande y aislado?",
    "q.l27#16.o0" to "Porque aumentan tanto el riesgo de rayo como el de caída de ramas",
    "q.l27#16.o1" to "Porque debajo no corre el aire",
    "q.l27#16.o2" to "Porque las raíces hacen tropezar",
    "q.l27#16.o3" to "Porque da sombra",
    "q.l27#16.e" to "Un punto alto y aislado es el camino preferente del rayo, y las ramas que rompe la tormenta son una fuente habitual de lesiones. En bosque se elige un claro, no un árbol solitario.",

    // ---------- l25 Preparación previa: permisos, seguro y logística ----------
    "q.l25#0.p" to "¿Qué es lo que más se subestima al tramitar un permiso de montaña?",
    "q.l25#0.o0" to "La antelación y los requisitos añadidos (guía, enlace, certificado médico)",
    "q.l25#0.o1" to "El coste",
    "q.l25#0.o2" to "El tamaño de las fotos",
    "q.l25#0.o3" to "El horario de la oficina",
    "q.l25#0.e" to "Muchos itinerarios exigen solicitud con semanas de antelación y llevan asociado un guía local o un enlace. Tramitarlo al pie de la montaña suele significar cambiar de ruta.",
    "q.l25#1.p" to "Al elegir seguro, ¿qué dos cosas hay que confirmar?",
    "q.l25#1.o0" to "Que cubra la escalada técnica y que cubra la evacuación en helicóptero a gran altitud",
    "q.l25#1.o1" to "Que incluya retrasos de vuelo",
    "q.l25#1.o2" to "Que se pueda cancelar",
    "q.l25#1.o3" to "Que la prima sea baja",
    "q.l25#1.e" to "Los seguros de viaje habituales excluyen «escalada técnica» y «gran altitud». Descubrir que no cubre cuando ya ha pasado algo es el segundo daño más frecuente en estos accidentes.",
    "q.l25#2.p" to "¿Qué parte de la logística necesita plan alternativo?",
    "q.l25#2.o0" to "Transporte, porte y avituallamiento del campamento: cada tramo debe tener alternativa",
    "q.l25#2.o1" to "Solo el transporte",
    "q.l25#2.o2" to "Solo el alojamiento",
    "q.l25#2.o3" to "Ninguna: no hacen falta alternativas",
    "q.l25#2.e" to "En montaña el retraso es la norma: carretera cortada, vuelo cancelado, porte modificado. Con alternativa en cada tramo, un atasco no tumba toda la cadena.",
    "q.l25#3.p" to "En la hoja de ruta que se deja al contacto, ¿qué hay que indicar como mínimo?",
    "q.l25#3.o0" to "Itinerario, horas de cada punto de control y cuánto tiempo sin noticias activa el protocolo y la alerta",
    "q.l25#3.o1" to "Solo el nombre de la montaña",
    "q.l25#3.o2" to "Solo los nombres de los compañeros",
    "q.l25#3.o3" to "Solo el presupuesto",
    "q.l25#3.e" to "La hoja sirve para que otra persona pueda decidir «si debe preocuparse». Los horarios y el protocolo son el núcleo; el itinerario es el punto de partida.",
    "q.l25#4.p" to "¿Por qué conviene reservar un 20 % de margen en el presupuesto?",
    "q.l25#4.o0" to "Porque los retrasos, las noches extra y los porteadores añadidos siempre acaban ocurriendo",
    "q.l25#4.o1" to "Para comprar recuerdos",
    "q.l25#4.o2" to "Para las propinas",
    "q.l25#4.o3" to "Porque cambia el tipo de cambio",
    "q.l25#4.e" to "Esos gastos no son imprevistos: son lo normal. El margen no busca ahorrar, sino evitar que en la montaña se tomen malas decisiones por dinero.",
    "q.l25#5.p" to "¿Qué material suele hacer falta para el certificado de cumbre?",
    "q.l25#5.o0" to "Fotos o vídeo de la cumbre, declaración de cumbre, permiso y documento de identidad",
    "q.l25#5.o1" to "Solo fotos",
    "q.l25#5.o2" to "Solo la firma de un compañero",
    "q.l25#5.o3" to "No hace falta nada",
    "q.l25#5.e" to "Cada montaña tiene sus requisitos, pero fotos, declaración y permiso se piden casi siempre. Confirmarlo antes de salir es mucho más fácil que arreglarlo a la vuelta.",
    "q.l25#6.p" to "¿Qué hay que dejar claro a todo el equipo antes de salir?",
    "q.l25#6.o0" to "Hora y lugar de encuentro y de evacuación",
    "q.l25#6.o1" to "Canal de walkie y normas de llamada",
    "q.l25#6.o2" to "Información médica y alergias o contraindicaciones",
    "q.l25#6.o3" to "El reparto diario de comida de cada uno",
    "q.l25#6.e" to "Los dos primeros afectan a separaciones y rescates, y el tercero es información clave en una urgencia. El reparto de comida es un detalle logístico que decide el jefe de expedición.",
    "q.l25#7.p" to "¿Cuáles de estos documentos pueden impedirte entrar si no los llevas?",
    "q.l25#7.o0" to "Permiso de la reserva o de ascensión",
    "q.l25#7.o1" to "Documento de identidad",
    "q.l25#7.o2" to "Póliza de seguro (en algunos itinerarios)",
    "q.l25#7.o3" to "Certificado de cumbre",
    "q.l25#7.e" to "El certificado de cumbre se obtiene a la vuelta y no sirve como documento de acceso. Los dos primeros se piden casi siempre y el tercero según el itinerario.",
    "q.l25#8.p" to "Desde que se decide subir una montaña hasta la salida, ¿cuál es el orden razonable?",
    "q.l25#8.o0" to "Fijar itinerario y ventana de tiempo",
    "q.l25#8.o1" to "Tramitar permisos y reservar transporte y porte",
    "q.l25#8.o2" to "Contratar un seguro específico y revisar las exclusiones",
    "q.l25#8.o3" to "Preparar la carpeta de documentos y dejar la hoja de ruta al contacto",
    "q.l25#8.e" to "Primero el itinerario para poder tramitar el permiso; con permiso y transporte cerrados ya se sabe qué días y qué actividades debe cubrir el seguro; el archivo de documentos va al final.",
    "q.l25#9.p" to "Si el equipaje se retrasa o no llega en el mismo vuelo, lo que más conviene llevar encima es ______.",
    "q.l25#9.a0" to "las botas de montaña",
    "q.l25#9.a1" to "las botas de alta montaña",
    "q.l25#9.a2" to "las botas",
    "q.l25#9.a3" to "el material técnico personal",
    "q.l25#9.e" to "Perder las botas o el material técnico personal es casi imposible de sustituir sobre la marcha. La mayoría de los equipos exigen llevar ambas cosas encima y no facturarlas.",
    "q.l25#10.p" to "En el presupuesto se recomienda dejar un margen del ______ %.",
    "q.l25#10.a0" to "20",
    "q.l25#10.e" to "El 20 % es un valor empírico. En montaña el gasto extra se concentra en «retrasos» y en «mano de obra».",
    "q.l25#11.p" to "Relaciona cada documento con su función.",
    "q.l25#11.l0" to "Permiso de ascensión",
    "q.l25#11.l1" to "Póliza y teléfono de rescate",
    "q.l25#11.l2" to "Declaración de cumbre",
    "q.l25#11.l3" to "Hoja de ruta",
    "q.l25#11.r0" to "Acredita el acceso y se revisa en los controles",
    "q.l25#11.r1" to "Base para contactar el rescate y tramitar el siniestro",
    "q.l25#11.r2" to "Se entrega al solicitar el certificado de cumbre",
    "q.l25#11.r3" to "Se deja al contacto para decidir cuándo dar la alarma",
    "q.l25#11.e" to "Cuatro documentos para cuatro escenarios: entrar, tener un accidente, acreditar y desaparecer. Si falta uno, ese escenario se bloquea.",
    "q.l25#12.p" to "Si el equipo no aclara antes de salir «quién tiene autoridad para decir basta», ¿cuál es la consecuencia más probable?",
    "q.l25#12.o0" to "Que nadie se atreve a hablar cuando habría que parar y el silencio colectivo amplifica el riesgo",
    "q.l25#12.o1" to "Que se camina más rápido",
    "q.l25#12.o2" to "Que la mochila pesa menos",
    "q.l25#12.o3" to "Ninguna",
    "q.l25#12.e" to "Convertir el «basta» en una autorización dada de antemano y no en una prueba de valor personal. Aclararlo antes sirve mucho más que discutirlo en la montaña.",
    "q.l25#13.p" to "El permiso exige contratar guía local y alguien del grupo se opone. ¿Qué se hace?",
    "q.l25#13.o0" to "Cumplir la norma e incluir al guía en presupuesto y plan",
    "q.l25#13.o1" to "Evitar el control",
    "q.l25#13.o2" to "Que el guía solo figure en el papel",
    "q.l25#13.o3" to "Cambiar a un itinerario que no lo exija y reevaluar",
    "q.l25#13.e" to "Saltarse el permiso no solo es ilegal: también deja sin efecto el rescate y el seguro. O se cumple, o se cambia de ruta; no se puede confiar en la suerte.",
    "q.l25#14.p" to "¿Por qué hay que recoger la información médica y de medicación antes de salir?",
    "q.l25#14.o0" to "Porque en una urgencia hay que conocer contraindicaciones y antecedentes, y la altitud amplifica el riesgo de patologías previas",
    "q.l25#14.o1" to "Para conseguir un descuento en el seguro",
    "q.l25#14.o2" to "Para hacer los grupos",
    "q.l25#14.o3" to "No tiene utilidad práctica",
    "q.l25#14.e" to "Por encima de 5.000 m una infección común o una alergia medicamentosa puede convertirse en urgencia. La información se recoge antes de salir, no preguntando uno por uno cuando ya ha pasado algo.",
)
